   // Helper: Auto-sync batches from admin_batch_imports to batches & batch_items
   const syncAdminBatchImportsToBatches = async () => {
      try {
         const startOfDay = batchDateFilter ? new Date(batchDateFilter + 'T00:00:00') : new Date();
         let endOfDay = batchDateFilter ? new Date(batchDateFilter + 'T23:59:59.999') : new Date();
         if (!batchDateFilter) {
            startOfDay.setHours(0, 0, 0, 0);
            endOfDay.setHours(23, 59, 59, 999);
         }

         const importsRef = collection(db, 'admin_batch_imports');
         const qImports = fsQuery(
            importsRef,
            where('timestamp', '>=', startOfDay.toISOString()),
            where('timestamp', '<=', endOfDay.toISOString())
         );
         const querySnapshot = await getDocs(qImports);
         const adminBatches: any[] = [];
         querySnapshot.forEach(docSnap => {
            adminBatches.push({ id: docSnap.id, ...docSnap.data() });
         });

         if (!adminBatches || adminBatches.length === 0) return 0;

         const batchNos = Array.from(new Set(adminBatches.map((b: any) => b.batchId).filter(Boolean)));
         if (batchNos.length === 0) return 0;

         // Check existing batches in chunks to prevent URL length overflow
         const existingSet = new Set<string>();
         for (let i = 0; i < batchNos.length; i += 50) {
            const chunk = batchNos.slice(i, i + 50);
            const { data: existingBatches } = await supabase
               .from('batches')
               .select('batch_no')
               .in('batch_no', chunk);
            (existingBatches || []).forEach((b: any) => existingSet.add(b.batch_no));
         }

         // Deduplicate missing by batchId
         const missingMap = new Map<string, any>();
         for (const b of adminBatches) {
            if (b.batchId && !existingSet.has(b.batchId) && !missingMap.has(b.batchId)) {
               missingMap.set(b.batchId, b);
            }
         }
         const missing = Array.from(missingMap.values());
         if (missing.length === 0) return 0;

         let syncedCount = 0;
         for (const m of missing) {
            const cleanCreatedAt = m.timestamp || new Date().toISOString();
            let batchId: string | undefined;

            // 1. Check if batch already exists in database
            const { data: existingBatch } = await supabase
               .from('batches')
               .select('id')
               .eq('batch_no', m.batchId)
               .maybeSingle();

            if (existingBatch?.id) {
               batchId = existingBatch.id;
            } else {
               // Insert new batch cleanly without on_conflict 406
               const { data: newBatch, error: bErr } = await supabase
                  .from('batches')
                  .insert({
                     batch_no: m.batchId,
                     excel_filename: m.excelFilename || m.batchId,
                     created_by: m.staffName || 'admin',
                     created_at: cleanCreatedAt
                  })
                  .select('id')
                  .maybeSingle();

               if (bErr) {
                  const { data: retryBatch } = await supabase
                     .from('batches')
                     .select('id')
                     .eq('batch_no', m.batchId)
                     .maybeSingle();
                  batchId = retryBatch?.id;
               } else {
                  batchId = newBatch?.id;
               }
            }

            if (!batchId) continue;

            // Check if batch_items already exist for this batch_id
            const { count: existingItemsCount } = await supabase
               .from('batch_items')
               .select('id', { count: 'exact', head: true })
               .eq('batch_id', batchId);

            if ((existingItemsCount || 0) > 0) {
               existingSet.add(m.batchId);
               continue;
            }

            let bcs: string[] = [];
            if (Array.isArray(m.barcodes)) {
               bcs = m.barcodes;
            } else if (typeof m.barcodes === 'string') {
               try { bcs = JSON.parse(m.barcodes); } catch (_) { bcs = []; }
            }

            const cleanBarcodes = Array.from(new Set(bcs.map((b: any) => (b || '').toString().trim().toUpperCase()).filter(Boolean)));

            if (cleanBarcodes.length > 0) {
               const INSERT_CHUNK = 500;
               for (let i = 0; i < cleanBarcodes.length; i += INSERT_CHUNK) {
                  const chunk = cleanBarcodes.slice(i, i + INSERT_CHUNK);
                  const { error: insItemErr } = await supabase.from('batch_items').insert(
                     chunk.map(bc => ({
                        batch_id: batchId,
                        barcode: bc,
                        created_at: cleanCreatedAt
                     }))
                  );
                  if (insItemErr) {
                     console.warn("Notice: Batch items insert notice:", insItemErr.message || insItemErr);
                  }
               }
            }
            existingSet.add(m.batchId);
            syncedCount++;
         }
         return syncedCount;
      } catch (err) {
         console.warn("syncAdminBatchImportsToBatches notice:", err);
         return 0;
      }
   };

   // 3b. Real-time Batch Search
   useEffect(() => {
      if ((activeView === 'BATCH_DATA' || activeView === 'BATCH_DATA_2' || activeView === 'BATCH_DATA_3') && activeBatchTab === 'SUMMARY') {
         const fetchBatchSummaryData = async () => {
            setIsLoadingBatchSummary(true);
            try {
               await syncAdminBatchImportsToBatches();
               let query = supabase.from('batches').select('*', { count: 'exact' });

               if (batchDateFilter) {
                  const startOfDay = new Date(batchDateFilter + 'T00:00:00');
                  let endOfDay = new Date(batchDateFilter + 'T23:59:59');
                  if (batchTimeFilter) {
                     const [hours, minutes, seconds] = batchTimeFilter.split(':');
                     startOfDay.setHours(parseInt(hours, 10), parseInt(minutes, 10), parseInt(seconds || '0', 10), 0);
                     endOfDay = new Date(startOfDay.getTime());
                     endOfDay.setHours(parseInt(hours, 10), parseInt(minutes, 10), parseInt(seconds || '0', 10), 999);
                  } else {
                     startOfDay.setHours(0, 0, 0, 0);
                     endOfDay.setHours(23, 59, 59, 999);
                  }
                  query = query.gte('created_at', startOfDay.toISOString()).lte('created_at', endOfDay.toISOString());
               }

               if (batchSearchMode === 'MASS' && batchMassSearchApplied.length > 0) {
                   const { data: matchedItems } = await supabase
                      .from('batch_items')
                      .select('batch_id')
                      .in('barcode', batchMassSearchApplied.slice(0, 1000));
                   const matchedBatchIds = Array.from(new Set((matchedItems || []).map((m: any) => m.batch_id).filter(Boolean)));
                   if (matchedBatchIds.length > 0) {
                      query = query.in('id', matchedBatchIds);
                   } else {
                      query = query.in('id', ['00000000-0000-0000-0000-000000000000']);
                   }
                } else if (batchSearch) {
                   const fuzzySearch = batchSearch.trim().replace(/\s+/g, '%');
                   query = query.or(`batch_no.ilike.%${fuzzySearch}%,excel_filename.ilike.%${fuzzySearch}%`);
                }

               const { data: batches, error } = await query.order('created_at', { ascending: false }).limit(500);
               if (error) {
                  console.error("Error fetching batches for summary:", error);
                  setIsLoadingBatchSummary(false);
                  return;
               }
               const summaryData = batches || [];
               
                // Pre-fill Leader Staff and Auto-Check Progress efficiently
                // Pre-fill Leader Staff and Auto-Check Progress efficiently
                if (summaryData.length > 0) {
                   // 1. Fetch all batch items for these batches in chunked batch_id queries (max 50 per query)
                   const batchIds = summaryData.map((b: any) => b.id);
                   const batchChunks: string[][] = [];
                   for (let i = 0; i < batchIds.length; i += 15) {
                      batchChunks.push(batchIds.slice(i, i + 15));
                   }
                   const itemResults = await Promise.all(
                      batchChunks.map(chunk =>
                         Promise.resolve(
                            supabase
                               .from('batch_items')
                               .select('barcode, batch_id')
                               .in('batch_id', chunk)
                         ).catch(() => ({ data: [] }))
                      )
                   );
                   const allItemsData: any[] = itemResults.flatMap((r: any) => r.data || []);

                   let scannedBarcodesMap = new Map();
                   const batchToBarcodes: Record<string, string[]> = {};

                   if (allItemsData && allItemsData.length > 0) {
                      const allBarcodes = Array.from(new Set(allItemsData.map((item: any) => item.barcode).filter(Boolean)));
                      
                      // 2. Fetch all scans for these barcodes in safe 200 chunks (3 concurrent requests max)
                      const scanChunks: string[][] = [];
                      for (let i = 0; i < allBarcodes.length; i += 200) {
                         scanChunks.push(allBarcodes.slice(i, i + 200));
                      }
                      
                      for (let i = 0; i < scanChunks.length; i += 3) {
                         const slice = scanChunks.slice(i, i + 3);
                         const results = await Promise.all(
                            slice.map(chunk =>
                               Promise.resolve(
                                  supabase.from('scanned_items')
                                     .select('barcode, role')
                                     .in('barcode', chunk)
                                     .in('role', ['PICKER', 'PICKER_2', 'SORTIR_BATCH', 'CHECKER', 'OJOL'])
                               ).catch(() => ({ data: [], error: null }))
                            )
                         );
                         results.forEach(res => {
                            if (res?.data) {
                               res.data.forEach((row: any) => {
                                  if (!scannedBarcodesMap.has(row.barcode)) {
                                     scannedBarcodesMap.set(row.barcode, new Set());
                                  }
                                  scannedBarcodesMap.get(row.barcode).add(row.role);
                               });
                            }
                         });
                      }

                      // 3. Group barcodes by batch_id
                      allItemsData.forEach((item: any) => {
                         if (!batchToBarcodes[item.batch_id]) {
                            batchToBarcodes[item.batch_id] = [];
                         }
                         batchToBarcodes[item.batch_id].push(item.barcode);
                      });
                   }

                   const minBatchTime = Math.min(...summaryData.map((b: any) => b.created_at ? new Date(b.created_at).getTime() : Date.now()));
                   const maxBatchTime = Math.max(...summaryData.map((b: any) => b.created_at ? new Date(b.created_at).getTime() : Date.now()));
                    
                   const minD = new Date(minBatchTime - 2 * 86400000);
                   const maxD = new Date(maxBatchTime + 2 * 86400000);
                   const leaderDates = [];
                   for (let dt = new Date(minD); dt <= maxD; dt.setDate(dt.getDate() + 1)) {
                      const d = dt.getDate();
                      const m = dt.getMonth() + 1;
                      const y = dt.getFullYear();
                      leaderDates.push(`${d}/${m}/${y}`, `${String(d).padStart(2, '0')}/${String(m).padStart(2, '0')}/${y}`);
                   }

                   // Fetch all leader scans in the date range safely
                   const { data: leaderScansData } = await Promise.resolve(
                      supabase.from('leader_scan_2')
                         .select('barcode, assignees, timestamp, date')
                         .in('date', Array.from(new Set(leaderDates)))
                         .limit(5000)
                   ).catch(() => ({ data: [] }));
                   const leaderScans = leaderScansData || [];
                   
                   const progressMapUpdates: Record<string, any> = {};

                   for (const batch of summaryData) {
                      const barcodesInBatch = batchToBarcodes[batch.id] || [];
                      const totalCount = barcodesInBatch.length;
                      
                      let scannedCount = 0;
                      barcodesInBatch.forEach(bc => {
                         if (scannedBarcodesMap.has(bc)) {
                            scannedCount++;
                         }
                      });

                      progressMapUpdates[batch.id] = {
                         total: totalCount,
                         scanned: scannedCount,
                         loading: false
                      };
                   }

                   const normalize = (n: string) => (n || '').toLowerCase().replace(/\.(xlsx|xls|pdf|csv)$/i, '').replace(/\s+/g, '');
                    
                   // Pre-build index Map from normalized filename -> unique staff string in O(M)
                   const leaderStaffMap = new Map<string, string>();
                   if (leaderScans && leaderScans.length > 0) {
                      const filenameToStaffSet = new Map<string, Set<string>>();
                      leaderScans.forEach((s: any) => {
                         if (s.barcode && s.assignees) {
                            const normKey = normalize(s.barcode);
                            if (!filenameToStaffSet.has(normKey)) {
                               filenameToStaffSet.set(normKey, new Set());
                            }
                            const staffSet = filenameToStaffSet.get(normKey)!;
                            const arr = Array.isArray(s.assignees) ? s.assignees : [s.assignees];
                            arr.forEach((a: any) => { if (a) staffSet.add(String(a)); });
                         }
                      });
                      filenameToStaffSet.forEach((staffSet, normKey) => {
                         if (staffSet.size > 0) {
                            leaderStaffMap.set(normKey, Array.from(staffSet).join(', '));
                         }
                      });
                   }
                   
                   setBatchProgressMap(prev => {
                      const newMap = { ...prev };
                      summaryData.forEach((b: any) => {
                         let staffStr = '-';
                         if (b.excel_filename) {
                            const bName = normalize(b.excel_filename);
                            staffStr = leaderStaffMap.get(bName) || '-';
                         }

                         if (progressMapUpdates[b.id]) {
                           newMap[b.id] = {
                              total: progressMapUpdates[b.id].total,
                              scanned: progressMapUpdates[b.id].scanned,
                              staff: staffStr,
                              loading: false
                           };
                        } else {
                           newMap[b.id] = {
                              total: 0,
                              scanned: 0,
                              staff: staffStr,
                              loading: false
                           };
                        }
                     });
                     return newMap;
                  });

                  setBatchSummaryData(summaryData);
               } else {
                  setBatchSummaryData([]);
               }
              setBatchSummaryPage(1);
           } catch (err) {
              console.error('Error fetching batch summary:', err);
           } finally {
              setIsLoadingBatchSummary(false);
           }
        };
        fetchBatchSummaryData();
     }
  }, [activeView, activeBatchTab, batchDateFilter, batchTimeFilter, batchSearch, batchSearchMode, batchMassSearchApplied, refreshSummaryTrigger]);

  useEffect(() => {
     const delayDebounceFn = setTimeout(() => {
        if ((activeView === 'BATCH_DATA' || activeView === 'BATCH_DATA_2' || activeView === 'BATCH_DATA_3') && activeBatchTab === 'ITEMS') {
           fetchBatchData(batchPage);
        }
     }, 500);
     return () => clearTimeout(delayDebounceFn);
  }, [batchSearch, batchSearchMode, batchMassSearchApplied, batchDateFilter, batchTimeFilter, batchPage, activeView, activeBatchTab]);

   // --- DATA LOGISTIK: TAB 2 (DUAL-COLUMN PICKER VS LOGISTIK COMPARISON) FETCHERS ---
   const normalizeBarcodeKey = (raw: string): string => {
      if (!raw) return '';
      let s = String(raw).trim().toUpperCase();
      if (s.startsWith('0026')) s = s.slice(2);
      s = s.replace(/[\s\-_/\\,.]/g, '');
      if (s.startsWith('00') && s.length > 8) {
         s = s.substring(2);
      }
      return s;
   };

   // Helper: Reset all comparison filters back to default 'ALL' / empty
   const resetDualComparisonFilters = () => {
      setPickerLogistikMatchFilter('ALL');
      setPickerLogistikStaffFilter('ALL');
      setPickerLogistikTypeFilter('ALL');
      setPickerLogistikSearch('');
      setPickerLogistikPage(1);
      setCompLogistikMatchFilter('ALL');
      setCompLogistikSearch('');
      setCompLogistikPage(1);
   };

   // Helper: Fetch all active cancelled orders from master list (persists across all dates)
   const fetchAllActiveCancelledOrders = async (forceRefresh = false) => {
      if (!forceRefresh && cachedCancelledBarcodesRef.current && (Date.now() - cachedCancelledBarcodesRef.current.timestamp < 300000)) {
         return cachedCancelledBarcodesRef.current.list;
      }

      let allCancel: any[] = [];
      let offset = 0;
      let hasMore = true;

      while (hasMore) {
         const { data, error } = await supabase
            .from('cancelled_orders')
            .select('barcode, cancelled_at')
            .eq('is_active', true)
            .range(offset, offset + 999);

         if (error || !data || data.length === 0) break;
         allCancel.push(...data);
         if (data.length < 1000) break;
         offset += 1000;
      }

      cachedCancelledBarcodesRef.current = {
         list: allCancel,
         timestamp: Date.now()
      };
      return allCancel;
   };

   // Helper: Loop fetch all records from Supabase with selective columns for ultra-fast performance
   const fetchAllRecordsForRoles = async (roles: string[], startMs: number, endMs: number) => {
      let allData: any[] = [];
      let offset = 0;
      const batchSize = 500;
      let hasMore = true;

      while (hasMore) {
         let pageData: any[] | null = null;
         let pageError: any = null;

         for (let attempt = 0; attempt < 3; attempt++) {
            const { data, error } = await supabase
               .from('scanned_items')
               .select('id, barcode, employee_name, timestamp, role, menu_context')
               .in('role', roles)
               .gte('timestamp', startMs)
               .lte('timestamp', endMs)
               .order('timestamp', { ascending: true })
               .order('id', { ascending: true })
               .range(offset, offset + batchSize - 1);

            pageData = data;
            pageError = error;
            if (!error && data) break;
            await new Promise(r => setTimeout(r, 300));
         }

         if (pageError || !pageData || pageData.length === 0) {
            hasMore = false;
            break;
         }
         allData.push(...pageData);
         if (pageData.length < batchSize) {
            hasMore = false;
         } else {
            offset += batchSize;
         }
      }
      return allData;
   };

   // Helper: Fetch all active pending scans from Gudang & Leader LT3 (where status/menu_context is PENDING)
   const fetchAllActivePendingScans = async () => {
      try {
         const [gudangRes, leaderRes] = await Promise.all([
            supabase
               .from('scanned_items')
               .select('barcode, employee_name, timestamp, menu_context, status')
               .eq('role', 'GUDANG')
               .or('menu_context.eq.PENDING,status.eq.PENDING'),
            supabase
               .from('leader_pending_scans')
               .select('barcode, leader_profile, leader_name, timestamp, status')
               .eq('status', 'PENDING')
         ]);

         const pendingList: Array<{ barcode: string, staff: string, timestamp?: number, source: 'GUDANG' | 'LEADER' }> = [];
         if (gudangRes && gudangRes.data) {
            gudangRes.data.forEach((item: any) => {
               if (item.barcode) {
                  pendingList.push({
                     barcode: item.barcode,
                     staff: item.employee_name || 'Gudang LT3',
                     timestamp: item.timestamp,
                     source: 'GUDANG'
                  });
               }
            });
         }
         if (leaderRes && leaderRes.data) {
            leaderRes.data.forEach((item: any) => {
               if (item.barcode) {
                  pendingList.push({
                     barcode: item.barcode,
                     staff: item.leader_profile || item.leader_name || 'Leader LT3',
                     timestamp: item.timestamp,
                     source: 'LEADER'
                  });
               }
            });
         }
         return pendingList;
      } catch (err) {
         console.warn('Error fetching active pending scans:', err);
         return [];
      }
   };

   const loadDualComparisonData = async () => {
      setIsLoadingDualComparison(true);
      try {
         const effectiveDate = canManageDate ? filterDate : getTodayString();
         const start = new Date(effectiveDate + 'T00:00:00').getTime();
         const end = new Date(effectiveDate + 'T23:59:59.999').getTime();

         // 1. Fetch PICKER, OJOL, LOGISTIK, LEADER, CANCELLED ORDERS, ACTIVE PENDING LT3, and GUDANG CANCEL SCANS in parallel
         const [pickerRaw, ojolRaw, logistikRaw, leaderRes, cancelRows, pendingRaw, gudangCancelRes] = await Promise.all([
            fetchAllRecordsForRoles(['PICKER', 'Picker', 'PICKER_2'], start, end),
            fetchAllRecordsForRoles(['OJOL', 'Ojol'], start, end),
            fetchAllRecordsForRoles(['LOGISTIK', 'Logistik'], start, end),
            supabase
               .from('leader_scan_2')
               .select('barcode, leader_profile, leader_name')
               .gte('timestamp', start)
               .lte('timestamp', end),
            fetchAllActiveCancelledOrders(),
            fetchAllActivePendingScans(),
            supabase
               .from('scanned_items')
               .select('barcode')
               .gte('timestamp', start)
               .lte('timestamp', end)
               .or('menu_context.ilike.%cancel%,status.ilike.%cancel%')
         ]);

         // Helper: check if barcode has Order SN prefix (26, 27, 28, 29, 30, 31, 32, 33, 34, ... 40) with optional 00
         const isExcludedOrderSn = (barcode: any) => {
            let b = (barcode || '').toString().trim();
            if (/^00(?:2[6-9]|3\d|40)/.test(b)) {
               b = b.slice(2);
            }
            return /^(?:2[6-9]|3\d|40)/.test(b);
         };

         // Helper: check if staff name is REVAN or RACHEL
         const isRevanOrRachelStaff = (empName: any) => {
            const name = (empName || '').toString().trim().toUpperCase();
            return name === 'REVAN' || name === 'RACHEL' || name.startsWith('REVAN') || name.startsWith('RACHEL') || name.includes('REVAN') || name.includes('RACHEL');
         };

         // Filter out Picker items scanned by REVAN / RACHEL if barcode matches Order SN prefix (26... to 40...)
         const filteredPickerRaw = pickerRaw.filter((item: any) => {
            if (isRevanOrRachelStaff(item.employee_name) && isExcludedOrderSn(item.barcode)) {
               return false;
            }
            return true;
         });

         // Filter out OJOL Order SN barcodes (e.g. 26xxxxxxxx s/d 40xxxxxxxx)
         const filteredOjolRaw = ojolRaw.filter((item: any) => {
            return !isExcludedOrderSn(item.barcode);
         });

         // Combine Picker & Ojol data sorted by timestamp descending
         const combinedPickerRaw = [...filteredPickerRaw, ...filteredOjolRaw].sort((a: any, b: any) => (b.timestamp || 0) - (a.timestamp || 0));

         // Cancelled Barcodes Set (Persists across all dates via Master Cancel list + daily Gudang Cancel Scans)
         const cancelledBarcodeSet = new Set<string>();
         if (cancelRows && cancelRows.length > 0) {
            cancelRows.forEach((c: any) => {
               const raw = (c.barcode || '').trim().toUpperCase();
               const norm = normalizeBarcodeKey(raw);
               if (raw) {
                  cancelledBarcodeSet.add(raw);
                  if (raw.startsWith('0026')) cancelledBarcodeSet.add(raw.slice(2));
               }
               if (norm) cancelledBarcodeSet.add(norm);
            });
         }
         if (gudangCancelRes && gudangCancelRes.data) {
            gudangCancelRes.data.forEach((g: any) => {
               const raw = (g.barcode || '').trim().toUpperCase();
               const norm = normalizeBarcodeKey(raw);
               if (raw) {
                  cancelledBarcodeSet.add(raw);
                  if (raw.startsWith('0026')) cancelledBarcodeSet.add(raw.slice(2));
               }
               if (norm) cancelledBarcodeSet.add(norm);
            });
         }

         // Leader Map
         const leaderMap = new Map<string, string>();
         if (leaderRes && leaderRes.data) {
            leaderRes.data.forEach((l: any) => {
               const raw = (l.barcode || '').trim();
               const name = l.leader_profile || l.leader_name;
               if (raw && name) {
                  leaderMap.set(raw, name);
                  leaderMap.set(raw.toUpperCase(), name);
                  const norm = normalizeBarcodeKey(raw);
                  if (norm) leaderMap.set(norm, name);
               }
            });
         }

         // Pending LT3 Map & Set
         const pendingLt3Set = new Set<string>();
         const pendingLt3Map = new Map<string, { staff: string, source: 'GUDANG' | 'LEADER', timestamp?: number }>();
         if (pendingRaw && pendingRaw.length > 0) {
            pendingRaw.forEach((p: any) => {
               const raw = (p.barcode || '').toString().trim().toUpperCase();
               const norm = normalizeBarcodeKey(raw);
               const stripped0026 = raw.startsWith('0026') ? raw.slice(2) : raw;
               if (raw) {
                  pendingLt3Set.add(raw);
                  pendingLt3Set.add(stripped0026);
                  pendingLt3Map.set(raw, p);
                  pendingLt3Map.set(stripped0026, p);
               }
               if (norm) {
                  pendingLt3Set.add(norm);
                  pendingLt3Map.set(norm, p);
               }
            });
         }

         const pickerNormMap = new Map<string, any>();
         const logistikNormSet = new Set<string>();
         const staffSet = new Set<string>();
         let satuanCount = 0;
         let packingListCount = 0;
         let pickerCount = 0;
         let ojolCount = 0;
         let cancelPickerCount = 0;
         let pendingLt3PickerCount = 0;

         logistikRaw.forEach((item: any) => {
            const raw = (item.barcode || '').trim();
            const norm = normalizeBarcodeKey(raw);
            if (norm) {
               logistikNormSet.add(norm);
               logistikNormSet.add(raw.toUpperCase());
            }
         });

         combinedPickerRaw.forEach((item: any) => {
            if (item.employee_name) staffSet.add(item.employee_name.trim());
            const isOjol = (item.role || '').toUpperCase() === 'OJOL';
            if (isOjol) {
               ojolCount++;
            } else {
               pickerCount++;
            }
            const raw = (item.barcode || '').trim();
            if (raw.includes(' ')) packingListCount++;
            else satuanCount++;

            let rawBarcode = (item.barcode || '').toString().trim().toUpperCase();
            let stripped0026 = rawBarcode.startsWith('0026') ? rawBarcode.slice(2) : rawBarcode;
            const norm = normalizeBarcodeKey(rawBarcode);
            const isCancelled = cancelledBarcodeSet.has(rawBarcode) ||
                                cancelledBarcodeSet.has(stripped0026) ||
                                (norm && cancelledBarcodeSet.has(norm));

            if (!isCancelled && norm) {
               pickerNormMap.set(norm, item);
               pickerNormMap.set(rawBarcode.toUpperCase(), item);
            }
         });

         let pickerMatchCount = 0;
         const formattedPicker = combinedPickerRaw.map((item: any) => {
            let rawBarcode = (item.barcode || '').toString().trim();
            let stripped0026 = rawBarcode.startsWith('0026') ? rawBarcode.slice(2) : rawBarcode;
            if (rawBarcode.startsWith('0026')) {
               rawBarcode = rawBarcode.slice(2);
            }
            if (/^LXAD[^-]/i.test(rawBarcode)) rawBarcode = 'LXAD-' + rawBarcode.substring(4);
            if (/^JNAP[^-]/i.test(rawBarcode)) rawBarcode = 'JNAP-' + rawBarcode.substring(4);
            if (/^JNEB[^-]/i.test(rawBarcode)) rawBarcode = 'JNEB-' + rawBarcode.substring(4);

            const norm = normalizeBarcodeKey(rawBarcode);
            const isCancelled = cancelledBarcodeSet.has(rawBarcode.toUpperCase()) ||
                                cancelledBarcodeSet.has(stripped0026.toUpperCase()) ||
                                (norm ? cancelledBarcodeSet.has(norm) : false);

            if (isCancelled) {
               cancelPickerCount++;
            }

            const isMatch = !isCancelled && (logistikNormSet.has(norm) || logistikNormSet.has(rawBarcode.toUpperCase()));
            if (isMatch) pickerMatchCount++;

            // Check if item is held up in Pending LT3 (only if not cancelled and not matched in logistik)
            const pendingInfo = (!isCancelled && !isMatch)
               ? (pendingLt3Map.get(norm) || pendingLt3Map.get(rawBarcode.toUpperCase()) || pendingLt3Map.get(stripped0026.toUpperCase()))
               : null;
            const isPendingLt3 = !!pendingInfo;
            if (isPendingLt3) {
               pendingLt3PickerCount++;
            }

            const roleCategory = (item.role || '').toUpperCase() === 'OJOL' ? 'OJOL' : 'PICKER';

            return {
               ...item,
               barcode: rawBarcode,
               role_category: roleCategory,
               leader_profile: leaderMap.get(item.barcode) || leaderMap.get(rawBarcode) || leaderMap.get(norm) || '-',
               is_packing_list: rawBarcode.includes(' '),
               is_matched_logistik: isMatch,
               is_cancelled: isCancelled,
               is_pending_lt3: isPendingLt3,
               pending_lt3_staff: pendingInfo?.staff || null
            };
         });

         // 2. Identify unmatched non-cancelled Logistik barcodes on the current date
         const unmatchedLogistikBarcodes: string[] = [];
         logistikRaw.forEach((item: any) => {
            const raw = (item.barcode || '').toString().trim();
            const norm = normalizeBarcodeKey(raw);
            const stripped0026 = raw.startsWith('0026') ? raw.slice(2) : raw;
            const isCancelled = cancelledBarcodeSet.has(raw.toUpperCase()) ||
                                cancelledBarcodeSet.has(stripped0026.toUpperCase()) ||
                                (norm ? cancelledBarcodeSet.has(norm) : false);
            const isMatchToday = pickerNormMap.has(norm) || pickerNormMap.has(raw.toUpperCase());
            if (!isCancelled && !isMatchToday && raw) {
               unmatchedLogistikBarcodes.push(raw);
               if (norm && norm !== raw) unmatchedLogistikBarcodes.push(norm);
            }
         });

         // 3. Fast Historical Cross-Date Search for Unmatched Non-Cancelled Logistik items prior to current date
         const historicalPickerMap = new Map<string, any>();
         if (unmatchedLogistikBarcodes.length > 0) {
            const uniqueUnmatched = Array.from(new Set(unmatchedLogistikBarcodes));
            const chunkSize = 500;
            const chunkPromises = [];
            for (let i = 0; i < uniqueUnmatched.length; i += chunkSize) {
               const chunk = uniqueUnmatched.slice(i, i + chunkSize);
               chunkPromises.push(
                  supabase
                     .from('scanned_items')
                     .select('barcode, employee_name, timestamp, scan_date, role')
                     .in('role', ['PICKER', 'Picker', 'PICKER_2', 'OJOL', 'Ojol'])
                     .lt('timestamp', start)
                     .in('barcode', chunk)
                     .order('timestamp', { ascending: false })
               );
            }
            const chunkResults = await Promise.all(chunkPromises);
            chunkResults.forEach((res: any) => {
               if (res && res.data) {
                  res.data.forEach((pItem: any) => {
                     const isOjol = (pItem.role || '').toUpperCase() === 'OJOL';
                     const isPickerRevanRachel = !isOjol && isRevanOrRachelStaff(pItem.employee_name);
                     const bRaw = (pItem.barcode || '').trim();
                     if ((isOjol || isPickerRevanRachel) && isExcludedOrderSn(bRaw)) {
                        return; // Skip OJOL and REVAN/RACHEL order SNs from matching
                     }
                     const bNorm = normalizeBarcodeKey(bRaw);
                     const isCanc = cancelledBarcodeSet.has(bRaw.toUpperCase()) || (bNorm && cancelledBarcodeSet.has(bNorm));
                     if (!isCanc) {
                        if (bRaw && !historicalPickerMap.has(bRaw.toUpperCase())) {
                           historicalPickerMap.set(bRaw.toUpperCase(), pItem);
                        }
                        if (bNorm && !historicalPickerMap.has(bNorm)) {
                           historicalPickerMap.set(bNorm, pItem);
                        }
                     }
                  });
               }
            });
         }

         // 4. Format Logistik with 5 Dedicated Classification Types (CANCEL, SAME_DAY, PREV_DAY, PENDING_LT3, UNMATCH)
         let matchTodayCount = 0;
         let matchPrevCount = 0;
         let cancelLogistikCount = 0;
         let pendingLt3LogistikCount = 0;
         let pureUnmatchCount = 0;

         const sortedLogistikRaw = [...logistikRaw].sort((a: any, b: any) => (b.timestamp || 0) - (a.timestamp || 0));
         const formattedLogistik = sortedLogistikRaw.map((item: any) => {
            let rawBarcode = (item.barcode || '').toString().trim();
            let stripped0026 = rawBarcode.startsWith('0026') ? rawBarcode.slice(2) : rawBarcode;
            const norm = normalizeBarcodeKey(rawBarcode);
            const isCancelled = cancelledBarcodeSet.has(rawBarcode.toUpperCase()) ||
                                cancelledBarcodeSet.has(stripped0026.toUpperCase()) ||
                                (norm ? cancelledBarcodeSet.has(norm) : false);

            // Priority 1: Data Cancel (Terpisah total, tidak dihitung sebagai match)
            if (isCancelled) {
               cancelLogistikCount++;
               return {
                  ...item,
                  barcode: rawBarcode,
                  match_type: 'CANCEL' as const,
                  is_matched_picker: false,
                  is_cancelled: true,
                  picker_history_date: null,
                  picker_history_staff: null
               };
            }

            // Priority 2: Match Hari Ini
            const isMatchToday = pickerNormMap.has(norm) || pickerNormMap.has(rawBarcode.toUpperCase());
            if (isMatchToday) {
               matchTodayCount++;
               const pMatch = pickerNormMap.get(norm) || pickerNormMap.get(rawBarcode.toUpperCase());
               const staffName = pMatch?.employee_name || ((pMatch?.role || '').toUpperCase() === 'OJOL' ? 'Ojol' : 'Picker');
               return {
                  ...item,
                  barcode: rawBarcode,
                  match_type: 'SAME_DAY' as const,
                  is_matched_picker: true,
                  is_cancelled: false,
                  picker_history_date: effectiveDate,
                  picker_history_staff: staffName
               };
            }

            // Priority 3: Match Beda Hari (Riwayat sebelum hari ini)
            const histItem = historicalPickerMap.get(norm) || historicalPickerMap.get(rawBarcode.toUpperCase());
            if (histItem) {
               matchPrevCount++;
               let histDateStr = histItem.scan_date;
               if (!histDateStr && histItem.timestamp) {
                  const d = new Date(histItem.timestamp);
                  histDateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
               }
               const staffName = histItem.employee_name || ((histItem.role || '').toUpperCase() === 'OJOL' ? 'Ojol' : 'Picker');
               return {
                  ...item,
                  barcode: rawBarcode,
                  match_type: 'PREV_DAY' as const,
                  is_matched_picker: true,
                  is_cancelled: false,
                  picker_history_date: histDateStr || 'Tgl Riwayat',
                  picker_history_staff: staffName,
                  picker_history_timestamp: histItem.timestamp
               };
            }

            // Priority 4: Pending LT3 (Resi logistik yang tercatat sedang pending di Gudang/Leader LT3)
            const pendingInfo = pendingLt3Map.get(norm) || pendingLt3Map.get(rawBarcode.toUpperCase()) || pendingLt3Map.get(stripped0026.toUpperCase());
            if (pendingInfo) {
               pendingLt3LogistikCount++;
               return {
                  ...item,
                  barcode: rawBarcode,
                  match_type: 'PENDING_LT3' as const,
                  is_matched_picker: false,
                  is_cancelled: false,
                  picker_history_date: null,
                  picker_history_staff: null,
                  pending_staff: pendingInfo.staff
               };
            }

            // Priority 5: Pure Unmatch (Murni Belum pernah di-scan picker sama sekali)
            pureUnmatchCount++;
            return {
               ...item,
               barcode: rawBarcode,
               match_type: 'UNMATCH' as const,
               is_matched_picker: false,
               is_cancelled: false,
               picker_history_date: null,
               picker_history_staff: null
            };
         });

         const totalPicker = formattedPicker.length;
         const totalLogistik = formattedLogistik.length;
         const totalMatchLogistik = matchTodayCount + matchPrevCount;
         // Belum Logistik = Total Picker dikurangi Match, Cancel, dan Pending LT3
         const pickerUnmatchCount = Math.max(0, totalPicker - pickerMatchCount - cancelPickerCount - pendingLt3PickerCount);
         const matchPercentage = totalLogistik > 0 
            ? `${((totalMatchLogistik / totalLogistik) * 100).toFixed(1)}%` 
            : '0%';

         setAllPickerMasterList(formattedPicker);
         setAllLogistikMasterList(formattedLogistik);
         setLogistikPickerStaffList(Array.from(staffSet).sort());

         setCompComparisonStats({
            totalPicker,
            pickerCount,
            ojolCount,
            totalLogistik,
            matchCount: pickerMatchCount,
            matchTodayCount,
            matchPrevCount,
            pendingLt3Count: pendingLt3PickerCount + pendingLt3LogistikCount,
            pendingLt3PickerCount,
            pendingLt3LogistikCount,
            resolvedSusulanCount: 0,
            cancelLogistikCount,
            cancelPickerCount,
            totalMatchLogistik,
            pureUnmatchLogistik: pureUnmatchCount,
            pickerUnmatchCount,
            logistikUnmatchCount: pureUnmatchCount,
            matchPercentage,
            satuanCount,
            packingListCount,
            uniqueStaff: staffSet.size
         });
      } catch (err) {
         console.error('Error loading dual comparison data:', err);
      } finally {
         setIsLoadingDualComparison(false);
      }
   };

   // Filtered Picker List (Left Column) with Pending LT3, Cancel, Match, Unmatch
   const filteredPickerComparisonList = useMemo(() => {
      return allPickerMasterList.filter(item => {
         if (pickerLogistikMatchFilter === 'PERLU_DICARI' && (item.is_matched_logistik || item.is_cancelled)) return false;
         if (pickerLogistikMatchFilter === 'MATCH' && (!item.is_matched_logistik || item.is_cancelled)) return false;
         if (pickerLogistikMatchFilter === 'PENDING_LT3' && (!item.is_pending_lt3 || item.is_cancelled || item.is_matched_logistik)) return false;
         if (pickerLogistikMatchFilter === 'CANCEL' && !item.is_cancelled) return false;
         if (pickerLogistikMatchFilter === 'UNMATCH' && (item.is_matched_logistik || item.is_cancelled || item.is_pending_lt3)) return false;
         if (pickerLogistikStaffFilter !== 'ALL' && item.employee_name !== pickerLogistikStaffFilter) return false;
         if (pickerLogistikTypeFilter === 'PICKER' && item.role_category !== 'PICKER') return false;
         if (pickerLogistikTypeFilter === 'OJOL' && item.role_category !== 'OJOL') return false;
         if (pickerLogistikTypeFilter === 'PACKING_LIST' && !item.is_packing_list) return false;
         if (pickerLogistikTypeFilter === 'MANUAL' && item.is_packing_list) return false;
         if (pickerLogistikSearch.trim()) {
            const s = pickerLogistikSearch.trim().toLowerCase();
            const b = (item.barcode || '').toLowerCase();
            const e = (item.employee_name || '').toLowerCase();
            const l = (item.leader_profile || '').toLowerCase();
            const r = (item.role_category || '').toLowerCase();
            const isCanc = item.is_cancelled ? 'cancel data cancel batal' : '';
            const isPend = item.is_pending_lt3 ? 'pending lt3 gudang' : '';
            if (!b.includes(s) && !e.includes(s) && !l.includes(s) && !r.includes(s) && !isCanc.includes(s) && !isPend.includes(s)) return false;
         }
         return true;
      });
   }, [allPickerMasterList, pickerLogistikMatchFilter, pickerLogistikStaffFilter, pickerLogistikTypeFilter, pickerLogistikSearch]);

   // Paginated Picker List
   const paginatedPickerComparisonList = useMemo(() => {
      const from = (pickerLogistikPage - 1) * pickerLogistikRowsPerPage;
      const to = from + pickerLogistikRowsPerPage;
      return filteredPickerComparisonList.slice(from, to);
   }, [filteredPickerComparisonList, pickerLogistikPage, pickerLogistikRowsPerPage]);

   // Filtered Logistik List (Right Column) with 4-Level Match & Cancel filtering
   const filteredLogistikComparisonList = useMemo(() => {
      return allLogistikMasterList.filter(item => {
         if (compLogistikMatchFilter === 'MATCH_SAME_DAY' && item.match_type !== 'SAME_DAY') return false;
         if (compLogistikMatchFilter === 'MATCH_PREV_DAY' && item.match_type !== 'PREV_DAY') return false;
         if (compLogistikMatchFilter === 'CANCEL' && item.match_type !== 'CANCEL') return false;
         if (compLogistikMatchFilter === 'UNMATCH' && item.match_type !== 'UNMATCH') return false;
         if (compLogistikSearch.trim()) {
            const s = compLogistikSearch.trim().toLowerCase();
            const b = (item.barcode || '').toLowerCase();
            const r = (item.role || '').toLowerCase();
            const st = (item.picker_history_staff || '').toLowerCase();
            const dt = (item.picker_history_date || '').toLowerCase();
            const isCanc = item.is_cancelled ? 'cancel data cancel batal' : '';
            if (!b.includes(s) && !r.includes(s) && !st.includes(s) && !dt.includes(s) && !isCanc.includes(s)) return false;
         }
         return true;
      });
   }, [allLogistikMasterList, compLogistikMatchFilter, compLogistikSearch]);

   // Paginated Logistik List
   const paginatedLogistikComparisonList = useMemo(() => {
      const from = (compLogistikPage - 1) * compLogistikRowsPerPage;
      const to = from + compLogistikRowsPerPage;
      return filteredLogistikComparisonList.slice(from, to);
   }, [filteredLogistikComparisonList, compLogistikPage, compLogistikRowsPerPage]);

   // Dedicated Lists & Filters for Tab 3: Data Cancel Comparison
   const pickerCancelFullList = useMemo(() => {
      const logistikCancelSet = new Set(
         allLogistikMasterList.filter(l => l.is_cancelled).map(l => normalizeBarcodeKey(l.barcode))
      );
      return allPickerMasterList
         .filter(item => item.is_cancelled)
         .map(item => {
            const norm = normalizeBarcodeKey(item.barcode);
            const reachedLogistik = logistikCancelSet.has(norm);
            return {
               ...item,
               reachedLogistik
            };
         });
   }, [allPickerMasterList, allLogistikMasterList]);

   const filteredCancelPickerList = useMemo(() => {
      return pickerCancelFullList.filter(item => {
         if (cancelViewPickerStatus === 'INTERCEPTED' && item.reachedLogistik) return false;
         if (cancelViewPickerStatus === 'LOGISTIK' && !item.reachedLogistik) return false;
         if (cancelViewPickerStaff !== 'ALL' && item.employee_name !== cancelViewPickerStaff) return false;
         if (cancelViewPickerSearch.trim()) {
            const s = cancelViewPickerSearch.trim().toLowerCase();
            const b = (item.barcode || '').toLowerCase();
            const e = (item.employee_name || '').toLowerCase();
            if (!b.includes(s) && !e.includes(s)) return false;
         }
         return true;
      });
   }, [pickerCancelFullList, cancelViewPickerStatus, cancelViewPickerStaff, cancelViewPickerSearch]);

   const paginatedCancelPickerList = useMemo(() => {
      const from = (cancelViewPickerPage - 1) * cancelViewPickerRowsPerPage;
      return filteredCancelPickerList.slice(from, from + cancelViewPickerRowsPerPage);
   }, [filteredCancelPickerList, cancelViewPickerPage, cancelViewPickerRowsPerPage]);

   const logistikCancelFullList = useMemo(() => {
      return allLogistikMasterList.filter(item => item.is_cancelled);
   }, [allLogistikMasterList]);

   const filteredCancelLogistikList = useMemo(() => {
      return logistikCancelFullList.filter(item => {
         if (cancelViewLogistikSearch.trim()) {
            const s = cancelViewLogistikSearch.trim().toLowerCase();
            const b = (item.barcode || '').toLowerCase();
            if (!b.includes(s)) return false;
         }
         return true;
      });
   }, [logistikCancelFullList, cancelViewLogistikSearch]);

   const paginatedCancelLogistikList = useMemo(() => {
      const from = (cancelViewLogistikPage - 1) * cancelViewLogistikRowsPerPage;
      return filteredCancelLogistikList.slice(from, from + cancelViewLogistikRowsPerPage);
   }, [filteredCancelLogistikList, cancelViewLogistikPage, cancelViewLogistikRowsPerPage]);

   // Excel Export with Multiple Sheets (Picker, Logistik, Ringkasan)
   const handleExportDualComparisonExcel = () => {
      try {
         const effectiveDate = canManageDate ? filterDate : getTodayString();

         const pickerRows = allPickerMasterList.map((item: any, idx: number) => ({
            'No': idx + 1,
            'Tanggal & Waktu': new Date(item.timestamp).toLocaleString('id-ID'),
            'No Resi / Barcode': item.barcode,
            'Role / Tipe': item.role_category === 'OJOL' ? 'OJOL' : 'PICKER',
            'Staff': item.employee_name || '-',
            'Leader': item.leader_profile || '-',
            'Status Match Logistik': item.is_matched_logistik ? 'MATCH' : 'BELUM DI LOGISTIK',
            'Tipe Scan': item.is_packing_list ? 'PACKING LIST' : 'SATUAN'
         }));

         const logistikRows = allLogistikMasterList.map((item: any, idx: number) => {
            let statusText = 'BELUM DI-SCAN PICKER';
            if (item.match_type === 'SAME_DAY') {
               statusText = 'MATCH (HARI INI)';
            } else if (item.match_type === 'PREV_DAY') {
               statusText = `MATCH (TGL ${item.picker_history_date || '-'} OLEH ${item.picker_history_staff || '-'})`;
            }

            return {
               'No': idx + 1,
               'Tanggal & Waktu': new Date(item.timestamp).toLocaleString('id-ID'),
               'No Resi / Barcode': item.barcode,
               'Role / Context': item.role || 'LOGISTIK',
               'Status Match Picker': statusText,
               'Tgl Scan Picker Asli': item.picker_history_date || (item.match_type === 'SAME_DAY' ? effectiveDate : '-'),
               'Staff Picker Terkait': item.picker_history_staff || '-'
            };
         });

         const summaryRows = [
            { 'Kategori': 'Tanggal Data', 'Nilai': effectiveDate },
            { 'Kategori': 'Total Scan Picker & Ojol (Tanggal Terpilih)', 'Nilai': allPickerMasterList.length },
            { 'Kategori': 'Total Picker', 'Nilai': compComparisonStats.pickerCount },
            { 'Kategori': 'Total Ojol', 'Nilai': compComparisonStats.ojolCount },
            { 'Kategori': 'Total Data Logistik (Tanggal Terpilih)', 'Nilai': allLogistikMasterList.length },
            { 'Kategori': 'Match Hari Ini', 'Nilai': compComparisonStats.matchTodayCount },
            { 'Kategori': 'Match Riwayat / Beda Hari', 'Nilai': compComparisonStats.matchPrevCount },
            { 'Kategori': 'Total Logistik Ter-Match', 'Nilai': compComparisonStats.totalMatchLogistik },
            { 'Kategori': 'Persentase Match Logistik', 'Nilai': compComparisonStats.matchPercentage },
            { 'Kategori': 'Logistik Belum Pernah di-Picker/Ojol (Murni Belum)', 'Nilai': compComparisonStats.pureUnmatchLogistik },
            { 'Kategori': 'Picker/Ojol Belum di Logistik (Hari Ini)', 'Nilai': compComparisonStats.pickerUnmatchCount }
         ];

         const wb = XLSX.utils.book_new();
         XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(summaryRows), 'Ringkasan_Komparasi');
         XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(pickerRows), 'Data_Picker_Ojol');
         XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(logistikRows), 'Data_Logistik');

         XLSX.writeFile(wb, `Komparasi_Picker_vs_Logistik_${effectiveDate}.xlsx`);
         setSuccessToast(`Berhasil mengekspor komparasi Picker & Ojol vs Logistik (${pickerRows.length} Picker/Ojol & ${logistikRows.length} Logistik)!`);
      } catch (err: any) {
         console.error('Export dual comparison error:', err);
         alert('Gagal mengekspor data: ' + err.message);
      }
   };

   // Synchronized effect for Dual-Column Tab
   useEffect(() => {
      if (activeView === 'LOGISTIK_DATA' && (logistikActiveTab === 'PICKER' || logistikActiveTab === 'CANCEL')) {
         const timer = setTimeout(() => {
            loadDualComparisonData();
         }, 150);
         return () => clearTimeout(timer);
      }
   }, [activeView, filterDate, logistikActiveTab]);
   useEffect(() => {
      if (activeView === 'PACKING_DATA' || activeView === 'PACKING_2_DATA' || activeView === 'SORTIR_DATA' || activeView === 'LOGISTIK_DATA' || (activeView === 'PICKER_DATA' || activeView === 'CHECKER_DATA') || activeView === 'LEADER_2_DATA' || activeView === 'LEADER_PENDING_ADMIN' || activeView === 'GUDANG_PENDING' || activeView === 'GUDANG_READY' || activeView === 'GUDANG_CANCEL' || activeView === 'GUDANG_REPORT' || activeView === 'SCAN_ALL') {
         if (dateFilterMode === 'RANGE' && !hasExecutedRangeSearch) {
            return;
         }
         const timer = setTimeout(() => {
            fetchPackingData(page);
         }, 100);
         return () => clearTimeout(timer);
      }
   }, [page, rowsPerPage, filterPackingStaff, filterPackingShift, packingSearch, filterDate, dateFilterMode, appliedRangeStartDate, appliedRangeEndDate, hasExecutedRangeSearch, filterPackingRole, activeView, filterCancelOnly, filterPickerType, forcedDataSource]);

   // 4b. Fetching for Tracking Status Resi
   useEffect(() => {
      if (activeView === 'TRACK_RESI') {
         fetchTrackingData();
      }
   }, [activeView, filterDate]);

    // Handle Enter key for custom batch warning modal
    useEffect(() => {
       const handleKeyDown = (e: KeyboardEvent) => {
          if (isBatchConfirmModalOpen && e.key === 'Enter') {
             e.preventDefault();
             setIsBatchConfirmModalOpen(false);
             executeSaveBatch();
          }
       };
       if (isBatchConfirmModalOpen) {
          window.addEventListener('keydown', handleKeyDown);
       }
       return () => {
          window.removeEventListener('keydown', handleKeyDown);
       };
    }, [isBatchConfirmModalOpen]);


   // Helper untuk mencocokkan shift staf aktif
   const checkEmployeeMatchesShift = useCallback((empShift: string | null | undefined, filterShift: string): boolean => {
      if (!filterShift || filterShift === 'ALL') return true;
      if (!empShift) return false;
      if (empShift === filterShift) return true;
      return empShift.toLowerCase().includes(filterShift.toLowerCase());
   }, []);

   // 5. Dynamic Active Staff List Logic (HANYA STAF YANG SCAN PADA HARI / TANGGAL TERPILIH)
   useEffect(() => {
      const SUPPORTED_STAFF_VIEWS: AdminView[] = [
         'PACKING_DATA',
         'PACKING_2_DATA',
         'SORTIR_DATA',
         'PICKER_DATA',
         'CHECKER_DATA',
         'LEADER_2_DATA',
         'LEADER_PENDING_ADMIN',
         'GUDANG_PENDING',
         'GUDANG_READY',
         'GUDANG_CANCEL',
         'GUDANG_REPORT',
         'GUDANG_BUNDLING',
         'LOGISTIK_DATA',
         'SCAN_ALL'
      ];

      if (!SUPPORTED_STAFF_VIEWS.includes(activeView)) return;

      let isCancelled = false;

      // 1. Ambil master employees (state atau localStorage cache) untuk mapping shift
      let baseEmployees = employees;
      if (!baseEmployees || baseEmployees.length === 0) {
         try {
            const cached = localStorage.getItem('app_employees_cache');
            if (cached) baseEmployees = JSON.parse(cached);
         } catch (e) {}
      }

      const empShiftMap = new Map<string, string>();
      if (baseEmployees && baseEmployees.length > 0) {
         baseEmployees.forEach(e => {
            if (e.name) empShiftMap.set(e.name.trim().toLowerCase(), e.shift || '');
         });
      }

      const staffSet = new Set<string>();

      // Helper untuk validasi dan menambahkan nama yang cocok dengan filter shift
      const addStaffIfMatches = (rawName: string | null | undefined) => {
         if (!rawName || typeof rawName !== 'string') return;
         const trimmed = rawName.trim();
         if (!trimmed || trimmed === '-' || trimmed === 'Unknown' || trimmed === 'null' || trimmed === 'undefined') return;
         const empShift = empShiftMap.get(trimmed.toLowerCase());
         if (checkEmployeeMatchesShift(empShift, filterPackingShift)) {
            staffSet.add(trimmed);
         }
      };

      // 2. Tampilkan instan nama dari data halaman saat ini agar tidak delay/kosong di UI
      if (packingData && packingData.length > 0) {
         packingData.forEach((item: any) => {
            addStaffIfMatches(item.employee_name);
            addStaffIfMatches(item.leader_name);
            addStaffIfMatches(item.leader_profile);
            if (Array.isArray(item.team_members)) {
               item.team_members.forEach((m: any) => {
                  const mName = typeof m === 'string' ? m : m?.name;
                  addStaffIfMatches(mName);
               });
            }
         });
         if (staffSet.size > 0) {
            setPackingStaffList(Array.from(staffSet).sort((a, b) => a.localeCompare(b)));
         }
      }

      // 3. Tentukan rentang tanggal
      const isRange = canUse7DaysRangeFilter && dateFilterMode === 'RANGE' && hasExecutedRangeSearch;
      const startDateStr = isRange ? (appliedRangeStartDate || rangeStartDate) : (canManageDate ? filterDate : getTodayString());
      const endDateStr = isRange ? (appliedRangeEndDate || rangeEndDate) : startDateStr;
      const startMs = new Date(`${startDateStr}T00:00:00`).getTime();
      const endMs = new Date(`${endDateStr}T23:59:59.999`).getTime();

      // 4. Jika ada data di Firestore cache untuk tanggal tersebut, langsung ekstrak stafnya
      if (firestoreDayDataCache.has(startDateStr)) {
         const dayDocs = firestoreDayDataCache.get(startDateStr) || [];
         dayDocs.forEach((d: any) => {
            const r = (d.role || '').toUpperCase();
            let isRoleMatch = false;
            if (activeView === 'PACKING_DATA' || activeView === 'PACKING_2_DATA') {
               isRoleMatch = (r === 'PACKING' || r.includes('PACK'));
            } else if (activeView === 'SORTIR_DATA') {
               isRoleMatch = (r === 'SORTIR');
            } else if (activeView === 'PICKER_DATA') {
               isRoleMatch = (r === 'PICKER' || r.includes('PICK'));
            } else if (activeView === 'CHECKER_DATA') {
               isRoleMatch = (r === 'CHECKER' || r.includes('CHECK'));
            } else if (activeView === 'LOGISTIK_DATA') {
               isRoleMatch = (r === 'LOGISTIK');
            } else if (activeView.startsWith('GUDANG')) {
               isRoleMatch = (r === 'GUDANG' || r.includes('GUDANG'));
            } else {
               isRoleMatch = (filterPackingRole === 'ALL' || r === filterPackingRole);
            }

            if (isRoleMatch) {
               addStaffIfMatches(d.employee_name || d.admin_name || d.leader_name);
            }
         });
      }

      // 5. Query Supabase secara async di background untuk seluruh staf aktif (semua pagination)
      const fetchActiveStaff = async () => {
         try {
            let effectiveTable = 'scanned_items';
            const isLeader2 = activeView === 'LEADER_2_DATA';
            const isLeaderPending = activeView === 'LEADER_PENDING_ADMIN';
            if (isLeader2) effectiveTable = 'leader_scan_2';
            else if (isLeaderPending) effectiveTable = 'leader_pending_scans';

            let effectiveRole = filterPackingRole;
            if (activeView === 'PACKING_DATA' || activeView === 'PACKING_2_DATA') effectiveRole = 'PACKING';
            else if (activeView.startsWith('GUDANG')) effectiveRole = 'GUDANG';
            else if (activeView === 'SORTIR_DATA') effectiveRole = 'SORTIR';
            else if (activeView === 'PICKER_DATA') effectiveRole = 'PICKER';
            else if (activeView === 'LOGISTIK_DATA') effectiveRole = 'LOGISTIK';
            else if (activeView === 'CHECKER_DATA') effectiveRole = 'CHECKER';

            let menuContext: string | null = null;
            if (activeView === 'GUDANG_CANCEL') menuContext = 'CANCEL';
            else if (activeView === 'GUDANG_PENDING') menuContext = 'PENDING';
            else if (activeView === 'GUDANG_READY') menuContext = 'READY';
            else if (activeView === 'GUDANG_REPORT') menuContext = 'REPORT';
            else if (activeView === 'GUDANG_BUNDLING') menuContext = 'BUNDLING';

            const selectCols = (isLeader2 || isLeaderPending) ? 'leader_name, leader_profile' : 'employee_name, team_members';

            // Hitung total scan untuk menentukan chunk pagination (cepat, HEAD request)
            let countQuery = supabase
               .from(effectiveTable)
               .select('id', { count: 'exact', head: true })
               .gte('timestamp', startMs)
               .lte('timestamp', endMs);

            if (effectiveRole !== 'ALL' && !isLeader2 && !isLeaderPending) {
               countQuery = countQuery.eq('role', effectiveRole);
            }
            if (menuContext) {
               countQuery = countQuery.eq('menu_context', menuContext);
            }

            const { count } = await countQuery;
            if (isCancelled) return;

            const totalCount = count || 0;
            if (totalCount > 0) {
               const chunkSize = 1000;
               // Ambil sampai 50 chunk (50.000 data per hari) secara paralel
               const numChunks = Math.min(50, Math.ceil(totalCount / chunkSize));
               const chunkPromises = [];

               for (let i = 0; i < numChunks; i++) {
                  const from = i * chunkSize;
                  const to = from + chunkSize - 1;
                  let q = supabase
                     .from(effectiveTable)
                     .select(selectCols)
                     .gte('timestamp', startMs)
                     .lte('timestamp', endMs);

                  if (effectiveRole !== 'ALL' && !isLeader2 && !isLeaderPending) {
                     q = q.eq('role', effectiveRole);
                  }
                  if (menuContext) {
                     q = q.eq('menu_context', menuContext);
                  }
                  chunkPromises.push(q.range(from, to));
               }

               const results = await Promise.all(chunkPromises);
               if (isCancelled) return;

               results.forEach(res => {
                  if (res.data) {
                     res.data.forEach((row: any) => {
                        addStaffIfMatches(row.employee_name);
                        addStaffIfMatches(row.leader_name);
                        addStaffIfMatches(row.leader_profile);
                        if (Array.isArray(row.team_members)) {
                           row.team_members.forEach((m: any) => {
                              const mName = typeof m === 'string' ? m : m?.name;
                              addStaffIfMatches(mName);
                           });
                        }
                     });
                  }
               });
            }

            if (!isCancelled) {
               const sortedList = Array.from(staffSet).sort((a, b) => a.localeCompare(b));
               setPackingStaffList(sortedList);
               if (filterPackingStaff !== 'ALL' && sortedList.length > 0 && !sortedList.includes(filterPackingStaff)) {
                  setFilterPackingStaff('ALL');
               }
            }
         } catch (err) {
            console.error("Error loading active staff list:", err);
         }
      };

      fetchActiveStaff();

      // Fallback: Jika master employees masih kosong di memori, load dari DB di background tanpa lag
      if ((!baseEmployees || baseEmployees.length === 0) && !isCancelled) {
         supabase.from('employees').select('*').order('name').then(({ data }) => {
            if (data && !isCancelled) {
               setEmployees(data as Employee[]);
               try {
                  localStorage.setItem('app_employees_cache', JSON.stringify(data));
               } catch (e) {}
            }
         }).catch(() => {});
      }

      return () => {
         isCancelled = true;
      };
   }, [
      activeView,
      filterPackingShift,
      filterPackingRole,
      filterDate,
      canManageDate,
      dateFilterMode,
      canUse7DaysRangeFilter,
      appliedRangeStartDate,
      appliedRangeEndDate,
      rangeStartDate,
      rangeEndDate,
      hasExecutedRangeSearch,
      forcedDataSource,
      employees,
      checkEmployeeMatchesShift
   ]);

   // --- MEMOIZED FILTERS ---
   const allUsers = useMemo(() =>
      Object.keys(localPermissions),
      [localPermissions]);

   // Access Control Filter Logic
   const filteredUsers = useMemo(() =>
      allUsers.filter(email => {
         // Super Admin Check - Hide sensitive accounts if not super admin
         if (!isSuperAdmin && SENSITIVE_ACCOUNTS.includes(email)) {
            return false;
         }

         const matchesSearch = email.toLowerCase().includes(accessSearch.toLowerCase());
         let matchesRole = true;

         if (filterAccessRole !== 'ALL') {
            const userRoles = localPermissions[email] || [];
            if (filterAccessRole === 'NONE') {
               matchesRole = userRoles.length === 0;
            } else {
               matchesRole = userRoles.includes(filterAccessRole as UserRole);
            }
         }
         return matchesSearch && matchesRole;
      }),
      [allUsers, accessSearch, filterAccessRole, localPermissions, isSuperAdmin]);

   const accessStats = useMemo(() => {
      const total = allUsers.length;
      let withAccess = 0;
      let manualAllowed = 0;
      let blocked = 0;

      allUsers.forEach(email => {
         const roles = localPermissions[email] || [];
         if (roles.length > 0) withAccess++;
         if (localManualInput[email]) manualAllowed++;
         if (blockedUsers[email]) blocked++;
      });

      return { total, withAccess, manualAllowed, blocked, filteredCount: filteredUsers.length };
   }, [allUsers, localPermissions, localManualInput, blockedUsers, filteredUsers.length]);

   const filteredEmployees = useMemo(() =>
      employees.filter(emp => {
         const matchesSearch = emp.name.toLowerCase().includes(employeeSearch.toLowerCase());

         let matchesShift = true;
         if (filterShift === 'NONE') {
            matchesShift = !emp.shift;
         } else if (filterShift !== 'ALL') {
            matchesShift = emp.shift === filterShift;
         }

         let matchesRole = true;
         if (filterRole === 'NONE') matchesRole = !emp.allowed_roles || emp.allowed_roles.length === 0;
         else if (filterRole !== 'ALL') {
            if (!emp.allowed_roles || emp.allowed_roles.length === 0) matchesRole = false;
            else matchesRole = emp.allowed_roles.includes(filterRole);
         }
         return matchesSearch && matchesShift && matchesRole;
      }),
      [employees, employeeSearch, filterShift, filterRole]);

   const employeeStats = useMemo(() => {
      const total = employees.length;
      let withShift = 0;
      let withRoles = 0;
      let withTarget = 0;

      employees.forEach(emp => {
         if (emp.shift && emp.shift.trim() !== '') withShift++;
         if (emp.allowed_roles && emp.allowed_roles.length > 0) withRoles++;
         if (emp.daily_target && emp.daily_target > 0) withTarget++;
      });

      return { total, withShift, withRoles, withTarget, filteredCount: filteredEmployees.length };
   }, [employees, filteredEmployees.length]);

   const filteredAdmins = useMemo(() =>
      adminUsers.filter(admin => admin.username.toLowerCase().includes(adminSearch.toLowerCase())),
      [adminUsers, adminSearch]);

   const packingStats = useMemo(() => {
      if (packingData.length === 0) return { total: totalRows, activeStaff: 0, latest: '-' };
      const uniqueStaff = new Set(packingData.map(i => i.employee_name));
      const latestTime = new Date(packingData[0].timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      return { total: totalRows, activeStaff: uniqueStaff.size, latest: latestTime };
   }, [packingData, totalRows]);

   // Analytics khusus staff pada menu Data Packing 2
   const packing2StaffAnalytics = useMemo(() => {
      if (activeView !== 'PACKING_2_DATA' || filterPackingStaff === 'ALL') return null;

      const staffName = filterPackingStaff;
      const staffTotal = isHalfCountMode ? Math.ceil(totalRows / 2) : totalRows;
      const effectiveOverallTotal = isHalfCountMode ? Math.ceil(packing2OverallTotal / 2) : packing2OverallTotal;
      const overallTotal = effectiveOverallTotal > 0 ? effectiveOverallTotal : (staffTotal > 0 ? staffTotal : 1);
      const percentage = Math.min(100, Math.round((staffTotal / overallTotal) * 100)) || 0;

      // Hourly distribution dari packingData
      const hourlyMap: Record<number, number> = {};
      for (let h = 0; h < 24; h++) hourlyMap[h] = 0;

      let latestItem: any = null;
      let latestTimeStr = '-';

      if (packingData.length > 0) {
         latestItem = packingData[0];
         try {
            latestTimeStr = new Date(latestItem.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
         } catch (e) {
            latestTimeStr = '-';
         }

         packingData.forEach(item => {
            try {
               const date = new Date(item.timestamp);
               const hour = date.getHours();
               if (!isNaN(hour) && hour >= 0 && hour < 24) {
                  hourlyMap[hour] = (hourlyMap[hour] || 0) + 1;
               }
            } catch (e) {}
         });
      }

      // Cari jam-jam aktif
      const activeHourEntries = Object.entries(hourlyMap).map(([h, count]) => ({ hour: parseInt(h), count }));
      const activeHoursWithScans = activeHourEntries.filter(e => e.count > 0);
      const activeHoursCount = Math.max(1, activeHoursWithScans.length);
      
      // Rata-rata scan per jam aktif
      const avgPerHour = Math.round(staffTotal / activeHoursCount) || 0;

      // Tentukan rentang jam untuk grafik (misal 07:00 - 21:00 atau rentang data aktif)
      let minHour = 8;
      let maxHour = 20;
      if (activeHoursWithScans.length > 0) {
         const minActive = Math.min(...activeHoursWithScans.map(e => e.hour));
         const maxActive = Math.max(...activeHoursWithScans.map(e => e.hour));
         minHour = Math.max(0, Math.min(minHour, minActive));
         maxHour = Math.min(23, Math.max(maxHour, maxActive));
      }

      const hourlyChartData: { hour: string; rawHour: number; count: number }[] = [];
      let maxCountInHour = 1;
      for (let h = minHour; h <= maxHour; h++) {
         const count = hourlyMap[h] || 0;
         if (count > maxCountInHour) maxCountInHour = count;
         hourlyChartData.push({
            hour: `${h.toString().padStart(2, '0')}:00`,
            rawHour: h,
            count
         });
      }

      // Status produktivitas
      let speedTag = { label: '🟢 Normal', color: 'text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-500/10 border-emerald-500/20' };
      if (avgPerHour >= 120) {
         speedTag = { label: '⚡ Super Cepat', color: 'text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-500/10 border-amber-500/20' };
      } else if (avgPerHour >= 60) {
         speedTag = { label: '🔥 Sangat Produktif', color: 'text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-500/10 border-indigo-500/20' };
      }

      // Shift staff
      const staffEmployee = employees.find(e => e.name === staffName);
      const shift = staffEmployee?.shift || (packingData[0]?.shift) || 'Shift 1';

      // Inisial avatar
      const initials = staffName.split(' ').map((n: string) => n[0]).filter(Boolean).slice(0, 2).join('').toUpperCase() || 'ST';

      return {
         staffName,
         initials,
         shift,
         staffTotal,
         overallTotal,
         percentage,
         avgPerHour,
         activeHoursCount,
         hourlyChartData,
         maxCountInHour,
         speedTag,
         latestItem,
         latestTimeStr
      };
   }, [activeView, filterPackingStaff, totalRows, packing2OverallTotal, packingData, employees, isHalfCountMode]);

   // Access Table Visible Roles Logic
   const accessTableVisibleRoles = useMemo(() => {
      if (isSuperAdmin) return availableRoles;
      // Restrict view for non-super admins
      return ['SORTIR', 'PACKING', 'PICKER', 'CHECKER'];
   }, [availableRoles, isSuperAdmin]);


   // --- HANDLERS ---

   // New: Reset Filters Logic
   const handleResetPackingFilters = () => {
      setFilterPackingShift('ALL');
      setFilterPackingStaff('ALL');
      setPackingSearch('');
      setFilterPickerType('ALL'); // Reset picker type filter
      if (canManageDate) {
         setFilterDate(getTodayString());
      }
      setPage(1);
      setSelectedScanIds([]); // Clear selection on refresh
      setIsHalfCountMode(false); // Reset half count mode

      // Reset Role if in SCAN_ALL mode
      if (activeView === 'SCAN_ALL') {
         setFilterPackingRole('ALL');
      }
   };





   // Bulk Role Change Logic
   // Bulk Role Change Logic
   const handleLeader2BulkAction = async () => {
      if (selectedScanIds.length === 0) return;
      if (!leader2BulkStaff && !leader2BulkDate && !bulkChangeRoleTarget) {
         alert("Pilih staff, tanggal, atau type yang mau diubah!");
         return;
      }

      setIsDeletingRange(true);
      try {
         const updates: any = {};
         if (leader2BulkStaff) updates.leader_name = leader2BulkStaff;
         if (leader2BulkDate) {
            updates.date = leader2BulkDate;
            updates.timestamp = new Date(leader2BulkDate + 'T12:00:00').getTime();
         }
         if (bulkChangeRoleTarget) updates.scan_type = bulkChangeRoleTarget;

         for (const itemId of selectedScanIds) {
            const { error } = await supabase
               .from('leader_scan_2')
               .update(updates)
               .eq('id', itemId);

            try {
               await supabaseNew
                  .from('leader_scan_2')
                  .update(updates)
                  .eq('id', itemId);
            } catch (e) {}

            if (error) console.error("Error updating leader_scan_2 item " + itemId, error);
         }

         setSuccessToast(`Berhasil mengubah ${selectedScanIds.length} data.`);
         setSelectedScanIds([]);
         setLeader2BulkStaff('');
         setLeader2BulkDate('');
         setBulkChangeRoleTarget('PACKING');
         fetchPackingData();

      } catch (err: any) {
         alert("Gagal mengubah data: " + err.message);
      } finally {
         setIsDeletingRange(false);
      }
   };

   const handleDeleteLeader2Bulk = async () => {
      if (selectedScanIds.length === 0) return;
      if (!confirm(`Yakin ingin MENGHAPUS PERMANEN ${selectedScanIds.length} data terpilih?`)) return;

      setIsDeletingRange(true);
      try {
         for (const itemId of selectedScanIds) {
            const { error } = await supabase
               .from('leader_scan_2')
               .delete()
               .eq('id', itemId);

            try {
               await supabaseNew
                  .from('leader_scan_2')
                  .delete()
                  .eq('id', itemId);
            } catch (e) {}

            if (error) console.error("Error deleting leader_scan_2 item " + itemId, error);
         }
         setSuccessToast(`Berhasil menghapus ${selectedScanIds.length} data.`);
         setSelectedScanIds([]);
         fetchPackingData();

      } catch (err: any) {
         alert("Gagal menghapus data: " + err.message);
      } finally {
         setIsDeletingRange(false);
      }
   };

   const handleBulkChangeRole = async (targetRoleOverride?: string) => {
      // Use override if provided, otherwise fall back to state (for other views if needed)
      // For SCAN_ALL, we will always pass the override.
      const target = typeof targetRoleOverride === 'string' ? targetRoleOverride : bulkChangeRoleTarget;

      if (!target) { alert("Please select a target role."); return; }
      if (!confirm(`Are you sure you want to change ${selectedScanIds.length} items to ${target}?`)) return;

      const successfulIds: string[] = [];
      const failedItems: { id: string, reason: string }[] = [];
      const duplicatesDeleted: string[] = [];

      try {
         // Process each item individually to handle unique constraint violations
         for (const itemId of selectedScanIds) {
            try {
               const { error } = await supabase
                  .from(activeView === 'LEADER_2_DATA' ? 'leader_scan_2' : 'scanned_items')
                  .update(activeView === 'LEADER_2_DATA' ? { scan_type: target } : { role: target })
                  .eq('id', itemId);

               if (error) {
                  // Check if it's a duplicate key error
                  if (error.message?.includes('duplicate key') || error.code === '23505') {
                     // This item would create a duplicate if we change its role
                     // Option: Delete this item since target role already has this barcode
                     const { error: deleteError } = await supabase
                        .from(activeView === 'LEADER_2_DATA' ? 'leader_scan_2' : 'scanned_items')
                        .delete()
                        .eq('id', itemId);

                     if (deleteError) {
                        failedItems.push({ id: itemId, reason: 'Duplikat & gagal hapus: ' + deleteError.message });
                     } else {
                        duplicatesDeleted.push(itemId);
                     }
                  } else {
                     failedItems.push({ id: itemId, reason: error.message });
                  }
               } else {
                  successfulIds.push(itemId);
               }
            } catch (itemErr: any) {
               failedItems.push({ id: itemId, reason: itemErr.message });
            }
         }

         // Build result message
         let resultMessage = '';
         if (successfulIds.length > 0) {
            resultMessage += `✓ ${successfulIds.length} item berhasil diubah ke ${target}.\n`;
         }
         if (duplicatesDeleted.length > 0) {
            resultMessage += `✓ ${duplicatesDeleted.length} item duplikat dihapus (sudah ada di role ${target}).\n`;
         }
         if (failedItems.length > 0) {
            resultMessage += `✗ ${failedItems.length} item gagal diproses.`;
         }

         if (successfulIds.length > 0 || duplicatesDeleted.length > 0) {
            setSuccessToast(resultMessage.trim());
         }

         if (failedItems.length > 0 && failedItems.length <= 5) {
            alert(`Beberapa item gagal:\n${failedItems.map(f => f.reason).join('\n')}`);
         } else if (failedItems.length > 5) {
            alert(`${failedItems.length} item gagal diproses. Error pertama: ${failedItems[0].reason}`);
         }

         setSelectedScanIds([]);
         setBulkChangeRoleTarget('');
         // Refresh Data
         fetchPackingData();
      } catch (err: any) {
         alert("Failed to update roles: " + err.message);
      }
   };

   const buildPackingQuery = (shiftToNamesMap: Record<string, string[]>, countType: 'exact' | 'planned' | 'estimated' | null = null, options?: { startDate?: string, endDate?: string, overrideView?: AdminView, leaderBarcodes?: string[] | null }) => {
      const effectiveStartDate = options?.startDate || (canManageDate ? filterDate : getTodayString());

      // Cutoff Date Logic: Before March 1, 2026 -> Old DB, else -> New DB
      const activeClient = supabase;

      const effectiveEndDate = options?.endDate || effectiveStartDate;
      const targetView = options?.overrideView || activeView;

      let effectiveTable = 'scanned_items';
      let isLeader2 = targetView === 'LEADER_2_DATA';
      let isLeaderPending = targetView === 'LEADER_PENDING_ADMIN';
      if (isLeader2) effectiveTable = 'leader_scan_2';
      else if (isLeaderPending) effectiveTable = 'leader_pending_scans';

      let query = activeClient.from(effectiveTable).select('*', countType ? { count: countType } : undefined);

      const start = new Date(effectiveStartDate + 'T00:00:00');
      const end = new Date(effectiveEndDate + 'T23:59:59.999');
      query = query.gte('timestamp', start.getTime()).lte('timestamp', end.getTime());

      let effectiveRole = filterPackingRole;
      if (targetView === 'PACKING_DATA' || targetView === 'PACKING_2_DATA') effectiveRole = 'PACKING';
      else if (targetView === 'GUDANG_PENDING' || targetView === 'GUDANG_READY' || targetView === 'GUDANG_CANCEL' || targetView === 'GUDANG_REPORT' || targetView === 'GUDANG_BUNDLING') effectiveRole = 'GUDANG';
      else if (targetView === 'SORTIR_DATA') effectiveRole = 'SORTIR';
      else if (targetView === 'PICKER_DATA') effectiveRole = 'PICKER';
      else if (targetView === 'LOGISTIK_DATA') effectiveRole = 'LOGISTIK';
      else if (targetView === 'CHECKER_DATA') effectiveRole = 'CHECKER';
      else if (targetView === 'OJOL_DATA') effectiveRole = 'OJOL';
      else if (targetView === 'LEADER_2_DATA') effectiveRole = 'LEADER_2';
      else if (targetView === 'LEADER_PENDING_ADMIN') effectiveRole = 'LEADER_PENDING';

      // If exporting specific type, we force role
      if (options?.overrideView) {
         // Role is determined by overrideView logic above, filterPackingRole is ignored for exports unless we want to support filtering exports by role selected in UI? 
         // User Request implies "All in one... rentang tanggal... di masing2 menu". 
         // It implies exporting ALL data for that range. So we should probably Ignore UI search/staff filters for the bulk export, OR make it optional. 
         // Standard practice: Bulk export usually exports ALL matches for date range.
         if (targetView === 'PACKING_DATA') effectiveRole = 'PACKING';
      }

      if (effectiveRole !== 'ALL' && !isLeader2 && !isLeaderPending) query = query.eq('role', effectiveRole);

      // Keep existing UI filters only if NOT exporting (or if we want exports to respect UI filters? User Request implies "All in one... rentang tanggal... di masing2 menu". 
      // It implies exporting ALL data for that range. So we should probably Ignore UI search/staff filters for the bulk export, OR make it optional. 
      // Standard practice: Bulk export usually exports ALL matches for date range.
      if (packingSearch) {
         if (isLeaderPending) query = query.or(`barcode.ilike.%${packingSearch}%,leader_name.ilike.%${packingSearch}%,leader_profile.ilike.%${packingSearch}%`);
         else if (isLeader2) query = query.or(`barcode.ilike.%${packingSearch}%,leader_name.ilike.%${packingSearch}%`);
         else query = query.or(`barcode.ilike.%${packingSearch}%,employee_name.ilike.%${packingSearch}%`);
      }
      if (options?.leaderBarcodes) {
         query = query.in('barcode', options.leaderBarcodes);
      }

      if (filterPackingStaff !== 'ALL') {
         if (isLeaderPending) query = query.or(`leader_name.eq.${filterPackingStaff},leader_profile.eq.${filterPackingStaff}`);
         else if (isLeader2) query = query.eq('leader_name', filterPackingStaff);
         else if (targetView !== 'PICKER_DATA') query = query.eq('employee_name', filterPackingStaff);
      }

      // Cancel Filter Logic
      if (filterCancelOnly) {
         query = query.ilike('description', '%[CANCEL] Camera Scan%');
      }

      // Context Filter for Gudang Sub-menus
      if (targetView === 'GUDANG_CANCEL') {
         query = query.eq('menu_context', 'CANCEL');
      } else if (targetView === 'GUDANG_PENDING') {
         query = query.eq('menu_context', 'PENDING');
      } else if (targetView === 'GUDANG_READY') {
         query = query.eq('menu_context', 'READY');
      } else if (targetView === 'GUDANG_REPORT') {
         query = query.eq('menu_context', 'REPORT');
      } else if (targetView === 'GUDANG_BUNDLING') {
         query = query.eq('menu_context', 'BUNDLING');
      }

      if (filterPackingShift !== 'ALL') {
         const validNames = shiftToNamesMap[filterPackingShift] || [];
         if (validNames.length > 0) {
            query = isLeader2 ? query.in('leader_name', validNames) : query.in('employee_name', validNames);
         } else {
            query = query.eq('id', '00000000-0000-0000-0000-000000000000');
         }
      }

      // Picker Type Filter: Manual (no space) vs Packing List (has space)
      if (targetView === 'PICKER_DATA' && filterPickerType !== 'ALL') {
         if (filterPickerType === 'PACKING_LIST') {
            query = query.ilike('barcode', '% %');
         } else if (filterPickerType === 'MANUAL') {
            query = query.not('barcode', 'ilike', '% %');
         }
      }

      return query.order('timestamp', { ascending: false });
   };

   const reconcileGudangPendingScans = async () => {
      try {
         const { data: readyScans } = await supabase
            .from('scanned_items')
            .select('barcode')
            .eq('role', 'GUDANG')
            .eq('menu_context', 'READY')
            .limit(2000);

         if (!readyScans || readyScans.length === 0) return;
         const readyBarcodes = Array.from(new Set(readyScans.map(r => (r.barcode || '').trim().toUpperCase()).filter(Boolean)));
         if (readyBarcodes.length === 0) return;

         const CHUNK_SIZE = 100;
         for (let i = 0; i < readyBarcodes.length; i += CHUNK_SIZE) {
            const chunk = readyBarcodes.slice(i, i + CHUNK_SIZE);
            const { data: pendingToFix } = await supabase
               .from('scanned_items')
               .select('id')
               .eq('role', 'GUDANG')
               .or('menu_context.eq.PENDING,status.eq.PENDING')
               .in('barcode', chunk);

            if (pendingToFix && pendingToFix.length > 0) {
               const idsToUpdate = pendingToFix.map(p => p.id);
               await supabase
                  .from('scanned_items')
                  .update({
                     status: 'COMPLETED',
                     menu_context: 'READY'
                  })
                  .in('id', idsToUpdate);
            }
         }
      } catch (err) {
         console.warn("Gudang pending reconciliation notice:", err);
      }
   };

   const handleSearchDateRange = (explicitStart?: string, explicitEnd?: string) => {
      const start = explicitStart || rangeStartDate;
      const end = explicitEnd || rangeEndDate;
      setAppliedRangeStartDate(start);
      setAppliedRangeEndDate(end);
      setHasExecutedRangeSearch(true);
      setPage(1);
      if (activeView === 'OJOL_DATA') {
         fetchOjolData();
      } else {
         fetchPackingData(1, undefined, { startDate: start, endDate: end });
      }
   };

   const fetchPackingData = async (targetPage = page, forceSource?: 'SUPABASE' | 'FIRESTORE', explicitRangeOptions?: { startDate?: string, endDate?: string }) => {
      // Permission guards for different views
      if (activeView === 'PACKING_DATA' && !hasPermission('view_packing')) return;
      if (activeView === 'PACKING_2_DATA' && !hasPermission('view_packing_2')) return;
      if ((activeView === 'GUDANG_PENDING' || activeView === 'GUDANG_REPORT' || activeView === 'GUDANG_BUNDLING') && !hasPermission('view_gudang')) return;
      if (activeView === 'SORTIR_DATA' && !hasPermission('view_sortir') && !hasPermission('view_packing')) return;
      if ((activeView === 'PICKER_DATA' || activeView === 'CHECKER_DATA') && !hasPermission('view_picker')) return;
      if (activeView === 'LOGISTIK_DATA' && !hasPermission('view_logistik')) return;
      if (activeView === 'LEADER_2_DATA' && !hasPermission('view_leader_2')) return;
      if (activeView === 'LEADER_PENDING_ADMIN' && !hasPermission('view_leader_2')) return;
      if (activeView === 'SCAN_ALL' && !hasPermission('view_scan_all')) return;

      setIsLoadingPacking(true);
      try {
         if (activeView === 'GUDANG_PENDING' || activeView === 'GUDANG_READY') {
            await reconcileGudangPendingScans();
         }
         const effectiveDate = canManageDate ? filterDate : getTodayString();
         const activeClient = supabase;

         let empDataForMap = employees;
         if (empDataForMap.length === 0) {
            const { data, error } = await activeClient.from('employees').select('name, shift');
            if (!error) empDataForMap = data as Employee[] || [];
         }

         const shiftMap = new Map<string, string>();
         const shiftToNamesMap: Record<string, string[]> = {};

         if (empDataForMap) {
            empDataForMap.forEach((e: any) => {
               if (e.name) {
                  if (e.shift) {
                     shiftMap.set(e.name, e.shift);
                     if (!shiftToNamesMap[e.shift]) shiftToNamesMap[e.shift] = [];
                     shiftToNamesMap[e.shift].push(e.name);
                  }
               }
            });
         }

         let leaderBarcodes: string[] | null = null;
         if ((activeView === 'PICKER_DATA' || activeView === 'CHECKER_DATA') && filterPackingStaff !== 'ALL') {
            const { data: ld } = await supabase.from('leader_scan_2').select('barcode').eq('leader_profile', filterPackingStaff);
            if (ld) leaderBarcodes = ld.map((d: any) => d.barcode);
            else leaderBarcodes = ['NO_MATCH_XYZ_123']; // Prevent empty array from fetching all
         }

         let sbData: any[] = [];
         let sbCount = 0;

         // JIKA MODE RENTANG TANGGAL DIAKTIFKAN
         if (canUse7DaysRangeFilter && dateFilterMode === 'RANGE') {
            if (!hasExecutedRangeSearch && !explicitRangeOptions) {
               setPackingData([]);
               setTotalRows(0);
               setIsLoadingPacking(false);
               return;
            }

            const effectiveStart = explicitRangeOptions?.startDate || appliedRangeStartDate || rangeStartDate;
            const effectiveEnd = explicitRangeOptions?.endDate || appliedRangeEndDate || rangeEndDate;

            try {
               const query = buildPackingQuery(shiftToNamesMap, 'exact', {
                  startDate: effectiveStart,
                  endDate: effectiveEnd,
                  leaderBarcodes
               });
               const from = (targetPage - 1) * rowsPerPage;
               const to = from + rowsPerPage - 1;
               const res = await query.range(from, to);

               if (res.error) throw res.error;

               sbData = res.data || [];
               sbCount = res.count || 0;
            } catch (err: any) {
               console.error("Error fetching date range from Supabase:", err);
               alert("Gagal memuat data rentang tanggal dari Supabase: " + err.message);
               setIsLoadingPacking(false);
               return;
            }
         } else {
            const targetDateStr = effectiveDate;
            const startMs = new Date(`${targetDateStr}T00:00:00`).getTime();
            const endMs = new Date(`${targetDateStr}T23:59:59.999`).getTime();

            const effectiveSource = forceSource || forcedDataSource || 'SUPABASE';

            const supportedFallbackViews = [
               'PACKING_DATA', 'PACKING_2_DATA', 'SORTIR_DATA', 'PICKER_DATA', 
               'CHECKER_DATA', 'LOGISTIK_DATA', 'OJOL_DATA', 'GUDANG_PENDING', 
               'GUDANG_READY', 'GUDANG_REPORT', 'GUDANG_BUNDLING'
            ];

            // 1. Fetch Supabase Data
            if (effectiveSource !== 'FIRESTORE') {
            try {
               const query = buildPackingQuery(shiftToNamesMap, 'exact', { leaderBarcodes });
               const from = (targetPage - 1) * rowsPerPage;
               const to = from + rowsPerPage - 1;
               const res = await query.range(from, to);
               if (!res.error) {
                  sbData = res.data || [];
                  sbCount = res.count || 0;
               }
            } catch (sbErr) {
               console.warn("Supabase query warning:", sbErr);
            }
         }

         // 2. Decide whether to use Firestore
         // Firestore is used if:
         // a) User forced Firestore source ('FIRESTORE')
         // b) activeView is in supportedFallbackViews AND (Supabase count is 0 or low < 500 or cache exists)
         const isSupportedView = supportedFallbackViews.includes(activeView);
         const shouldCheckFirestore = isSupportedView && (effectiveSource === 'FIRESTORE');

         if (shouldCheckFirestore) {
            try {
               let targetRole = 'PACKING';
               if (activeView === 'PACKING_DATA' || activeView === 'PACKING_2_DATA') targetRole = 'PACKING';
               else if (activeView === 'SORTIR_DATA') targetRole = 'SORTIR';
               else if (activeView === 'PICKER_DATA') targetRole = 'PICKER';
               else if (activeView === 'CHECKER_DATA') targetRole = 'CHECKER';
               else if (activeView === 'LOGISTIK_DATA') targetRole = 'LOGISTIK';
               else if (activeView === 'OJOL_DATA') targetRole = 'OJOL';
               else if (activeView.startsWith('GUDANG')) targetRole = 'GUDANG';

               let dayDocs: any[] = [];
               if (firestoreDayDataCache.has(targetDateStr)) {
                  dayDocs = firestoreDayDataCache.get(targetDateStr)!;
               } else {
                  setFirestoreLoadingText('Mengambil data dari Firestore...');
                  const activeFsQuery = fsQuery(
                     collection(db, 'scanned_items'),
                     where('timestamp', '>=', startMs),
                     where('timestamp', '<=', endMs)
                  );
                  const fsSnap = await getDocs(activeFsQuery);
                  dayDocs = fsSnap.docs.map(docSnap => ({
                     id: docSnap.id,
                     ...(docSnap.data() as Record<string, any>)
                  }));
                  firestoreDayDataCache.set(targetDateStr, dayDocs);
                  setFirestoreLoadingText('');
               }

               let fsRoleItems: any[] = [];
               dayDocs.forEach(d => {
                  const r = (d.role || '').toUpperCase();
                  let isMatch = false;
                  if (targetRole === 'PACKING') {
                     isMatch = (r === 'PACKING' || r === 'PACKING_DATA' || r === 'PACKING_2' || r === 'PACKING_2_DATA' || r.includes('PACK'));
                  } else if (targetRole === 'SORTIR') {
                     isMatch = (r === 'SORTIR' || r === 'SORTIR_DATA');
                  } else if (targetRole === 'PICKER') {
                     isMatch = (r === 'PICKER' || r === 'PICKER_DATA' || r === 'PICKER_2' || r.includes('PICK'));
                  } else if (targetRole === 'CHECKER') {
                     isMatch = (r === 'CHECKER' || r === 'CHECKER_DATA' || r.includes('CHECK'));
                  } else if (targetRole === 'LOGISTIK') {
                     isMatch = (r === 'LOGISTIK' || r === 'LOGISTIK_DATA' || r.includes('LOGISTIK'));
                  } else if (targetRole === 'OJOL') {
                     isMatch = (r === 'OJOL' || r === 'OJOL_DATA' || r.includes('OJOL'));
                  } else if (targetRole === 'GUDANG') {
                     isMatch = (r === 'GUDANG' || r.includes('GUDANG'));
                  }

                  if (isMatch) {
                     let rawBarcode = (d.barcode || '').toString().trim();
                     if (rawBarcode && targetRole !== 'LOGISTIK' && rawBarcode.startsWith('0026')) {
                        rawBarcode = rawBarcode.slice(2);
                     }
                     if (/^LXAD[^-]/i.test(rawBarcode)) rawBarcode = 'LXAD-' + rawBarcode.substring(4);
                     if (/^JNAP[^-]/i.test(rawBarcode)) rawBarcode = 'JNAP-' + rawBarcode.substring(4);
                     if (/^JNEB[^-]/i.test(rawBarcode)) rawBarcode = 'JNEB-' + rawBarcode.substring(4);

                     const empName = d.employee_name || d.admin_name || d.leader_name || '-';
                     fsRoleItems.push({
                        ...d,
                        barcode: rawBarcode,
                        employee_name: empName,
                        shift: shiftMap.get(empName) || 'Unknown',
                        is_from_firestore: true
                     });
                  }
               });

               // Gunakan data Firestore jika Supabase 0 data ATAU data Firestore lebih lengkap
               if (effectiveSource === 'FIRESTORE' || fsRoleItems.length > 0) {
                  let filteredFs = fsRoleItems;
                  if (filterPackingStaff && filterPackingStaff !== 'ALL') {
                     filteredFs = filteredFs.filter(item => item.employee_name === filterPackingStaff || item.admin_name === filterPackingStaff);
                  }
                  if (filterPackingShift && filterPackingShift !== 'ALL') {
                     const validNames = new Set(shiftToNamesMap[filterPackingShift] || []);
                     filteredFs = filteredFs.filter(item => validNames.has(item.employee_name));
                  }
                  if (packingSearch) {
                     const term = packingSearch.toLowerCase();
                     filteredFs = filteredFs.filter(item =>
                        (item.barcode && item.barcode.toLowerCase().includes(term)) ||
                        (item.employee_name && item.employee_name.toLowerCase().includes(term)) ||
                        (item.admin_name && item.admin_name.toLowerCase().includes(term))
                     );
                  }

                  filteredFs.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));

                  const totalFsCount = filteredFs.length;
                  const from = (targetPage - 1) * rowsPerPage;
                  const to = from + rowsPerPage - 1;
                  const pageItems = filteredFs.slice(from, to + 1);

                  setPackingData(pageItems);
                  setTotalRows(totalFsCount);
                  setActiveDataSource('FIRESTORE');
                  setIsLoadingPacking(false);
                  return;
               }
            } catch (fsErr) {
               console.error("Error fetching fallback data from Firestore:", fsErr);
            }
         }

         // FALLBACK / SINKRONISASI FIRESTORE KHUSUS MENU LEADER_PENDING_ADMIN
         if (activeView === 'LEADER_PENDING_ADMIN') {
            try {
               const activeFsQuery = fsQuery(
                  collection(db, 'leader_pending_scans'),
                  where('timestamp', '>=', startMs),
                  where('timestamp', '<=', endMs)
               );

               const fsSnap = await getDocs(activeFsQuery);
               let fsItems: any[] = [];
               fsSnap.docs.forEach(docSnap => {
                  const d = docSnap.data() as Record<string, any>;
                  fsItems.push({
                     id: docSnap.id,
                     ...d,
                     barcode: (d.barcode || '').toString().trim(),
                     employee_name: d.leader_name || d.leader_profile || 'LEADER',
                     shift: shiftMap.get(d.leader_name) || 'Unknown',
                     role: 'LEADER_PENDING',
                     is_from_firestore: true
                  });
               });

               if ((sbCount === 0 || effectiveSource === 'FIRESTORE') && fsItems.length > 0) {
                  if (filterPackingStaff && filterPackingStaff !== 'ALL') {
                     fsItems = fsItems.filter(item => item.leader_name === filterPackingStaff || item.leader_profile === filterPackingStaff || item.employee_name === filterPackingStaff);
                  }
                  if (packingSearch) {
                     const term = packingSearch.toLowerCase();
                     fsItems = fsItems.filter(item =>
                        (item.barcode && item.barcode.toLowerCase().includes(term)) ||
                        (item.leader_name && item.leader_name.toLowerCase().includes(term)) ||
                        (item.leader_profile && item.leader_profile.toLowerCase().includes(term))
                     );
                  }

                  fsItems.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));

                  const totalFsCount = fsItems.length;
                  const from = (targetPage - 1) * rowsPerPage;
                  const to = from + rowsPerPage - 1;
                  const pageItems = fsItems.slice(from, to + 1);

                  setPackingData(pageItems);
                  setTotalRows(totalFsCount);
                  setActiveDataSource('FIRESTORE');
                  setIsLoadingPacking(false);
                  return;
               }
            } catch (fsErr) {
               console.error("Error fetching fallback leader pending data from Firestore:", fsErr);
            }
         }
         }

         // Default to Supabase data
         let enrichedData = (sbData || []).map((item: any) => {
            let rawBarcode = (item.barcode || '').toString().trim();
            const isLogistik = activeView === 'LOGISTIK_DATA' || item.role === 'LOGISTIK';

            if (rawBarcode && !isLogistik && rawBarcode.startsWith('0026')) {
               rawBarcode = rawBarcode.slice(2);
            }
            if (/^LXAD[^-]/i.test(rawBarcode)) {
               rawBarcode = 'LXAD-' + rawBarcode.substring(4);
            }
            if (/^JNAP[^-]/i.test(rawBarcode)) {
               rawBarcode = 'JNAP-' + rawBarcode.substring(4);
            }
            if (/^JNEB[^-]/i.test(rawBarcode)) {
               rawBarcode = 'JNEB-' + rawBarcode.substring(4);
            }

            if (activeView === 'LEADER_2_DATA') {
               return {
                  ...item,
                  barcode: rawBarcode,
                  employee_name: item.leader_name,
                  role: 'LEADER_2',
                  description: `[${item.assignment_mode || ''}] ${item.scan_type || ''}`,
                  destination: Array.isArray(item.assignees) ? item.assignees.join(', ') : '',
                  shift: shiftMap.get(item.leader_name) || 'Unknown'
               };
            }
            if (activeView === 'LEADER_PENDING_ADMIN') {
               const staffName = item.leader_name || item.leader_profile || item.employee_name || 'LEADER';
               return {
                  ...item,
                  barcode: rawBarcode,
                  employee_name: staffName,
                  leader_name: item.leader_name || staffName,
                  leader_profile: item.leader_profile || staffName,
                  role: 'LEADER_PENDING',
                  status: item.status || 'PENDING',
                  description: item.description || `[PENDING LEADER] ${item.leader_profile || ''}`,
                  destination: item.leader_profile || '',
                  shift: shiftMap.get(staffName) || '-'
               };
            }
            return {
               ...item,
               barcode: rawBarcode,
               shift: shiftMap.get(item.employee_name) || 'Unknown'
            };
         });

         // FETCH LEADER PROFILE IF PICKER
         if ((activeView === 'PICKER_DATA' || activeView === 'CHECKER_DATA') && enrichedData.length > 0) {
            const barcodes = enrichedData.map((d: any) => d.barcode);
            const { data: leaderData } = await activeClient
               .from('leader_scan_2')
               .select('barcode, leader_profile')
               .in('barcode', barcodes);

            if (leaderData) {
               const leaderMap = new Map();
               leaderData.forEach((ld: any) => leaderMap.set(ld.barcode, ld.leader_profile));
               enrichedData.forEach((d: any) => {
                  d.leader_profile = leaderMap.get(d.barcode) || '-';
               });
            } else {
               enrichedData.forEach((d: any) => d.leader_profile = '-');
            }
         }

         setPackingData(enrichedData);
         setTotalRows(sbCount || 0);
         setActiveDataSource('SUPABASE');
      } catch (err: any) {
         if (!err.message?.includes("Failed to fetch")) console.error("Fetch packing data error:", err.message);
      } finally {
         setIsLoadingPacking(false);
      }
   };

   const autoCompleteBatchInAdmin = async (batchId: string) => {
       try {
          const { data: batchData } = await supabase.from('batches').select('excel_filename, created_at').eq('id', batchId).maybeSingle();
          const { data: batchItems } = await supabase.from('batch_items').select('*').eq('batch_id', batchId);
          if (!batchItems || batchItems.length === 0) {
             return;
          }

          const barcodes = batchItems.map(i => i.barcode);
          const { data: existingScans } = await supabase
             .from('scanned_items')
             .select('barcode')
             .in('barcode', barcodes);

          const existingSet = new Set((existingScans || []).map(s => s.barcode.trim().toUpperCase()));
          const toAutoScan = batchItems.filter(it => !existingSet.has(it.barcode.trim().toUpperCase()));

          let assignedStaff = 'Admin Auto-Complete';
          if (toAutoScan.length > 0) {
             // Look up staff assigned to this batch by the leader
             if (batchData?.excel_filename) {
                const baseName = batchData.excel_filename.toLowerCase().replace(/\.(xlsx|xls|pdf|csv)\s*$/i, '').trim();
                const safeSearch = baseName.replace(/"/g, '').replace(/\s+/g, '%').replace(/,/g, '');
                
                const bTime = batchData.created_at ? new Date(batchData.created_at).getTime() : Date.now();
                const dt = new Date(bTime);
                const dStr1 = `${dt.getDate()}/${dt.getMonth() + 1}/${dt.getFullYear()}`;
                const dStr2 = `${String(dt.getDate()).padStart(2, '0')}/${String(dt.getMonth() + 1).padStart(2, '0')}/${dt.getFullYear()}`;
                const { data: leaderScans } = await Promise.resolve(
                   supabase.from('leader_scan_2')
                      .select('barcode, assignees, timestamp, date')
                      .in('date', [dStr1, dStr2])
                      .limit(500)
                ).catch(() => ({ data: [] }));
                   
                if (leaderScans && leaderScans.length > 0) {
                   const normalize = (n: string) => (n || '').toLowerCase().replace(/\.(xlsx|xls|pdf|csv)$/i, '').replace(/\s+/g, '');
                   const searchName = normalize(batchData.excel_filename);
                   
                   const matchingScans = leaderScans.filter(s => {
                      if (!s.barcode) return false;
                      if (s.timestamp && Math.abs(s.timestamp - bTime) > 2 * 24 * 60 * 60 * 1000) return false;
                      const sName = normalize(s.barcode);
                      return sName === searchName || sName.includes(searchName) || searchName.includes(sName);
                   });
                   const allStaff = matchingScans.map(s => s.assignees).flat().filter(Boolean);
                   const uniqueStaff = Array.from(new Set(allStaff));
                   if (uniqueStaff.length > 0) {
                      assignedStaff = uniqueStaff.join(', ');
                   }
                }
             }

             const bulkItems = toAutoScan.map(it => ({
                id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                timestamp: Date.now(),
                barcode: it.barcode,
                role: 'PICKER',
                status: 'COMPLETED' as const,
                description: `[AUTO-BATCH] ${it.msku || ''}`,
                destination: 'Page 1 (Auto)',
                priority: 'NORMAL' as const,
                employee_name: assignedStaff,
                user_email: currentAdmin?.email || 'admin@kalindo.com',
                menu_context: 'DEFAULT',
                excel_filename: batchData?.excel_filename || undefined
             }));

             await supabase.from('scanned_items').insert(bulkItems);
          }

          // Update local progress so it marks completed in UI, but DO NOT delete batches or batch_items
          setBatchProgressMap(prev => ({
             ...prev,
             [batchId]: {
                ...(prev[batchId] || {}),
                total: barcodes.length,
                scanned: barcodes.length,
                staff: assignedStaff,
                loading: false
             }
          }));
       } catch (err) {
          console.error('Error auto-completing batch in admin:', err);
       }
    };

   const checkBatchProgress = async (batchId: string) => {
      try {
         setBatchProgressMap(prev => ({ ...prev, [batchId]: { ...prev[batchId], loading: true } }));
         const { data: batchData } = await supabase.from('batches').select('excel_filename, created_at').eq('id', batchId).single();
         const { data: items } = await supabase.from('batch_items').select('barcode').eq('batch_id', batchId);
         if (!items || items.length === 0) {
            setBatchProgressMap(prev => ({ ...prev, [batchId]: { total: 0, scanned: 0, staff: '-', loading: false } }));
            return;
         }
         const barcodes = items.map(i => i.barcode);
         const total = barcodes.length;
         
         let sbScannedCount = 0;
         const CHUNK_SIZE = 200;
         for (let i = 0; i < barcodes.length; i += CHUNK_SIZE) {
            const chunk = barcodes.slice(i, i + CHUNK_SIZE);
            const { count } = await supabase.from('scanned_items')
               .select('*', { count: 'exact', head: true })
               .in('barcode', chunk)
               .in('role', ['PICKER', 'PICKER_2', 'SORTIR_BATCH', 'CHECKER', 'OJOL']);
            sbScannedCount += (count || 0);
         }

         let fsScannedCount = 0;
         try {
            if (barcodes.length > 0) {
               for (let i = 0; i < barcodes.length; i += 30) {
                  const chunk = barcodes.slice(i, i + 30);
                  const fsBatchQuery = fsQuery(
                     collection(db, 'scanned_items'),
                     where('barcode', 'in', chunk)
                  );
                  const fsBatchSnap = await getDocs(fsBatchQuery);
                  fsScannedCount += fsBatchSnap.docs.length;
               }
            }
         } catch (e) {}

         const scannedCount = Math.max(sbScannedCount || 0, fsScannedCount);

         let staffStr = '-';
         if (batchData?.excel_filename) {
            const baseName = batchData.excel_filename.toLowerCase().replace(/\.(xlsx|xls|pdf|csv)\s*$/i, '').trim();
            const safeSearch = baseName.replace(/"/g, '').replace(/\s+/g, '%').replace(/,/g, '');
            
            const bTime = batchData.created_at ? new Date(batchData.created_at).getTime() : Date.now();
            const dt = new Date(bTime);
            const dStr1 = `${dt.getDate()}/${dt.getMonth() + 1}/${dt.getFullYear()}`;
            const dStr2 = `${String(dt.getDate()).padStart(2, '0')}/${String(dt.getMonth() + 1).padStart(2, '0')}/${dt.getFullYear()}`;
            const { data: leaderScans } = await Promise.resolve(
               supabase.from('leader_scan_2')
                  .select('barcode, assignees, timestamp, date')
                  .in('date', [dStr1, dStr2])
                  .limit(500)
            ).catch(() => ({ data: [] }));
               
            if (leaderScans && leaderScans.length > 0) {
               const normalize = (n: string) => (n || '').toLowerCase().replace(/\.(xlsx|xls|pdf|csv)$/i, '').replace(/\s+/g, '');
               const searchName = normalize(batchData.excel_filename);
               
               const matchingScans = leaderScans.filter(s => {
                  if (!s.barcode) return false;
                  if (s.timestamp && Math.abs(s.timestamp - bTime) > 2 * 24 * 60 * 60 * 1000) return false;
                  const sName = normalize(s.barcode);
                  return sName === searchName || sName.includes(searchName) || searchName.includes(sName);
               });
               const allStaff = matchingScans.map(s => s.assignees).flat().filter(Boolean);
               const uniqueStaff = Array.from(new Set(allStaff));
               if (uniqueStaff.length > 0) staffStr = uniqueStaff.join(', ');
            }
         }
            
         setBatchProgressMap(prev => ({ ...prev, [batchId]: { total, scanned: scannedCount || 0, staff: staffStr, loading: false } }));
      } catch (err) {
         console.error('Error checking batch progress:', err);
         setBatchProgressMap(prev => ({ ...prev, [batchId]: { ...prev[batchId], loading: false } }));
      }
   };

   const handleCleanupAllCompletedBatches = async () => {
      if (batchSummaryData.length === 0) return;
      if (!window.confirm(`Proses & selesaikan otomatis semua batch yang sudah discan ≥ 3 resi? (${batchSummaryData.length} batch akan diperiksa)`)) return;
      
      setIsLoadingBatchSummary(true);
      try {
         let cleanedCount = 0;
         for (const batch of batchSummaryData) {
            const { data: items } = await supabase.from('batch_items').select('barcode').eq('batch_id', batch.id);
            if (!items || items.length === 0) {
               await supabase.from('batch_items').delete().eq('batch_id', batch.id);
               await supabase.from('batches').delete().eq('id', batch.id);
               cleanedCount++;
               continue;
            }
            const barcodes = items.map(i => i.barcode);
            const { count: scannedCount } = await supabase.from('scanned_items')
               .select('*', { count: 'exact', head: true })
               .in('barcode', barcodes)
               .in('role', ['PICKER', 'PICKER_2', 'SORTIR_BATCH', 'CHECKER', 'OJOL']);

            if ((scannedCount || 0) >= 3) {
               await autoCompleteBatchInAdmin(batch.id);
               cleanedCount++;
            }
         }
         alert(`Berhasil menyelesaikan dan membersihkan ${cleanedCount} batch!`);
      } catch (err) {
         console.error('Error cleaning completed batches:', err);
      } finally {
         setIsLoadingBatchSummary(false);
         // Refresh list
         setRefreshSummaryTrigger(prev => prev + 1);
         fetchBatchData();
      }
   };

   const fetchBatchData = async (targetPage = batchPage) => {
      if (!hasPermission('manage_batches')) return;
      setIsLoadingBatchData(true);
      setIsSelectAllBatchFiltered(false);
      try {
         await syncAdminBatchImportsToBatches();
         const startOfDay = batchDateFilter ? new Date(batchDateFilter + 'T00:00:00') : new Date();
         let endOfDay = batchDateFilter ? new Date(batchDateFilter + 'T23:59:59') : new Date();
         if (!batchDateFilter) {
            startOfDay.setHours(0, 0, 0, 0);
            endOfDay.setHours(23, 59, 59, 999);
         } else if (batchTimeFilter) {
            const [hours, minutes, seconds] = batchTimeFilter.split(':');
            startOfDay.setHours(parseInt(hours, 10), parseInt(minutes, 10), parseInt(seconds || '0', 10), 0);
            endOfDay = new Date(startOfDay.getTime());
            endOfDay.setHours(parseInt(hours, 10), parseInt(minutes, 10), parseInt(seconds || '0', 10), 999);
         }

         const startTs = startOfDay.getTime();
         const endTs = endOfDay.getTime();

         // 1. Fetch batches matching date range and search
         let batchesQuery = supabase
            .from('batches')
            .select('id, batch_no, excel_filename, created_at')
            .gte('created_at', startOfDay.toISOString())
            .lte('created_at', endOfDay.toISOString())
            .order('created_at', { ascending: false })
            .limit(500);

         if (batchSearch) {
            const fuzzySearch = batchSearch.trim().replace(/\s+/g, '%');
            batchesQuery = batchesQuery.or(`batch_no.ilike.%${fuzzySearch}%,excel_filename.ilike.%${fuzzySearch}%`);
         }

         const { data: batchesData, error: batchesErr } = await Promise.resolve(batchesQuery).catch(() => ({ data: [], error: null }));
         const batches = batchesData || [];

         if (batches.length === 0 && !batchSearch) {
            setBatchDataList([]);
            setBatchTotalRows(0);
            return;
         }

         const fsQueryScanned = fsQuery(
            collection(db, 'scanned_items'),
            where('timestamp', '>=', startTs),
            where('timestamp', '<=', endTs)
         );

         // Format dates for fast indexed lookup in leader_scan_2
         const filterDateStr = batchDateFilter || new Date().toISOString().split('T')[0];
         const [y, m, d] = filterDateStr.split('-');
         const dFormatted1 = `${parseInt(d, 10)}/${parseInt(m, 10)}/${y}`;
         const dFormatted2 = `${d}/${m}/${y}`;
         const dPrev = new Date(startOfDay.getTime() - 86400000);
         const dPrevStr1 = `${dPrev.getDate()}/${dPrev.getMonth() + 1}/${dPrev.getFullYear()}`;
         const dPrevStr2 = `${String(dPrev.getDate()).padStart(2, '0')}/${String(dPrev.getMonth() + 1).padStart(2, '0')}/${dPrev.getFullYear()}`;
         const leaderDates = Array.from(new Set([dFormatted1, dFormatted2, dPrevStr1, dPrevStr2]));

         // Fetch batch items per batch in chunks with created_at range filter to prevent full-table scan timeouts
         const batchIds = batches.map(b => b.id);
         const batchMap = new Map(batches.map(b => [b.id, b]));
         // Use CHUNK_SIZE = 15 batches so total items per query stays well under Supabase PostgREST 1000-row limit!
         const CHUNK_SIZE = 15;
         const batchChunks: string[][] = [];
         for (let i = 0; i < batchIds.length; i += CHUNK_SIZE) {
            batchChunks.push(batchIds.slice(i, i + CHUNK_SIZE));
         }

         const itemPromises = batchChunks.map(chunk => {
            let q = supabase
               .from('batch_items')
               .select('id, barcode, batch_id, created_at, msku, qty, order_id')
               .in('batch_id', chunk);

            // batch_items is already filtered by in('batch_id', chunk)
            return Promise.resolve(q).catch(() => ({ data: [] }));
         });

         const [itemResults, leaderRes] = await Promise.all([
            Promise.all(itemPromises),
            Promise.resolve(
               supabase
                  .from('leader_scan_2')
                  .select('barcode, assignees, date')
                  .in('date', leaderDates)
                  .limit(5000)
            ).catch(err => {
               console.warn("Notice: leader_scan_2 lookup skipped:", err);
               return { data: [], error: null };
            })
         ]);

         let itemsData: any[] = [];
         itemResults.forEach((res: any) => {
            if (res?.data) {
               res.data.forEach((item: any) => {
                  const bHeader = batchMap.get(item.batch_id);
                  itemsData.push({
                     ...item,
                     batches: {
                        batch_no: bHeader?.batch_no || '',
                        excel_filename: bHeader?.excel_filename || '',
                        created_at: bHeader?.created_at || item.created_at
                     }
                  });
               });
            }
         });

         if (batchSearchMode === 'MASS' && batchMassSearchApplied.length > 0) {
            const massSet = new Set(batchMassSearchApplied.map(b => b.trim().toUpperCase()));
            itemsData = itemsData.filter(it => it.barcode && massSet.has(it.barcode.trim().toUpperCase()));
         } else if (batchSearch) {
            const fuzzy = batchSearch.trim().toUpperCase();
            itemsData = itemsData.filter(it => 
               (it.barcode && it.barcode.toUpperCase().includes(fuzzy)) || 
               (it.batches?.batch_no && it.batches.batch_no.toUpperCase().includes(fuzzy)) || 
               (it.batches?.excel_filename && it.batches.excel_filename.toUpperCase().includes(fuzzy))
            );
         }

         const count = itemsData.length;

         if (itemsData.length === 0) {
            setBatchDataList([]);
            setBatchTotalRows(0);
            return;
         }

         // Extract all distinct barcodes from itemsData for accurate cross-matching
         const allBarcodes = Array.from(new Set((itemsData || []).map((i: any) => i.barcode?.trim().toUpperCase()).filter(Boolean)));

         // Build lookup maps in O(1) from Supabase scans with safe concurrency
         const scannedBarcodesMap = new Map<string, string>();

         if (allBarcodes.length > 0) {
            const CHUNK_SIZE = 500;
            const barcodeChunks: string[][] = [];
            for (let i = 0; i < allBarcodes.length; i += CHUNK_SIZE) {
               barcodeChunks.push(allBarcodes.slice(i, i + CHUNK_SIZE));
            }
            // 3 concurrent requests max to prevent HTTP/2 overload
            for (let i = 0; i < barcodeChunks.length; i += 4) {
               const slice = barcodeChunks.slice(i, i + 4);
               const scannedResults = await Promise.all(
                  slice.map(chunk =>
                     Promise.resolve(
                        supabase
                           .from('scanned_items')
                           .select('barcode, user_email, employee_name, role')
                           .in('role', ['PICKER', 'PICKER_2', 'OJOL'])
                           .in('barcode', chunk)
                     ).catch(() => ({ data: [], error: null }))
                  )
               );
               scannedResults.forEach(res => {
                  if (res?.data) {
                     res.data.forEach((s: any) => {
                        if (s.barcode) {
                           const key = s.barcode.trim().toUpperCase();
                           const staffName = s.employee_name || s.user_email || 'Scanned';
                           scannedBarcodesMap.set(key, staffName);
                        }
                     });
                  }
               });
            }
         }

         const normalize = (n: string) => (n || '').toLowerCase().replace(/\.(xlsx|xls|pdf|csv)$/i, '').replace(/\s+/g, '');
         const leaderStaffDataMap = new Map<string, string>();
         if (leaderRes?.data) {
            leaderRes.data.forEach((s: any) => {
               if (s.barcode && s.assignees) {
                  const normKey = normalize(s.barcode);
                  if (!leaderStaffDataMap.has(normKey)) {
                     const staffStr = Array.isArray(s.assignees) ? s.assignees.join(', ') : String(s.assignees);
                     leaderStaffDataMap.set(normKey, staffStr);
                  }
               }
            });
         }

         const items = (itemsData || []).map(item => {
            const cleanBarcode = (item.barcode || '').trim().toUpperCase();
            const bName = normalize(item.batches?.excel_filename);
            let staffStr = leaderStaffDataMap.get(bName) || null;
            if (scannedBarcodesMap.has(cleanBarcode)) {
               staffStr = scannedBarcodesMap.get(cleanBarcode) || 'Scanned';
            }
            return { ...item, staff: staffStr, is_scanned: scannedBarcodesMap.has(cleanBarcode) };
         });

         setBatchDataList(items);
         setBatchTotalRows(count || items.length);
      } catch (err: any) {
         console.error("Error fetching batch data:", err);
      } finally {
         setIsLoadingBatchData(false);
      }
   };

   const fetchAdminImports = async (): Promise<string[]> => {
      if (!batchDateFilter) {
         setAdminImports([]);
         setEarlierAdminResiMap(new Map());
         return [];
      }
      setIsLoadingAdminImports(true);
      try {
         const importsRef = collection(db, 'admin_batch_imports');
         let q = fsQuery(importsRef);
         
         const startOfDay = new Date(batchDateFilter + 'T00:00:00');
         let endOfDay = new Date(batchDateFilter + 'T23:59:59.999');

         if (batchTimeFilter) {
            const [hours, minutes, seconds] = batchTimeFilter.split(':');
            startOfDay.setHours(parseInt(hours, 10), parseInt(minutes, 10), parseInt(seconds || '0', 10), 0);
            endOfDay = new Date(startOfDay.getTime());
            endOfDay.setHours(parseInt(hours, 10), parseInt(minutes, 10), parseInt(seconds || '0', 10), 999);
         }
         q = fsQuery(q, where('timestamp', '>=', startOfDay.toISOString()), where('timestamp', '<=', endOfDay.toISOString()));

         // Also fetch earlier admin_batch_imports for cross-date matching (up to 7 days before, NON-BLOCKING in background)
         const lookbackCacheKey = batchDateFilter;
         const cachedLookback = earlierLookbackCacheRef.current.get(lookbackCacheKey);
         const now = Date.now();

         if (cachedLookback && (now - cachedLookback.timestamp < 10 * 60 * 1000)) {
            setEarlierAdminResiMap(cachedLookback.map);
         } else {
            // Asynchronous non-blocking background fetch
            (async () => {
               try {
                  const lookbackStart = new Date(startOfDay.getTime() - 7 * 24 * 60 * 60 * 1000);
                  const lookbackQ = fsQuery(
                     collection(db, 'admin_batch_imports'),
                     where('timestamp', '>=', lookbackStart.toISOString()),
                     where('timestamp', '<', startOfDay.toISOString())
                  );
                  const lookbackSnap = await getDocs(lookbackQ);
                  const eMap = new Map<string, string>();
                  lookbackSnap.forEach(docSnap => {
                     const data = docSnap.data();
                     const tsStr = data.timestamp;
                     if (tsStr && Array.isArray(data.barcodes)) {
                        const ts = new Date(tsStr);
                        const dStr = `${String(ts.getDate()).padStart(2, '0')}/${String(ts.getMonth() + 1).padStart(2, '0')}`;
                        data.barcodes.forEach((b: string) => {
                           const cleanB = (b || '').toString().trim().toUpperCase();
                           if (cleanB && !eMap.has(cleanB)) {
                              eMap.set(cleanB, dStr);
                           }
                        });
                     }
                  });
                  earlierLookbackCacheRef.current.set(lookbackCacheKey, { timestamp: Date.now(), map: eMap });
                  setEarlierAdminResiMap(eMap);
               } catch (pastErr) {
                  console.error("Failed to fetch earlier admin imports:", pastErr);
               }
            })();
         }

         // Fetch today's snapshot directly from Firestore
         let fetched: AdminBatchImport[] = [];
         try {
            const querySnapshot = await getDocs(q);
            querySnapshot.forEach(docSnap => {
               fetched.push({ id: docSnap.id, ...docSnap.data() } as AdminBatchImport);
            });
         } catch (fsErr) {
            console.error('Failed to fetch admin_batch_imports from Firestore:', fsErr);
         }

         fetched.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
         setAdminImports(fetched);
         
         // Auto-select staff with data if currently selected staff tab is empty
         if (fetched.length > 0) {
            const hasDataForCurrent = fetched.some(item => item.staffName === activeStaffTab);
            if (!hasDataForCurrent && activeStaffTab !== 'SEMUA') {
               const firstStaffWithData = fetched[0]?.staffName;
               if (firstStaffWithData) {
                  setActiveStaffTab(firstStaffWithData);
               }
            }
         }

         const barcodes = fetched.flatMap(item => item.barcodes || []).map(b => (b || '').toString().trim().toUpperCase()).filter(Boolean);
         return Array.from(new Set(barcodes));
      } catch (err: any) {
         console.error("Failed to fetch admin batch imports", err);
         return [];
      } finally {
         setIsLoadingAdminImports(false);
      }
   };

   const handleDeleteSingleRekap = async (item: AdminBatchImport) => {
      const batchTitle = item.excelFilename || item.batchId || 'item ini';
      if (!confirm(`Apakah Anda yakin ingin menghapus 1 data rekap batch "${batchTitle}"? Data ini akan dihapus dari Firestore dan Supabase secara permanen.`)) {
         return;
      }
      
      try {
         setIsLoadingAdminImports(true);

         // 1. Delete from Firestore
         await deleteDoc(doc(db, 'admin_batch_imports', item.id));

         // 2. Delete from Supabase
         try {
            // A. If barcodes are available, delete batch_items by barcode FIRST (uses idx_batch_items_barcode, super fast <200ms)
            if (item.barcodes && item.barcodes.length > 0) {
               for (let i = 0; i < item.barcodes.length; i += 500) {
                  const chunk = item.barcodes.slice(i, i + 500);
                  await supabase.from('batch_items').delete().in('barcode', chunk);
               }
            }

            // B. Delete batch record from batches table
            if (item.batchId) {
               const { data: matchedBatches } = await supabase.from('batches').select('id').eq('batch_no', item.batchId);
               const matchingIds = (matchedBatches || []).map(b => b.id);
               if (matchingIds.length > 0) {
                  if (!item.barcodes || item.barcodes.length === 0) {
                     await supabase.from('batch_items').delete().in('batch_id', matchingIds);
                  }
                  await supabase.from('batches').delete().in('id', matchingIds);
               }
            }
         } catch (sbErr) {
            console.warn("Supabase batch cleanup warning:", sbErr);
         }
         
         setSuccessToast(`Berhasil menghapus 1 data rekap: ${batchTitle}`);
         setSelectedRekapIds(prev => prev.filter(id => id !== item.id));
         setAdminImportsTrigger(prev => prev + 1);
         fetchBatchData();
      } catch (err: any) {
         console.error("Gagal menghapus single rekap:", err);
         alert("Gagal menghapus data: " + err.message);
      } finally {
         setIsLoadingAdminImports(false);
      }
   };

   const handleDeleteSelectedRekap = async () => {
      if (selectedRekapIds.length === 0) return;
      if (!confirm(`Apakah Anda yakin ingin menghapus ${selectedRekapIds.length} data rekap admin? Data ini akan dihapus dari Firestore dan Supabase secara permanen.`)) {
         return;
      }
      
      try {
         setIsLoadingAdminImports(true);

         const selectedItems = adminImports.filter(item => selectedRekapIds.includes(item.id));
         const batchNosToDelete = selectedItems.map(item => item.batchId).filter(Boolean);
         const barcodesToDelete = selectedItems.flatMap(item => item.barcodes || []).filter(Boolean);

         // 1. Delete from Firestore
         const batch = writeBatch(db);
         selectedRekapIds.forEach(id => {
            batch.delete(doc(db, 'admin_batch_imports', id));
         });
         await batch.commit();

         // 2. Delete from Supabase
         try {
            // A. Delete by barcode FIRST in chunks (fast, uses idx_batch_items_barcode)
            if (barcodesToDelete.length > 0) {
               for (let i = 0; i < barcodesToDelete.length; i += 500) {
                  const chunk = barcodesToDelete.slice(i, i + 500);
                  await supabase.from('batch_items').delete().in('barcode', chunk);
               }
            }

            // B. Delete parent batch records
            if (batchNosToDelete.length > 0) {
               const { data: matchedBatches } = await supabase.from('batches').select('id').in('batch_no', batchNosToDelete);
               const matchingIds = (matchedBatches || []).map(b => b.id);
               if (matchingIds.length > 0) {
                  if (barcodesToDelete.length === 0) {
                     await supabase.from('batch_items').delete().in('batch_id', matchingIds);
                  }
                  await supabase.from('batches').delete().in('id', matchingIds);
               }
            }
         } catch (sbErr) {
            console.warn("Supabase batch cleanup warning:", sbErr);
         }
         
         // Catat riwayat log penghapusan ke Supabase deletion_logs
         const rekapTargetSummary = selectedItems.map(item => `${item.staffName || 'Staff'}: ${item.excelFilename || item.batchId || 'Tanpa Nama'} (${item.jumlah || (item.barcodes?.length || 0)} resi)`).join(', ');
         await logDeletionAction({
            deleted_by: currentAdmin?.name || currentAdmin?.username || 'Staff',
            user_role: currentAdmin?.role || currentAdmin?.username || 'user',
            menu_name: activeView === 'BATCH_DATA_3' ? 'Batch management' : (activeView === 'BATCH_DATA_2' ? 'Progress Order' : 'Batch Management Old'),
            tab_name: 'Rekap Admin Print',
            item_count: selectedItems.length,
            target_summary: rekapTargetSummary,
            deleted_data: selectedItems
         });
         setSuccessToast(`Berhasil menghapus ${selectedRekapIds.length} data rekap.`);
         setSelectedRekapIds([]);
         setAdminImportsTrigger(prev => prev + 1);
         fetchBatchData();
      } catch (err: any) {
         console.error("Gagal menghapus rekap:", err);
         alert("Gagal menghapus data: " + err.message);
      } finally {
         setIsLoadingAdminImports(false);
      }
   };

   const handleClearSelectedAdminResi = async () => {
      if (selectedAdminResi.length === 0) return;
      const dateLabel = batchDateFilter ? `pada tanggal ${batchDateFilter}` : 'semua tanggal';
      if (!window.confirm(`Apakah Anda yakin ingin menghapus ${selectedAdminResi.length} resi admin terpilih ${dateLabel} dari Supabase (batch_items) & Firestore (admin_batch_imports)?\n\n- Resi pada tanggal lain TIDAK akan terhapus.\n- Resi pada role lain (Picker/Checker/Packing) TIDAK akan terhapus.`)) {
         return;
      }

      setIsLoadingAuditData(true);
      try {
         const selectedSet = new Set(selectedAdminResi.map(b => (b || '').toString().trim().toUpperCase()));
         const resiArray = Array.from(selectedSet);

         // 1. Delete selected barcodes from Supabase batch_items scoped to active batchDateFilter
         if (batchDateFilter) {
            const startOfDay = new Date(batchDateFilter + 'T00:00:00');
            const endOfDay = new Date(batchDateFilter + 'T23:59:59.999');

            for (let i = 0; i < resiArray.length; i += 500) {
               const chunk = resiArray.slice(i, i + 500);
               await supabase.from('batch_items')
                  .delete()
                  .in('barcode', chunk)
                  .gte('created_at', startOfDay.toISOString())
                  .lte('created_at', endOfDay.toISOString());
            }
         } else {
            for (let i = 0; i < resiArray.length; i += 500) {
               const chunk = resiArray.slice(i, i + 500);
               await supabase.from('batch_items').delete().in('barcode', chunk);
            }
         }

         // 2. Update/delete barcodes in Firestore admin_batch_imports (adminImports is already filtered by active date)
         for (const item of adminImports) {
            if (!item.id || !Array.isArray(item.barcodes)) continue;
            const hasTargetBarcode = item.barcodes.some(b => selectedSet.has((b || '').toString().trim().toUpperCase()));
            if (hasTargetBarcode) {
               const updatedBarcodes = item.barcodes.filter(b => !selectedSet.has((b || '').toString().trim().toUpperCase()));
               const docRef = doc(db, 'admin_batch_imports', item.id);
               if (updatedBarcodes.length === 0) {
                  await deleteDoc(docRef);
               } else {
                  await updateDoc(docRef, {
                     barcodes: updatedBarcodes,
                     jumlah: updatedBarcodes.length
                  });
               }
            }
         }

         setSuccessToast(`Berhasil menghapus ${selectedAdminResi.length} resi admin ${dateLabel} dari Supabase & Firestore.`);
         setSelectedAdminResi([]);
         setAdminImportsTrigger(prev => prev + 1);
         fetchBatchData();
         fetchAuditData(true);
      } catch (err: any) {
         console.error("Gagal menghapus resi admin terpilih:", err);
         alert("Gagal menghapus data: " + err.message);
      } finally {
         setIsLoadingAuditData(false);
      }
   };

   const fetchAuditData = async (forceRefresh = false, providedAdminBarcodes?: string[]) => {
      if (!batchDateFilter) {
         setAuditRoleData([]);
         setAuditPendingData([]);
         setLastAuditFetchTime(null);
         return;
      }
      const curReqId = ++auditRequestIdRef.current;
      try {
         const getDates = () => {
            if (!batchDateFilter) return null;
            const start = new Date(batchDateFilter + 'T00:00:00');
            let end = new Date(batchDateFilter + 'T23:59:59.999');
            if (batchTimeFilter) {
               const [h, m, s] = batchTimeFilter.split(':');
               start.setHours(+h, +m, +(s || '0'), 0);
               end = new Date(start.getTime());
               end.setHours(+h, +m, +(s || '0'), 999);
            }
            return { startMs: start.getTime(), endMs: end.getTime() };
         };

         const d = getDates();
         if (!d) return;
         const dateKey = `${d.startMs}_${d.endMs}`;
         const roleCacheKey = `${dateKey}_${auditRoleFilter}`;

         const adminBarcodes = providedAdminBarcodes || Array.from(new Set(
            adminImports.flatMap(item => item.barcodes || []).map(b => (b || '').toString().trim().toUpperCase()).filter(Boolean)
         )) as string[];

         const fetchOptimizedData = async (role: string, fetchGudangAudit = false) => {
            if (fetchGudangAudit) {
               // 1. Direct fast fetch for Gudang status scans on Same-Day (Ready / Cancel / Pending)
               const { data: sameDayGudangRows } = await supabase.from('scanned_items')
                  .select('id, barcode, timestamp, status, menu_context, role, description')
                  .or('status.eq.PENDING,menu_context.eq.PENDING,status.eq.READY,menu_context.eq.READY,status.eq.CANCEL,menu_context.eq.CANCEL,role.eq.GUDANG,role.eq.LEADER_PENDING')
                  .gte('timestamp', d.startMs)
                  .lte('timestamp', d.endMs)
                  .limit(5000);

               // 2. Identify unscanned admin barcodes to check cross-date Gudang status
               const sameDayGudangBc = new Set((sameDayGudangRows || []).map(r => (r.barcode || '').toString().trim().toUpperCase()).filter(Boolean));
               const unscannedAdminBc = adminBarcodes.filter(bc => !sameDayGudangBc.has(bc));

               let crossDateGudangRows: any[] = [];
               if (unscannedAdminBc.length > 0) {
                  const chunkSize = 200;
                  const chunks: string[][] = [];
                  for (let i = 0; i < unscannedAdminBc.length; i += chunkSize) {
                     chunks.push(unscannedAdminBc.slice(i, i + chunkSize));
                  }

                  // Process sequentially in small batches of 3 to prevent HTTP/2 connection overload
                  const CONCURRENT_LIMIT_G = 3;
                  for (let b = 0; b < chunks.length; b += CONCURRENT_LIMIT_G) {
                     const batchSlice = chunks.slice(b, b + CONCURRENT_LIMIT_G);
                     const batchResults = await Promise.all(
                        batchSlice.map(chunk =>
                           supabase.from('scanned_items')
                              .select('id, barcode, timestamp, status, menu_context, role, description')
                              .in('barcode', chunk)
                              .or('status.eq.PENDING,menu_context.eq.PENDING,status.eq.READY,menu_context.eq.READY,status.eq.CANCEL,menu_context.eq.CANCEL,role.eq.GUDANG,role.eq.LEADER_PENDING')
                        )
                     );
                     batchResults.forEach(res => {
                        if (res.data) crossDateGudangRows.push(...res.data);
                     });
                  }
               }

               // Merge and de-duplicate gudang rows
               const allGudang = [...(sameDayGudangRows || []), ...crossDateGudangRows];
               const uniqueGudang = new Map<string, any>();
               allGudang.forEach(row => {
                  const bc = (row.barcode || '').toString().trim().toUpperCase();
                  if (bc) {
                     const key = `${bc}_${row.status || ''}_${row.menu_context || ''}_${row.timestamp || 0}`;
                     if (!uniqueGudang.has(key)) {
                        uniqueGudang.set(key, row);
                     }
                  }
               });
               return Array.from(uniqueGudang.values());
            }

            const roleList = role === 'PICKER' 
               ? ['PICKER', 'Picker', 'OJOL', 'Ojol'] 
               : role === 'LOGISTIK'
               ? ['LOGISTIK', 'Logistik']
               : [role.toUpperCase(), role.charAt(0).toUpperCase() + role.slice(1).toLowerCase()];

            // A. Fetch Same-day Scans
            const buildAuditQuery = (isCount = false) => {
               let q = supabase.from('scanned_items');
               if (isCount) {
                  q = q.select('*', { count: 'exact', head: true });
               } else {
                  q = q.select('id, barcode, timestamp, status, menu_context, role');
               }
               if (roleList.length > 1) q = q.in('role', roleList);
               else q = q.eq('role', role);
               
               q = q.gte('timestamp', d.startMs).lte('timestamp', d.endMs);
               if (!isCount) {
                  q = q.order('timestamp', { ascending: false });
               }
               return q;
            };

            const [{ count: auditCount }, firstPage] = await Promise.all([
               buildAuditQuery(true),
               buildAuditQuery(false).range(0, 999)
            ]);

            let sameDayData: any[] = [...(firstPage.data || [])];

            if (auditCount && auditCount > 1000) {
               const chunkSize = 1000;
               const totalPages = Math.ceil(auditCount / chunkSize);
               const batchPromises = [];
               for (let j = 1; j < totalPages; j++) {
                  const from = j * chunkSize;
                  const to = from + chunkSize - 1;
                  batchPromises.push(buildAuditQuery(false).range(from, to));
               }
               const batchResults = await Promise.all(batchPromises);
               batchResults.forEach(r => {
                  if (r.data) sameDayData.push(...r.data);
               });
            }

            // B. Identify remaining admin barcodes not scanned on same day
            const sameDayBarcodes = new Set(
               sameDayData.map(item => (item.barcode || '').toString().trim().toUpperCase()).filter(Boolean)
            );
            const remainingBarcodes = adminBarcodes.filter(bc => !sameDayBarcodes.has(bc));

            // C. Fetch Cross-Date Scans (Past & Future) for remaining admin barcodes in parallel
            let crossDateData: any[] = [];
            if (remainingBarcodes.length > 0) {
               const chunkSize = 200;
               const chunks: string[][] = [];
               for (let i = 0; i < remainingBarcodes.length; i += chunkSize) {
                  chunks.push(remainingBarcodes.slice(i, i + chunkSize));
               }

               // Process sequentially in small batches of 3 to prevent HTTP/2 connection overload
               const CONCURRENT_LIMIT_R = 3;
               for (let b = 0; b < chunks.length; b += CONCURRENT_LIMIT_R) {
                  const batchSlice = chunks.slice(b, b + CONCURRENT_LIMIT_R);
                  const batchResults = await Promise.all(
                     batchSlice.map(chunk => {
                        let q = supabase.from('scanned_items')
                           .select('id, barcode, timestamp, status, menu_context, role')
                           .in('barcode', chunk);

                        if (roleList.length > 1) q = q.in('role', roleList);
                        else q = q.eq('role', role);
                        return q;
                     })
                  );
                  batchResults.forEach(res => {
                     if (res.data) crossDateData.push(...res.data);
                  });
               }
            }

            return [...sameDayData, ...crossDateData];
         };

         // 1. Initial Cache Check (SWR Phase 1: Stale)
         let hasRoleCache = false;
         let hasPendingCache = false;

         if (!forceRefresh) {
            if (auditRoleCacheRef.current[roleCacheKey]) {
               setAuditRoleData(auditRoleCacheRef.current[roleCacheKey]);
               hasRoleCache = true;
            }
            if (auditPendingCacheRef.current && auditPendingCacheRef.current.dateKey === dateKey) {
               setAuditPendingData(auditPendingCacheRef.current.data);
               hasPendingCache = true;
            }
         }

         // Decide which loading state to use
         if (!hasRoleCache || !hasPendingCache || forceRefresh) {
            setIsLoadingAuditData(true);
         } else {
            setIsBackgroundRefreshingAudit(true);
         }

         // 2. Fetch Fresh Data (SWR Phase 2: Revalidate)
         const fetchPromises = [fetchOptimizedData(auditRoleFilter)];
         if (!hasPendingCache || forceRefresh) {
            fetchPromises.push(fetchOptimizedData('GUDANG', true));
         }

         const results = await Promise.all(fetchPromises);
         if (curReqId !== auditRequestIdRef.current) return; // Stale request, discard!

         const roleData = results[0];

         // Update cache and state with fresh data
         auditRoleCacheRef.current[roleCacheKey] = roleData;
         setAuditRoleData(roleData);

         if (results.length > 1) {
            const gudangAuditData = results[1];
            auditPendingCacheRef.current = { dateKey, data: gudangAuditData };
            setAuditPendingData(gudangAuditData);
         }

         const now = new Date();
         setLastAuditFetchTime(`${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}`);
      } catch (err) {
         console.error("Failed to fetch audit data:", err);
      } finally {
         if (curReqId === auditRequestIdRef.current) {
            setIsLoadingAuditData(false);
            setIsBackgroundRefreshingAudit(false);
         }
      }
   };

   const [adminBarcodesCache, setAdminBarcodesCache] = useState<string[]>([]);
   
   // Single unified trigger: Fetch admin imports first, then fetch audit data immediately
   useEffect(() => {
      let isMounted = true;
      const loadData = async () => {
         if ((activeView === 'BATCH_DATA' || activeView === 'BATCH_DATA_2' || activeView === 'BATCH_DATA_3')) {
            if (activeBatchTab === 'REKAP_ADMIN' || activeBatchTab === 'AUDIT_KOMPARASI') {
               const barcodes = await fetchAdminImports();
               if (!isMounted) return;
               setAdminBarcodesCache(barcodes);
               if (activeBatchTab === 'AUDIT_KOMPARASI') {
                  fetchCancelledOrders();
                  fetchAuditData(false, barcodes);
               }
            }
         }
      };
      loadData();
      return () => { isMounted = false; };
   }, [activeView, activeBatchTab, batchDateFilter, batchTimeFilter, adminImportsTrigger]);

   // Trigger audit fetch ONLY when auditRoleFilter changes (Picker -> Checker, etc.)
   useEffect(() => {
      if ((activeView === 'BATCH_DATA' || activeView === 'BATCH_DATA_2' || activeView === 'BATCH_DATA_3') && activeBatchTab === 'AUDIT_KOMPARASI') {
         if (adminBarcodesCache.length > 0) {
            fetchAuditData(false, adminBarcodesCache);
         }
      }
   }, [auditRoleFilter]);

   // Realtime Live Stream Listener for Cek Selisih Resi (Auto update as scans occur)
   useEffect(() => {
      if ((activeView === 'BATCH_DATA' || activeView === 'BATCH_DATA_2' || activeView === 'BATCH_DATA_3') && activeBatchTab === 'AUDIT_KOMPARASI' && batchDateFilter) {
         let debounceTimer: any = null;
         const channelName = `realtime_audit_${batchDateFilter}_${auditRoleFilter}`;
         
         const channel = supabase
            .channel(channelName)
            .on(
               'postgres_changes',
               {
                  event: '*',
                  schema: 'public',
                  table: 'scanned_items'
               },
               () => {
                  clearTimeout(debounceTimer);
                  debounceTimer = setTimeout(() => {
                     fetchAuditData(false, adminBarcodesCache.length > 0 ? adminBarcodesCache : undefined);
                  }, 1500);
               }
            )
            .subscribe();

         return () => {
            clearTimeout(debounceTimer);
            supabase.removeChannel(channel);
         };
      }
   }, [activeView, activeBatchTab, batchDateFilter, auditRoleFilter, adminBarcodesCache]);

   // Memoized heavy computation for Audit Komparasi (Cek Selisih Resi)
   const auditComputedData = useMemo(() => {
      if (!batchDateFilter) return null;

      const adminResiArr = Array.from(new Set(
         adminImports.flatMap(item => item.barcodes || []).map(b => (b || '').toString().trim().toUpperCase()).filter(Boolean)
      )) as string[];
      const adminResiSet = new Set<string>(adminResiArr);

      // Compute date threshold for cross-date scan detection
      const targetEndMs = (() => {
         if (!batchDateFilter) return Infinity;
         const end = new Date(batchDateFilter + 'T23:59:59.999');
         if (batchTimeFilter) {
            const [h, m, s] = batchTimeFilter.split(':');
            end.setHours(+h, +m, +(s || '0'), 999);
         }
         return end.getTime();
      })();

      // Filter auditRoleData to relevant scans for this target date:
      // 1. Scans matching Admin barcodes for target date (whether scanned H+0 or H+1+)
      // 2. Scans performed ON target date (timestamp <= targetEndMs)
      const relevantRoleData = auditRoleData.filter(d => {
         const bc = (d.barcode || '').toString().trim().toUpperCase();
         if (!bc) return false;
         const isAdminResi = adminResiSet.has(bc);
         const isSameDayScan = !targetEndMs || (d.timestamp && d.timestamp <= targetEndMs);
         return isAdminResi || isSameDayScan;
      });

      // Map barcode to latest scan record
      const roleResiMap = new Map<string, any>();
      relevantRoleData.forEach(d => {
         const bc = (d.barcode || '').toString().trim().toUpperCase();
         if (bc && (!roleResiMap.has(bc) || (d.timestamp && d.timestamp > roleResiMap.get(bc).timestamp))) {
            roleResiMap.set(bc, d);
         }
      });

      const gudangCancelResiSet = new Set<string>(
         auditPendingData
            .filter(d => d.status === 'CANCEL' || d.menu_context === 'CANCEL' || (d.description && d.description.toUpperCase().includes('[CANCEL]')))
            .map(d => (d.barcode || '').toString().trim().toUpperCase())
            .filter(Boolean)
      );

      const cancelImportOnlySet = new Set<string>(cancelledOrders.map(o => (o.barcode || '').trim().toUpperCase()).filter(Boolean));
      const cancelBarcodeSet = new Set<string>([
         ...Array.from(cancelImportOnlySet),
         ...Array.from(gudangCancelResiSet)
      ]);
      const readyResiSet = new Set<string>(
         auditPendingData
            .filter(d => d.status === 'READY' || d.menu_context === 'READY' || (d.description && d.description.toUpperCase().includes('[READY]')))
            .map(d => (d.barcode || '').toString().trim().toUpperCase())
            .filter(Boolean)
      );
      
      // Prevent Overlap: If a resi is Cancelled or Ready, it shouldn't be counted as a valid scan in Terkirim/Susulan.
      cancelBarcodeSet.forEach(bc => roleResiMap.delete(bc));
      readyResiSet.forEach(bc => roleResiMap.delete(bc));

      // Remove Cancelled barcodes from the Ready set to avoid double-counting
      cancelBarcodeSet.forEach(bc => readyResiSet.delete(bc));

      const roleResi = new Set<string>(Array.from(roleResiMap.keys()));
      const ojolResiSet = new Set<string>(relevantRoleData.filter(d => (d.role || '').toUpperCase() === 'OJOL').map(d => (d.barcode || '').toString().trim().toUpperCase()).filter(Boolean));
      const pendingResi = new Set<string>(
         auditPendingData
            .filter(d => d.status === 'PENDING' || d.menu_context === 'PENDING' || (d.description && (d.description.toUpperCase().includes('[PENDING]') || d.description.toUpperCase().includes('[PENDING LT3]'))))
            .map(d => (d.barcode || '').toString().trim().toUpperCase())
            .filter(Boolean)
      );

      // If a resi is Cancelled, Ready in Gudang, or Scanned by Field Role, it is NO LONGER Pending!
      cancelBarcodeSet.forEach(bc => pendingResi.delete(bc));
      readyResiSet.forEach(bc => pendingResi.delete(bc));
      roleResi.forEach(bc => pendingResi.delete(bc));

      const crossDateResiMap = new Map<string, string>(); // barcode -> dateStr
      const crossDateCancelMap = new Map<string, string>(); // barcode -> dateStr
      const crossDateReadyMap = new Map<string, string>(); // barcode -> dateStr
      const sameDayResiSet = new Set<string>();
      const crossDateResiSet = new Set<string>();

      // Map cancel cross-date info (scanned or imported on H+1+, previous days, etc.)
      auditPendingData.forEach(d => {
         const bc = (d.barcode || '').toString().trim().toUpperCase();
         const isCancel = d.status === 'CANCEL' || d.menu_context === 'CANCEL' || (d.description && d.description.toUpperCase().includes('[CANCEL]'));
         if (bc && isCancel && d.timestamp && targetEndMs && d.timestamp > targetEndMs) {
            const dt = new Date(d.timestamp);
            const dateStr = `${String(dt.getDate()).padStart(2, '0')}/${String(dt.getMonth() + 1).padStart(2, '0')}`;
            crossDateCancelMap.set(bc, dateStr);
         }
      });
      cancelledOrders.forEach(o => {
         const bc = (o.barcode || '').toString().trim().toUpperCase();
         if (bc && cancelBarcodeSet.has(bc) && o.cancelled_at) {
            const ts = new Date(o.cancelled_at).getTime();
            if (targetEndMs && ts > targetEndMs) {
               const dt = new Date(ts);
               const dateStr = `${String(dt.getDate()).padStart(2, '0')}/${String(dt.getMonth() + 1).padStart(2, '0')}`;
               if (!crossDateCancelMap.has(bc)) {
                  crossDateCancelMap.set(bc, dateStr);
               }
            }
         }
      });

      // Map ready cross-date info
      auditPendingData.forEach(d => {
         const bc = (d.barcode || '').toString().trim().toUpperCase();
         const isReady = d.status === 'READY' || d.menu_context === 'READY' || (d.description && d.description.toUpperCase().includes('[READY]'));
         if (bc && isReady && d.timestamp && targetEndMs && d.timestamp > targetEndMs) {
            const dt = new Date(d.timestamp);
            const dateStr = `${String(dt.getDate()).padStart(2, '0')}/${String(dt.getMonth() + 1).padStart(2, '0')}`;
            crossDateReadyMap.set(bc, dateStr);
         }
      });

      adminResiArr.forEach(r => {
         if (roleResiMap.has(r)) {
            const scanItem = roleResiMap.get(r);
            const ts = scanItem.timestamp || 0;
            if (targetEndMs && ts > targetEndMs) {
               const dt = new Date(ts);
               const dateStr = `${String(dt.getDate()).padStart(2, '0')}/${String(dt.getMonth() + 1).padStart(2, '0')}`;
               crossDateResiMap.set(r, dateStr);
               crossDateResiSet.add(r);
            } else {
               sameDayResiSet.add(r);
            }
         }
      });

      const cancelMatchedSet = new Set<string>(adminResiArr.filter(r => cancelBarcodeSet.has(r)));
      const readyMatchedSet = new Set<string>(adminResiArr.filter(r => readyResiSet.has(r)));
      const belumDiscan = adminResiArr.filter(r => !roleResi.has(r) && !cancelBarcodeSet.has(r) && !readyResiSet.has(r));
      const matchResi = adminResiArr.filter(r => roleResi.has(r));
      const scanEkstra = Array.from(roleResi).filter(r => !adminResiSet.has(r));
      const susulanRoleList = Array.from(roleResi).filter(r => !adminResiSet.has(r) && earlierAdminResiMap.has(r));
      const pureEkstraList = Array.from(roleResi).filter(r => !adminResiSet.has(r) && !earlierAdminResiMap.has(r));

      return {
         adminResiArr,
         adminResiSet,
         roleResiMap,
         gudangCancelResiSet,
         cancelImportOnlySet,
         cancelBarcodeSet,
         readyResiSet,
         roleResi,
         ojolResiSet,
         pendingResi,
         crossDateResiMap,
         crossDateCancelMap,
         crossDateReadyMap,
         sameDayResiSet,
         crossDateResiSet,
         cancelMatchedSet,
         readyMatchedSet,
         belumDiscan,
         matchResi,
         scanEkstra,
         susulanRoleList,
         pureEkstraList
      };
   }, [adminImports, batchDateFilter, batchTimeFilter, auditRoleData, auditPendingData, cancelledOrders, earlierAdminResiMap]);

   const {
      adminResiArr = [] as string[],
      adminResiSet = new Set<string>(),
      roleResiMap = new Map<string, any>(),
      gudangCancelResiSet = new Set<string>(),
      cancelImportOnlySet = new Set<string>(),
      cancelBarcodeSet = new Set<string>(),
      readyResiSet = new Set<string>(),
      roleResi = new Set<string>(),
      ojolResiSet = new Set<string>(),
      pendingResi = new Set<string>(),
      crossDateResiMap = new Map<string, string>(),
      crossDateCancelMap = new Map<string, string>(),
      crossDateReadyMap = new Map<string, string>(),
      sameDayResiSet = new Set<string>(),
      crossDateResiSet = new Set<string>(),
      cancelMatchedSet = new Set<string>(),
      readyMatchedSet = new Set<string>(),
      belumDiscan = [] as string[],
      matchResi = [] as string[],
      scanEkstra = [] as string[],
      susulanRoleList = [] as string[],
      pureEkstraList = [] as string[]
   } = auditComputedData || {};

   const checkDuplicateBatchFilename = async (filename: string, dateStr: string): Promise<{
      isDuplicate: boolean;
      existingBatch?: { batch_no: string; created_at: string; excel_filename: string };
   }> => {
      const cleanName = filename.trim().toUpperCase();
      if (!cleanName || !dateStr) return { isDuplicate: false };

      const getLocalDateStr = (isoOrDate: string | Date): string => {
         const d = new Date(isoOrDate);
         const year = d.getFullYear();
         const month = String(d.getMonth() + 1).padStart(2, '0');
         const day = String(d.getDate()).padStart(2, '0');
         return `${year}-${month}-${day}`;
      };

      // 1. Cek dari batchSummaryData di state lokal
      if (batchSummaryData && batchSummaryData.length > 0) {
         const localMatch = batchSummaryData.find((b: any) => {
            if (!b.excel_filename || !b.created_at) return false;
            if (b.excel_filename.trim().toUpperCase() !== cleanName) return false;
            return getLocalDateStr(b.created_at) === dateStr;
         });
         if (localMatch) {
            return {
               isDuplicate: true,
               existingBatch: {
                  batch_no: localMatch.batch_no || '-',
                  created_at: localMatch.created_at,
                  excel_filename: localMatch.excel_filename
               }
            };
         }
      }

      // 2. Query tabel batches di Supabase untuk tanggal kalender tersebut
      try {
         const [y, m, d] = dateStr.split('-').map(Number);
         if (!isNaN(y) && !isNaN(m) && !isNaN(d)) {
            const startOfDay = new Date(y, m - 1, d, 0, 0, 0, 0);
            const endOfDay = new Date(y, m - 1, d, 23, 59, 59, 999);
            const searchStart = new Date(startOfDay.getTime() - 7200000).toISOString();
            const searchEnd = new Date(endOfDay.getTime() + 7200000).toISOString();

            const { data: dbBatches, error } = await supabase
               .from('batches')
               .select('id, batch_no, excel_filename, created_at')
               .gte('created_at', searchStart)
               .lte('created_at', searchEnd);

            if (!error && dbBatches && dbBatches.length > 0) {
               const dbMatch = dbBatches.find((b: any) => {
                  if (!b.excel_filename || !b.created_at) return false;
                  if (b.excel_filename.trim().toUpperCase() !== cleanName) return false;
                  return getLocalDateStr(b.created_at) === dateStr;
               });
               if (dbMatch) {
                  return {
                     isDuplicate: true,
                     existingBatch: {
                        batch_no: dbMatch.batch_no || '-',
                        created_at: dbMatch.created_at,
                        excel_filename: dbMatch.excel_filename
                     }
                  };
               }
            }
         }
      } catch (err) {
         console.warn("Pengecekan duplikat batch gagal:", err);
      }

      return { isDuplicate: false };
   };

   const handleSaveBatch = async () => {
      if (!batchExcelFilename.trim()) {
         alert("Nama File Excel harus diisi!");
         return;
      }
      if (!batchImportText.trim()) {
         alert("Masukkan data barcode!");
         return;
      }

      // Pengecekan penolakan duplikat nama file Excel di hari/tanggal/tahun yang sama
      setIsSavingBatch(true);
      const dupCheck = await checkDuplicateBatchFilename(batchExcelFilename, batchImportDate);
      if (dupCheck.isDuplicate) {
         setIsSavingBatch(false);
         const existing = dupCheck.existingBatch;
         const [y, m, d] = (batchImportDate || '').split('-');
         const formattedDate = (d && m && y) ? `${d}-${m}-${y}` : batchImportDate;
         const createdAtStr = existing?.created_at
            ? new Date(existing.created_at).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' })
            : '-';

         setBatchDuplicateErrorData({
            filename: batchExcelFilename.trim(),
            dateStr: formattedDate,
            batchNo: existing?.batch_no || '-',
            createdAt: createdAtStr
         });
         return;
      }
      setIsSavingBatch(false);

      const lines = batchImportText.split(/[\n,;]+/)
         .map(line => line.replace(/@/g, '').trim().toUpperCase())
         .filter(line => line.length > 0);

      const barcodeCount = lines.length;
      const hasKilat = /KILAT/i.test(batchExcelFilename);

      if (!hasKilat && barcodeCount !== 50) {
         let confirmMsg = "";
         if (barcodeCount < 50) {
            confirmMsg = `Jumlah barcode yang terdeteksi hanya ${barcodeCount} data (kurang dari standar 50 barcode per batch).`;
         } else {
            confirmMsg = `Jumlah barcode yang terdeteksi sebanyak ${barcodeCount} data (melebihi standar 50 barcode per batch).`;
         }
         setBatchConfirmMessage(confirmMsg);
         setIsBatchConfirmModalOpen(true);
         return;
      }

      await executeSaveBatch();
   };

   const formatBarcodeWithKnownPrefixes = (barcode: string): string => {
      if (!barcode) return '';
      let clean = barcode.replace(/@/g, '').trim().toUpperCase();
      const prefixes = ['LXAD', 'JNEB', 'JNAP'];
      for (const p of prefixes) {
         if (clean.startsWith(`${p}-`)) {
            // Already has hyphen
            break;
         }
         if (clean.startsWith(p)) {
            const rest = clean.slice(p.length);
            if (rest.length > 0 && !rest.startsWith('-')) {
               clean = `${p}-${rest}`;
               break;
            }
         }
      }
      // Normalize SiCepat 10-digit without leading '00' to 12-digit
      if (/^\d{10}$/.test(clean) && /^[4-9]/.test(clean)) {
         clean = '00' + clean;
      }
      return clean;
   };

   const parseLineToOrderAndBarcode = (line: string): { order_id: string | null; barcode: string } => {
      if (!line) return { order_id: null, barcode: '' };
      const rawClean = line.replace(/@/g, '').trim();
      if (!rawClean) return { order_id: null, barcode: '' };

      const allParts = rawClean.split(/[\t\s]+/).filter(Boolean);
      if (allParts.length === 0) return { order_id: null, barcode: '' };
      if (allParts.length === 1) {
         return { order_id: null, barcode: formatBarcodeWithKnownPrefixes(allParts[0]) };
      }

      // Filter out line number tokens (e.g. "1", "2", "1.", "50.")
      const parts = allParts.filter((p, idx) => {
         if (idx === 0 && /^\d{1,4}\.?$/.test(p) && allParts.length > 2) return false;
         return true;
      });

      if (parts.length === 1) {
         return { order_id: null, barcode: formatBarcodeWithKnownPrefixes(parts[0]) };
      }

      const tok0 = parts[0].trim().toUpperCase();
      const tok1 = parts[1].trim().toUpperCase();

      const isBarcodePattern = (t: string) => {
         return /^(SPXID|SPX|JP|JT|JX|JY|JZ|GTL|TKP|BLI|LXAD|LEX|JNAP|JNEB|00|10|11|12|TK|ID|NJV|NLID|CM|TJNT|SOC|BDG|JKT|SUB)/i.test(t) ||
                /\.(PDF|JPG|PNG)$/i.test(t) ||
                (/^00\d{8,12}$/.test(t)) ||
                (/^\d{10}$/.test(t) && /^[4-9]/.test(t)) ||
                (/^\d{12}$/.test(t));
      };

      const isOrderIdPattern = (t: string) => {
         return /^(INV\/|260|261|262|250|251|ORD|SO)/i.test(t) ||
                (/^\d{14,22}$/.test(t)) ||
                (/^2609\w+$/i.test(t));
      };

      // Case 1: tok0 is OrderID and tok1 is Barcode (Standard: [Order ID] [Barcode])
      if (isOrderIdPattern(tok0) && !isOrderIdPattern(tok1)) {
         return { order_id: parts[0], barcode: formatBarcodeWithKnownPrefixes(parts[1]) };
      }

      // Case 2: tok0 is Barcode and tok1 is OrderID (Reversed: [Barcode] [Order ID])
      if (isBarcodePattern(tok0) && (isOrderIdPattern(tok1) || !isBarcodePattern(tok1))) {
         return { order_id: parts[1], barcode: formatBarcodeWithKnownPrefixes(parts[0]) };
      }

      // Case 3: tok1 is clearly Barcode
      if (isBarcodePattern(tok1) && !isBarcodePattern(tok0)) {
         return { order_id: parts[0], barcode: formatBarcodeWithKnownPrefixes(parts[1]) };
      }

      // Fallback default: parts[0] is order_id, parts[1] is barcode
      return { order_id: parts[0], barcode: formatBarcodeWithKnownPrefixes(parts[1]) };
   };

   const executeSaveBatch = async () => {
      setIsSavingBatch(true);
      try {
         // Perlindungan ganda jika executeSaveBatch dipanggil dari modal konfirmasi
         const dupCheck = await checkDuplicateBatchFilename(batchExcelFilename, batchImportDate);
         if (dupCheck.isDuplicate) {
            setIsSavingBatch(false);
            const existing = dupCheck.existingBatch;
            const [y, m, d] = (batchImportDate || '').split('-');
            const formattedDate = (d && m && y) ? `${d}-${m}-${y}` : batchImportDate;
            const createdAtStr = existing?.created_at
               ? new Date(existing.created_at).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' })
               : '-';

            setBatchDuplicateErrorData({
               filename: batchExcelFilename.trim(),
               dateStr: formattedDate,
               batchNo: existing?.batch_no || '-',
               createdAt: createdAtStr
            });
            return;
         }

         const parsedLines = batchImportText.split(/[\n,;]+/)
            .map(line => line.trim())
            .filter(line => line.length > 0)
            .map(line => parseLineToOrderAndBarcode(line))
            .filter(item => item.barcode.length > 0);

         if (parsedLines.length === 0) {
            alert("Tidak ada barcode valid.");
            setIsSavingBatch(false);
            return;
         }

         // Remove duplicate lines from the input itself first based on barcode
         const uniqueMap = new Map();
         for (const item of parsedLines) {
             if (!uniqueMap.has(item.barcode)) {
                 uniqueMap.set(item.barcode, item);
             }
         }
         const finalItemsToInsert = Array.from(uniqueMap.values());
         const barcodesToCheck = finalItemsToInsert.map(item => item.barcode);

         // Clean up any stale/unscanned rows in batch_items for these exact barcodes
         // so the new batch owns all 50 barcodes cleanly without collision
         const CHUNK_SIZE = 500;
         for (let i = 0; i < barcodesToCheck.length; i += CHUNK_SIZE) {
            const chunk = barcodesToCheck.slice(i, i + CHUNK_SIZE);
            try {
               await supabase
                  .from('batch_items')
                  .delete()
                  .in('barcode', chunk);
            } catch (delErr) {
               console.warn("Stale batch_items cleanup notice:", delErr);
            }
         }

         // Generate a human-readable batch_no (e.g., BTCH-YYYYMMDD-XXXX)
         const datePart = batchImportDate.replace(/-/g, '');
         const randomPart = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
         const newBatchNo = `BTCH-${datePart}-${randomPart}`;
         
         const dateObj = new Date();
         if (batchImportDate) {
            const [y, m, d] = batchImportDate.split('-');
            dateObj.setFullYear(parseInt(y), parseInt(m) - 1, parseInt(d));
         }
         const overrideCreatedAt = dateObj.toISOString();

         // 1. Create the Batch Header
         const { data: newBatch, error: batchError } = await supabase
            .from('batches')
            .insert({
               batch_no: newBatchNo,
               created_by: currentAdmin?.username || 'admin',
               excel_filename: batchExcelFilename.trim(),
               created_at: overrideCreatedAt
            })
            .select()
            .single();

         if (batchError) throw batchError;

         // 2. Create Batch Items via chunked insert
         const INSERT_CHUNK = 500;
         for (let i = 0; i < finalItemsToInsert.length; i += INSERT_CHUNK) {
            const insertChunk = finalItemsToInsert.slice(i, i + INSERT_CHUNK);
            const { error: itemsError } = await supabase.from('batch_items').insert(
               insertChunk.map(item => ({
                  batch_id: newBatch.id,
                  barcode: item.barcode,
                  order_id: item.order_id,
                  created_at: overrideCreatedAt
               }))
            );
            if (itemsError) throw itemsError;
         }

         // 3. Save to PocketBase admin_batch_imports (and mirror to Firestore)
         const upperFilename = batchExcelFilename.toUpperCase();
         const matchedStaff = STAFF_NAMES.find(staff => upperFilename.includes(staff)) || 'LAINNYA';
         try {
            await addDoc(collection(db, 'admin_batch_imports'), {
               excelFilename: batchExcelFilename.trim(),
               staffName: matchedStaff,
               jumlah: finalItemsToInsert.length,
               timestamp: overrideCreatedAt,
               batchId: newBatchNo,
               createdAt: new Date().toISOString(),
               barcodes: finalItemsToInsert.map(i => i.barcode)
            });
         } catch (fsErr: any) {
            console.error("Failed to save to Firestore admin_batch_imports:", fsErr);
         }

         setSuccessToast(`Berhasil menyimpan ${finalItemsToInsert.length} data batch.`);
         setBatchImportText('');
         setIsBatchImportModalOpen(false);
         setBatchExcelFilename('');
         fetchBatchData();
         setRefreshSummaryTrigger(prev => prev + 1);
         setAdminImportsTrigger(prev => prev + 1);
      } catch (err: any) {
         alert("Gagal menyimpan batch: " + err.message);
      } finally {
         setIsSavingBatch(false);
      }
   };

   const sanitizeAndPadBarcode = (raw: string): string => {
      let cleaned = (raw || '').trim();
      if (!cleaned) return '';

      // Extract candidate if string contains space-separated noise (e.g. "134 JY1402022246 13.20.08")
      const parts = cleaned.split(/[\s\t,;]+/).filter(Boolean);
      if (parts.length > 1) {
         const candidate = parts.find(p => {
            const norm = p.toUpperCase().replace(/[^A-Z0-9]/g, '');
            return norm.length >= 7 && norm.length <= 35 && !/^\d{1,3}$/.test(norm) && !/^\d{2}\.\d{2}\.\d{2}$/.test(p);
         });
         if (candidate) {
            cleaned = candidate;
         }
      }

      // Clean non-alphanumeric chars
      cleaned = cleaned.replace(/[^A-Z0-9]/gi, '').toUpperCase();

      // Auto-padding 00 for barcodes starting with 4 or 2 (e.g. 4648115926 -> 004648115926, 2972260803 -> 002972260803)
      if (!cleaned.startsWith('00') && /^(4|2)/.test(cleaned)) {
         cleaned = '00' + cleaned;
      }

      // Format LXAD, JNAP & JNEB barcodes without hyphen: LXAD123456 -> LXAD-123456, JNAP123456 -> JNAP-123456, JNEB123456 -> JNEB-123456
      if (/^LXAD[^-]/i.test(cleaned)) {
         cleaned = 'LXAD-' + cleaned.substring(4);
      }
      if (/^JNAP[^-]/i.test(cleaned)) {
         cleaned = 'JNAP-' + cleaned.substring(4);
      }
      if (/^JNEB[^-]/i.test(cleaned)) {
         cleaned = 'JNEB-' + cleaned.substring(4);
      }

      return cleaned;
   };

   const [isCleaningDevModeLogistik, setIsCleaningDevModeLogistik] = useState(false);
   const [isManualCleaningDevModeLogistik, setIsManualCleaningDevModeLogistik] = useState(false);
   const [isCleaningDevMode0026, setIsCleaningDevMode0026] = useState(false);
   const [devModeModalConfig, setDevModeModalConfig] = useState<{ isOpen: boolean; type: 'NORMAL' | 'EXCEL' }>({ isOpen: false, type: 'NORMAL' });
   const [devModeModalText, setDevModeModalText] = useState('');

   const handleProcessDevModeModal = async () => {
      if (!devModeModalText || !devModeModalText.trim()) {
         alert("Data tidak boleh kosong!");
         return;
      }

      let barcodes: string[] = devModeModalText.split(/[\n]+/)
         .map(line => {
            // Excel uses Tabs (\t) for column separation. 
            // Split by Tab first, if no tabs then fallback to spaces
            const parts = line.includes('\t') ? line.trim().split('\t') : line.trim().split(/\s+/);
            let candidate = null;
            if (parts.length >= 2) {
               // If it has multiple columns (e.g. 3 columns), take the 2nd one (index 1)
               candidate = parts[1].trim().toUpperCase();
            } else if (parts.length === 1) {
               // If it only has 1 column (just the barcode itself), take that one
               candidate = parts[0].trim().toUpperCase();
            }
            // Abaikan angka baris / sampah Excel yang terlalu pendek
            if (candidate && candidate.length < 6) return null;
            return candidate;
         })
         .filter(Boolean) as string[];

      barcodes = Array.from(new Set(barcodes));

      if (barcodes.length === 0) {
         alert("Tidak ada resi valid yang ditemukan untuk diproses.");
         return;
      }

      if (devModeModalConfig.type === 'EXCEL') {
         const confirmText = `Sistem berhasil mengekstrak ${barcodes.length} resi dari teks tersebut.\n\nApakah Anda yakin ingin MENGIMPOR resi tersebut sebagai data Logistik baru?\n\n(Sistem akan otomatis menyesuaikan format sesuai standar Logistik).`;
         if (!window.confirm(confirmText)) return;

         setIsManualCleaningDevModeLogistik(true);
         try {
            // DevMode: Import murni tanpa auto-tambah 00 (bypass sanitizeAndPadBarcode)
            const cleanedBarcodes = barcodes.map(b => b.trim().toUpperCase()).filter(Boolean);
            const uniqueBarcodes = Array.from(new Set(cleanedBarcodes));
            if (uniqueBarcodes.length === 0) throw new Error("Tidak ada barcode valid setelah sanitasi.");

            // Cek apakah resi sudah ada di database untuk mencegah duplikat
            const { data: existingData } = await supabase
               .from('scanned_items')
               .select('barcode')
               .eq('role', 'LOGISTIK')
               .in('barcode', uniqueBarcodes);
            
            const existingBarcodes = new Set(existingData?.map(d => d.barcode) || []);
            const newBarcodesToInsert = uniqueBarcodes.filter(b => !existingBarcodes.has(b));

            if (newBarcodesToInsert.length === 0) {
               alert(`Seluruh ${uniqueBarcodes.length} resi tersebut sudah pernah di-scan / sudah ada di database!`);
               setIsManualCleaningDevModeLogistik(false);
               return;
            }

            const targetTimestamp = logistikImportDate ? (() => {
               const [y, m, d] = logistikImportDate.split('-').map(Number);
               const dateObj = new Date();
               dateObj.setFullYear(y, m - 1, d);
               const now = new Date();
               dateObj.setHours(now.getHours(), now.getMinutes(), now.getSeconds(), now.getMilliseconds());
               return dateObj.getTime();
            })() : Date.now();
            
            const insertChunkSize = 500;
            for (let i = 0; i < newBarcodesToInsert.length; i += insertChunkSize) {
               const chunk = newBarcodesToInsert.slice(i, i + insertChunkSize);
               const insertData = chunk.map(barcode => {
                  const uniqueId = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
                  return {
                     id: uniqueId,
                     barcode,
                     timestamp: targetTimestamp,
                     status: 'OK',
                     menu_context: 'LOGISTIK',
                     role: 'LOGISTIK',
                     employee_name: 'LOGISTIK',
                     user_email: currentAdmin?.username || 'admin@kalindo.com',
                  };
               });
               const { error } = await supabase.from('scanned_items').insert(insertData);
               if (error) throw error;
            }

            setDevModeModalConfig({ isOpen: false, type: 'NORMAL' });
            setDevModeModalText('');
            setSuccessToast(`✅ Berhasil mengimpor ${newBarcodesToInsert.length} data Logistik baru dari Excel! (${existingBarcodes.size} dilewati karena duplikat)`);
            
            if (activeView === 'LOGISTIK_DATA') {
               fetchPackingData(1);
            }
         } catch (err: any) {
            alert("Gagal mengimpor Logistik: " + err.message);
         } finally {
            setIsManualCleaningDevModeLogistik(false);
         }
         return;
      }

      // --------------------------------------------------------------------------------
      // LOGIC UNTUK "MANUAL HAPUS 00" (UPDATE DATABASE)
      // --------------------------------------------------------------------------------
      if (devModeModalConfig.type === 'REMOVE_00') {
         const confirmText = `Apakah Anda yakin ingin mencari ${barcodes.length} resi tersebut dan MENGHAPUS awalan 00 di depannya jika ada?\n\nProses ini berlaku untuk SEMUA ROLE (Logistik, Checker, dll).`;
         
         if (!window.confirm(confirmText)) return;

         setIsManualCleaningDevModeLogistik(true);
         try {
            let allRecords: { id: string; barcode: string; role: string }[] = [];
            
            // Fetch records that match the input barcodes (including variants with and without 00)
            for (let i = 0; i < barcodes.length; i += 500) {
               const chunk = barcodes.slice(i, i + 500);
               const searchChunk = Array.from(new Set(chunk.flatMap(b => [b, '00' + b, b.replace(/^00/, '')])));
               
               const { data, error } = await supabase
                  .from('scanned_items')
                  .select('id, barcode, role')
                  .in('barcode', searchChunk);
               
               if (error) throw error;
               if (data && data.length > 0) {
                  allRecords.push(...data);
               }
            }

            if (allRecords.length === 0) {
               alert("Tidak ada satupun resi yang cocok ditemukan di database.");
               return;
            }

            const updates: { id: string; barcode: string }[] = [];
            allRecords.forEach(r => {
               const oldBarcode = (r.barcode || '').toString().trim();
               if (oldBarcode.startsWith('00')) {
                  const newBarcode = oldBarcode.replace(/^00/, '');
                  updates.push({ id: r.id, barcode: newBarcode });
               }
            });

            if (updates.length === 0) {
               alert(`Ditemukan ${allRecords.length} resi cocok, tapi semuanya sudah bersih (tidak memiliki 00 di depan).`);
               return;
            }

            let successCount = 0;
            let deletedCount = 0;

            for (let i = 0; i < updates.length; i += 100) {
               const chunk = updates.slice(i, i + 100);
               const results = await Promise.all(
                  chunk.map(u => supabase.from('scanned_items').update({ barcode: u.barcode }).eq('id', u.id))
               );

               for (let j = 0; j < results.length; j++) {
                  const res = results[j];
                  if (res.error) {
                     // If it fails (likely due to unique constraint because the clean barcode already exists),
                     // we just delete this dirty duplicate record to clean it up.
                     const delRes = await supabase.from('scanned_items').delete().eq('id', chunk[j].id);
                     if (!delRes.error) {
                        deletedCount++;
                     } else {
                        throw new Error(res.error.message);
                     }
                  } else {
                     successCount++;
                  }
               }
            }

            setDevModeModalConfig({ isOpen: false, type: 'NORMAL' });
            setDevModeModalText('');
            setSuccessToast(`🧹 Manual DevMode Cleaner: Berhasil MENGHAPUS awalan 00 pada ${successCount} data resi! (Dihapus karena duplikat: ${deletedCount})`);
            setTimeout(() => {
               if (activeView === 'LOGISTIK_DATA') fetchPackingData(1);
            }, 500);
         } catch (error: any) {
            console.error("Error manual remove 00 dev mode logic:", error);
            alert("Gagal memproses data: " + error.message);
         } finally {
            setIsManualCleaningDevModeLogistik(false);
         }
         return;
      }

      // --------------------------------------------------------------------------------
      // LOGIC UNTUK "MANUAL LOGISTIK 00" (UPDATE DATABASE)
      // --------------------------------------------------------------------------------
      const confirmText = `Apakah Anda yakin ingin mencari ${barcodes.length} resi tersebut dan menambahkan 00 di depannya jika diperlukan?\n\nProses ini khusus untuk role LOGISTIK.`;
      
      if (!window.confirm(confirmText)) return;

      setIsManualCleaningDevModeLogistik(true);
      try {
         let allRecords: { id: string; barcode: string; role: string }[] = [];
         
         // Fetch LOGISTIK records that match the input barcodes (including variants with and without 00)
         for (let i = 0; i < barcodes.length; i += 500) {
            const chunk = barcodes.slice(i, i + 500);
            // Include variants: the barcode itself, with '00' prepended, and removing '00' if it has it
            const searchChunk = Array.from(new Set(chunk.flatMap(b => [b, '00' + b, b.replace(/^00/, '')])));
            
            const { data, error } = await supabase
               .from('scanned_items')
               .select('id, barcode, role')
               .eq('role', 'LOGISTIK')
               .in('barcode', searchChunk);
            
            if (error) throw error;
            if (data && data.length > 0) {
               allRecords.push(...data);
            }
         }

         if (allRecords.length === 0) {
            alert("Tidak ada satupun resi yang cocok ditemukan di database untuk role LOGISTIK.");
            return;
         }

         const updates: { id: string; barcode: string }[] = [];
         allRecords.forEach(r => {
            const oldBarcode = (r.barcode || '').toString().trim();
            let cleanBarcode = sanitizeAndPadBarcode(oldBarcode);
            if (!cleanBarcode.startsWith('00')) {
                 cleanBarcode = '00' + cleanBarcode;
            }
            if (cleanBarcode && cleanBarcode !== oldBarcode) {
               updates.push({ id: r.id, barcode: cleanBarcode });
            }
         });

         if (updates.length === 0) {
            alert(`Ditemukan ${allRecords.length} resi cocok, tapi semuanya sudah berformat 00 atau tidak perlu diupdate.`);
            return;
         }

         for (let i = 0; i < updates.length; i += 100) {
            const chunk = updates.slice(i, i + 100);
            await Promise.all(
               chunk.map(u => supabase.from('scanned_items').update({ barcode: u.barcode }).eq('id', u.id))
            );
         }

         setDevModeModalConfig({ isOpen: false, type: 'NORMAL' });
         setDevModeModalText('');
         setSuccessToast(`🧹 Manual DevMode Cleaner: Berhasil menambahkan 00 pada ${updates.length} data resi Logistik!`);
         setTimeout(() => {
            if (activeView === 'LOGISTIK_DATA') fetchPackingData(1);
         }, 500);
      } catch (error: any) {
         console.error("Error manual dev mode logic:", error);
         alert("Gagal memproses data: " + error.message);
      } finally {
         setIsManualCleaningDevModeLogistik(false);
      }
   };
   // Function to scan and group duplicates in Logistik
   const handleScanLogistikDuplicates = async (customBarcodesInput?: string[]) => {
      setIsScanningLogistikDupes(true);
      try {
         let allRecords: { id: string; barcode: string; timestamp: number; role: string; user_email?: string }[] = [];

         if (customBarcodesInput && customBarcodesInput.length > 0) {
            // Scan based on provided barcode list
            for (let i = 0; i < customBarcodesInput.length; i += 500) {
               const chunk = customBarcodesInput.slice(i, i + 500);
               const searchChunk = Array.from(new Set(chunk.flatMap(b => [b, '00' + b, b.replace(/^00/, '')])));
               const { data, error } = await supabase
                  .from('scanned_items')
                  .select('id, barcode, timestamp, role, user_email')
                  .eq('role', 'LOGISTIK')
                  .in('barcode', searchChunk);
               if (error) throw error;
               if (data) allRecords.push(...data);
            }
         } else {
            // Scan based on date filter (or all)
            const startOfDay = filterDate ? new Date(filterDate + 'T00:00:00.000').getTime() : 0;
            const endOfDay = filterDate ? new Date(filterDate + 'T23:59:59.999').getTime() : 0;
            let offset = 0;
            const limit = 1000;

            while (true) {
               let q = supabase
                  .from('scanned_items')
                  .select('id, barcode, timestamp, role, user_email')
                  .eq('role', 'LOGISTIK');
               if (startOfDay && endOfDay) {
                  q = q.gte('timestamp', startOfDay).lte('timestamp', endOfDay);
               }
               q = q.order('timestamp', { ascending: true }).range(offset, offset + limit - 1);
               const { data: pageData, error } = await q;
               if (error) throw error;
               if (!pageData || pageData.length === 0) break;
               allRecords.push(...pageData);
               if (pageData.length < limit) break;
               offset += limit;
            }
         }

         if (allRecords.length === 0) {
            alert("Tidak ada data Logistik yang ditemukan untuk dipindai.");
            return;
         }

         // Group by normalized barcode
         const groupMap = new Map<string, typeof allRecords>();
         allRecords.forEach(r => {
            const raw = (r.barcode || '').toString().trim();
            if (!raw) return;
            let norm = sanitizeAndPadBarcode(raw);
            if (!norm.startsWith('00') && (norm.startsWith('4') || norm.startsWith('2') || norm.startsWith('6'))) {
               norm = '00' + norm;
            }
            norm = norm.toUpperCase();
            if (!groupMap.has(norm)) {
               groupMap.set(norm, []);
            }
            groupMap.get(norm)!.push(r);
         });

         // Filter groups with > 1 item (actual duplicates)
         const detectedGroups: {
            normalizedKey: string;
            items: {
               id: string;
               barcode: string;
               timestamp: number;
               role: string;
               user_email?: string;
               isKeep: boolean;
            }[];
         }[] = [];

         const defaultDeleteIds: string[] = [];

         groupMap.forEach((items, normKey) => {
            if (items.length > 1) {
               // Sort items: prefer formatted '00' first, then earliest timestamp
               const sorted = [...items].sort((a, b) => {
                  const aHas00 = (a.barcode || '').startsWith('00') ? 1 : 0;
                  const bHas00 = (b.barcode || '').startsWith('00') ? 1 : 0;
                  if (aHas00 !== bHas00) return bHas00 - aHas00;
                  return (a.timestamp || 0) - (b.timestamp || 0);
               });

               const groupItems = sorted.map((item, idx) => {
                  const isKeep = idx === 0;
                  if (!isKeep) {
                     defaultDeleteIds.push(item.id);
                  }
                  return {
                     ...item,
                     isKeep
                  };
               });

               detectedGroups.push({
                  normalizedKey: normKey,
                  items: groupItems
               });
            }
         });

         if (detectedGroups.length === 0) {
            alert("✅ Hebat! Tidak ditemukan data duplikat/ganda pada data Logistik yang diperiksa.");
            return;
         }

         setLogistikDupeGroups(detectedGroups);
         setSelectedLogistikDupeDeleteIds(defaultDeleteIds);
         setLogistikDupeSearch('');
         setLogistikDupePage(1);
         setIsLogistikDupeModalOpen(true);
      } catch (err: any) {
         console.error("Error scanning logistik duplicates:", err);
         alert("Gagal memindai data duplikat: " + (err.message || 'Error tidak diketahui'));
      } finally {
         setIsScanningLogistikDupes(false);
      }
   };

