   const handleLogistikExcelFileSelect = async (file: File) => {
      setLogistikExcelFile(file);
      setIsProcessingLogistikExcel(true);
      setLogistikExcelPage(1);
      setLogistikExcelSearch('');
      setLogistikExcelSheetFilter('ALL');
      try {
         const data = await file.arrayBuffer();
         const workbook = XLSX.read(new Uint8Array(data), { type: 'array', cellDates: true, cellText: true, raw: false });
         
         const extracted: {
            id: string;
            barcode: string;
            sheetName: string;
            rowNum: number;
            waktu?: string;
            tanggal?: string;
            parsedTimestamp?: number;
         }[] = [];

         const sheetCounts: Record<string, number> = {};

         workbook.SheetNames.forEach(sheetName => {
            const worksheet = workbook.Sheets[sheetName];
            if (!worksheet) return;

            const rows: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false });
            if (rows.length === 0) return;

            let countForThisSheet = 0;
            // Row 0 is header, iterate from row 1 (B2:B)
            for (let r = 1; r < rows.length; r++) {
               const row = rows[r];
               if (!row || !Array.isArray(row)) continue;

               // Column B is index 1
               const rawBarcode = row[1] !== undefined && row[1] !== null ? String(row[1]).trim() : '';
               if (!rawBarcode) continue;

               // Sanitize and pad barcode
               const cleanBarcode = sanitizeAndPadBarcode(rawBarcode);
               if (!cleanBarcode) continue;

               // Parse Column C (WAKTU) & Column D (TANGGAL) if present
               const rawWaktu = row[2] !== undefined && row[2] !== null ? String(row[2]).trim() : '';
               const rawTanggal = row[3] !== undefined && row[3] !== null ? String(row[3]).trim() : '';

               let rowTimestamp: number | undefined = undefined;
               if (rawTanggal) {
                  try {
                     let datePart = rawTanggal;
                     let timePart = rawWaktu ? rawWaktu.replace(/\./g, ':') : '12:00:00';
                     if (datePart.includes('/')) {
                        const parts = datePart.split('/');
                        if (parts.length === 3) {
                           if (parts[2].length === 4) {
                              datePart = `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
                           }
                        }
                     }
                     const combinedStr = `${datePart}T${timePart}`;
                     const parsedDate = new Date(combinedStr);
                     if (!isNaN(parsedDate.getTime())) {
                        rowTimestamp = parsedDate.getTime();
                     }
                  } catch (e) {}
               }

               extracted.push({
                  id: `${sheetName}_${r}_${cleanBarcode}`,
                  barcode: cleanBarcode,
                  sheetName,
                  rowNum: r + 1,
                  waktu: rawWaktu,
                  tanggal: rawTanggal,
                  parsedTimestamp: rowTimestamp
               });
               countForThisSheet++;
            }

            if (countForThisSheet > 0) {
               sheetCounts[sheetName] = countForThisSheet;
            }
         });

         const summaryArr = Object.entries(sheetCounts).map(([sheetName, count]) => ({ sheetName, count }));
         setLogistikExcelSheetSummary(summaryArr);

         // Check database to identify existing barcodes in Role Logistik
         const distinctBarcodes = Array.from(new Set(extracted.map(x => x.barcode)));
         const existingSet = new Set<string>();

         if (distinctBarcodes.length > 0) {
            const checkChunkSize = 200;
            for (let i = 0; i < distinctBarcodes.length; i += checkChunkSize) {
               const chunk = distinctBarcodes.slice(i, i + checkChunkSize);
               const { data: existingRows } = await supabase
                  .from('scanned_items')
                  .select('barcode')
                  .in('barcode', chunk)
                  .eq('role', 'LOGISTIK');
               (existingRows || []).forEach((r: any) => {
                  if (r.barcode) existingSet.add(r.barcode.trim().toUpperCase());
               });
            }
         }

         setLogistikExcelExistingCount(existingSet.size);

         const annotatedRows = extracted.map(row => ({
            ...row,
            isDuplicateInDb: existingSet.has(row.barcode.toUpperCase())
         }));

         setLogistikExcelExtractedRows(annotatedRows);
         if (annotatedRows.length === 0) {
            alert("Tidak ditemukan data resi di Kolom B (B2:B) pada file Excel ini.");
         }
      } catch (err: any) {
         console.error("Error reading Logistik Excel file:", err);
         alert("Gagal membaca file Excel: " + err.message);
      } finally {
         setIsProcessingLogistikExcel(false);
      }
   };

   const handleSaveLogistikExcelImport = async () => {
      if (logistikExcelExtractedRows.length === 0) {
         alert("Tidak ada data untuk diimpor.");
         return;
      }

      // Filter out duplicates (auto-skip)
      const seen = new Set<string>();
      const rowsToInsert = logistikExcelExtractedRows.filter(row => {
         if (row.isDuplicateInDb) return false;
         const upper = row.barcode.toUpperCase();
         if (seen.has(upper)) return false;
         seen.add(upper);
         return true;
      });

      if (rowsToInsert.length === 0) {
         alert("Semua data pada file Excel ini sudah ada di database (Role Logistik) atau merupakan duplikat.");
         return;
      }

      setIsSavingLogistikExcel(true);
      setLogistikExcelProgress({ current: 0, total: rowsToInsert.length, percentage: 0 });

      try {
         const defaultTimestamp = logistikExcelDate ? (() => {
            const [y, m, d] = logistikExcelDate.split('-').map(Number);
            const dateObj = new Date();
            dateObj.setFullYear(y, m - 1, d);
            const now = new Date();
            dateObj.setHours(now.getHours(), now.getMinutes(), now.getSeconds(), now.getMilliseconds());
            return dateObj.getTime();
         })() : Date.now();

         const insertChunkSize = 500;
         let insertedCount = 0;

         for (let i = 0; i < rowsToInsert.length; i += insertChunkSize) {
            const chunk = rowsToInsert.slice(i, i + insertChunkSize);
            const insertData = chunk.map(row => {
               const uniqueId = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
               return {
                  id: uniqueId,
                  barcode: row.barcode,
                  timestamp: row.parsedTimestamp || defaultTimestamp,
                  status: 'OK',
                  menu_context: 'LOGISTIK',
                  role: 'LOGISTIK',
                  employee_name: 'LOGISTIK',
                  user_email: currentAdmin?.username || 'admin@kalindo.com',
                  description: row.sheetName ? `[Sheet: ${row.sheetName}]` : undefined
               };
            });

            const { error } = await supabase.from('scanned_items').insert(insertData);
            if (error) throw error;

            insertedCount += chunk.length;
            const pct = Math.round((insertedCount / rowsToInsert.length) * 100);
            setLogistikExcelProgress({ current: insertedCount, total: rowsToInsert.length, percentage: pct });
         }

         setSuccessToast(`Berhasil mengimpor ${rowsToInsert.length.toLocaleString()} data Logistik (${logistikExcelExtractedRows.length - rowsToInsert.length} data duplikat di-skip).`);
         setIsLogistikExcelModalOpen(false);
         setLogistikExcelFile(null);
         setLogistikExcelExtractedRows([]);
         setLogistikExcelSheetSummary([]);
         
         // Refresh Logistik Data view
         if (activeView === 'LOGISTIK_DATA') {
            fetchPackingData(1);
         }
      } catch (err: any) {
         console.error("Gagal import data excel logistik:", err);
         alert("Gagal mengimpor data Logistik: " + err.message);
      } finally {
         setIsSavingLogistikExcel(false);
      }
   };

   const handleSaveLogistikImport = async () => {
      if (!logistikImportText.trim()) {
         alert("Masukkan atau paste data resi Logistik.");
         return;
      }
      setIsSavingLogistik(true);
      try {
         const rawLines = logistikImportText.split(/[\n\r,;]+/).map(b => b.trim()).filter(Boolean);
         if (rawLines.length === 0) throw new Error("Tidak ada data barcode yang diinput.");

         // 1. Check for Forbidden Symbols (strict rejection)
         const activeSymbolsList = forbiddenSymbols.map(s => s.symbol).filter(Boolean);
         const invalidLines: string[] = [];

         rawLines.forEach(line => {
            const hasForbiddenSymbol = activeSymbolsList.some(sym => line.includes(sym));
            const hasSpecialChars = /[^a-zA-Z0-9\-\_\/\s]/.test(line);
            if (hasForbiddenSymbol || hasSpecialChars) {
               invalidLines.push(line);
            }
         });

         if (invalidLines.length > 0) {
            const sampleDisplay = invalidLines.slice(0, 15).map(l => `- "${l}"`).join('\n');
            const extraCount = invalidLines.length > 15 ? `\n...dan ${invalidLines.length - 15} data lainnya` : '';
            alert(
               `❌ IMPORT LOGISTIK DITOLAK!\n\nTerdapat ${invalidLines.length} data yang mengandung SIMBOL TERLARANG:\n\nData Bermasalah:\n${sampleDisplay}${extraCount}\n\nSilakan bersihkan data tersebut dari teks import dan coba lagi.`
            );
            setIsSavingLogistik(false);
            return;
         }

         // 2. Sanitize & pad valid barcodes
         const cleanedBarcodes = rawLines.map(line => sanitizeAndPadBarcode(line)).filter(Boolean);
         const uniqueBarcodes = Array.from(new Set(cleanedBarcodes));
         if (uniqueBarcodes.length === 0) throw new Error("Tidak ada barcode valid setelah sanitasi.");

         const targetTimestamp = logistikImportDate ? (() => {
            const [y, m, d] = logistikImportDate.split('-').map(Number);
            const dateObj = new Date();
            dateObj.setFullYear(y, m - 1, d);
            const now = new Date();
            dateObj.setHours(now.getHours(), now.getMinutes(), now.getSeconds(), now.getMilliseconds());
            return dateObj.getTime();
         })() : Date.now();

         // 3. Check for existing barcodes in database (Role LOGISTIK) to prevent 409 Conflict (unique constraint)
         const existingInDb = new Set<string>();
         const checkChunkSize = 1000;
         for (let i = 0; i < uniqueBarcodes.length; i += checkChunkSize) {
            const chunk = uniqueBarcodes.slice(i, i + checkChunkSize);
            const { data: existRows, error: checkErr } = await supabase
               .from('scanned_items')
               .select('barcode')
               .eq('role', 'LOGISTIK')
               .in('barcode', chunk);

            if (!checkErr && existRows) {
               existRows.forEach(r => existingInDb.add((r.barcode || '').trim().toUpperCase()));
            }
         }

         const barcodesToInsert = uniqueBarcodes.filter(b => !existingInDb.has(b.trim().toUpperCase()));

         if (barcodesToInsert.length === 0) {
            alert(`⚠️ Seluruh ${uniqueBarcodes.length} data resi yang diinput SUDAH ADA di database (Role Logistik)!\n\nTidak ada data baru yang perlu diimpor.`);
            setIsSavingLogistik(false);
            return;
         }

         const insertChunkSize = 500;
         for (let i = 0; i < barcodesToInsert.length; i += insertChunkSize) {
            const chunk = barcodesToInsert.slice(i, i + insertChunkSize);
            const insertData = chunk.map((barcode, idx) => {
               const uniqueId = `${Date.now()}-${idx}-${Math.random().toString(36).substring(2, 9)}`;
               return {
                  id: uniqueId,
                  barcode,
                  timestamp: targetTimestamp,
                  status: 'OK',
                  menu_context: 'LOGISTIK',
                  role: 'LOGISTIK',
                  employee_name: 'LOGISTIK',
                  user_email: currentAdmin?.username || 'admin@kalindo.com',
               };
            });
            const { error } = await supabase.from('scanned_items').insert(insertData);
            if (error) {
               // Fallback: jika terjadi conflict 409, insert per item dan lewati yang duplikat
               if (error.code === '23505' || String(error.message || '').includes('unique_scan_global_role_menu') || error.code === '409') {
                  for (const row of insertData) {
                     const { error: singleErr } = await supabase.from('scanned_items').insert([row]);
                     if (singleErr && singleErr.code !== '23505') throw singleErr;
                  }
               } else {
                  throw error;
               }
            }
         }

         const skippedCount = existingInDb.size;
         if (skippedCount > 0) {
            setSuccessToast(`✅ Berhasil mengimpor ${barcodesToInsert.length} data Logistik baru (${skippedCount} data duplikat otomatis dilewati).`);
         } else {
            setSuccessToast(`✅ Berhasil mengimpor ${barcodesToInsert.length} data Logistik pada tanggal ${logistikImportDate}.`);
         }
         setLogistikImportText('');
         const today = new Date();
         const offset = today.getTimezoneOffset() * 60000;
         setLogistikImportDate((new Date(today.getTime() - offset)).toISOString().slice(0, 10));
         setIsLogistikImportModalOpen(false);
         // Refresh data logistik
         if (activeView === 'LOGISTIK_DATA') {
            fetchPackingData(1);
         }
      } catch (err: any) {
         alert("Gagal mengimpor Logistik: " + err.message);
      } finally {
         setIsSavingLogistik(false);
      }
   };

   const processBulkExcelUpload = async () => {
      if (excelFilesToImport.length === 0) {
         alert("Pilih minimal satu file Excel.");
         return;
      }

      setIsLoadingBatchData(true);
      let totalImported = 0;
      let sheetsProcessed = 0;
      let filesProcessed = 0;
      let errors: string[] = [];

      try {
         for (const file of excelFilesToImport) {
            try {
               const data = await file.arrayBuffer();
               const workbook = XLSX.read(new Uint8Array(data), { type: 'array' });
               
               let targetSheets = workbook.SheetNames.filter(name => name.toLowerCase().startsWith('batch'));
               if (targetSheets.length === 0) {
                  targetSheets = workbook.SheetNames; // Allow any sheet name if 'Batch' is not found
               }

               // Generate shared identity parts
               const datePart = new Date().toISOString().slice(0, 10).replace(/-/g, '');
               const randomPart = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
               const baseFileName = file.name.replace(/\.[^/.]+$/, ""); // strip extension

               for (const sheetName of targetSheets) {
                  const worksheet = workbook.Sheets[sheetName];
                  const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 }) as any[][];

                  if (jsonData.length === 0) continue;

                  // Map to group items by batch name
                  const batchGroups = new Map<string, { barcode: string; order_id: string | null }[]>();

                  // Try to find the AWB, Batch, and Order ID columns dynamically from header (index 0)
                  const headerRow = jsonData[0] || [];
                  let awbIndex = -1;
                  let batchIndex = -1;
                  let orderIdIndex = -1;
                  
                  for (let col = 0; col < headerRow.length; col++) {
                     const colName = String(headerRow[col] || '').toUpperCase().trim();
                     if (colName.includes('AWB') || colName.includes('BARCODE') || colName.includes('RESI')) {
                        awbIndex = col;
                     }
                     if (colName.includes('BATCH') || colName.includes('FILENAME')) {
                        batchIndex = col;
                     }
                     if (colName.includes('PESANAN') || colName.includes('ORDER_ID') || colName.includes('ORDER ID') || colName === 'ID') {
                        orderIdIndex = col;
                     }
                  }

                  if (awbIndex === -1) awbIndex = 3; // Default to column D (index 3) if not found

                  // Skip index 0 (header D1). Start from index 1 (D2)
                  for (let i = 1; i < jsonData.length; i++) {
                     const row = jsonData[i];
                     if (row && row.length > awbIndex && row[awbIndex]) {
                        const bc = formatBarcodeWithKnownPrefixes(String(row[awbIndex]).replace(/@/g, '').trim().toUpperCase());
                        const ordId = (orderIdIndex !== -1 && row[orderIdIndex]) ? String(row[orderIdIndex]).replace(/@/g, '').trim().toUpperCase() : null;
                        if (bc) {
                           let rowBatchName = `${sheetName.trim()} [${baseFileName}]-${datePart}-${randomPart}`;
                           if (batchIndex !== -1 && row[batchIndex]) {
                              rowBatchName = String(row[batchIndex]).trim();
                           }

                           if (!batchGroups.has(rowBatchName)) {
                              batchGroups.set(rowBatchName, []);
                           }
                           batchGroups.get(rowBatchName)!.push({ barcode: bc, order_id: ordId });
                        }
                     }
                  }

                  // Process each grouped batch
                  for (const [batchNo, rawItems] of batchGroups.entries()) {
                     // Remove duplicates within the batch based on barcode
                     const uniqueMap = new Map<string, { barcode: string; order_id: string | null }>();
                     for (const it of rawItems) {
                        if (!uniqueMap.has(it.barcode)) {
                           uniqueMap.set(it.barcode, it);
                        }
                     }
                     const uniqueItems = Array.from(uniqueMap.values());
                     if (uniqueItems.length === 0) continue;

                     let batchId;
                     const { data: newBatch, error: batchError } = await supabase
                        .from('batches')
                        .insert({
                           batch_no: batchNo,
                           created_by: currentAdmin?.username || 'admin'
                        })
                        .select()
                        .single();

                     if (batchError) {
                        console.error(`Batch error on sheet ${sheetName}, batch ${batchNo}:`, batchError);
                        continue; // Skip the error batch but continue others
                     }
                     batchId = newBatch.id;

                     // Clean up any stale/unscanned rows in batch_items for these exact barcodes
                     // so the new batch owns all barcodes cleanly without losing data
                     const allBarcodes = uniqueItems.map(it => it.barcode);
                     const CHUNK_SIZE = 500;
                     for (let i = 0; i < allBarcodes.length; i += CHUNK_SIZE) {
                        const chunk = allBarcodes.slice(i, i + CHUNK_SIZE);
                        try {
                           await supabase
                              .from('batch_items')
                              .delete()
                              .in('barcode', chunk);
                        } catch (delErr) {
                           console.warn("Stale batch_items cleanup notice (Excel):", delErr);
                        }
                     }

                     const finalItemsToInsert = uniqueItems;
                     if (finalItemsToInsert.length === 0) continue; // Skip if all barcodes already imported

                     // Insert only completely new barcodes via chunks
                     const INSERT_CHUNK = 500;
                     for (let i = 0; i < finalItemsToInsert.length; i += INSERT_CHUNK) {
                        const insertChunk = finalItemsToInsert.slice(i, i + INSERT_CHUNK);
                        const { error: itemsError } = await supabase.from('batch_items').insert(
                           insertChunk.map(item => ({
                              batch_id: batchId,
                              barcode: item.barcode,
                              order_id: item.order_id || null
                           }))
                        );

                        if (itemsError) {
                           console.error(`Items error on sheet ${sheetName}, batch ${batchNo} (chunk):`, itemsError);
                        }
                     }

                     totalImported += finalItemsToInsert.length;
                     sheetsProcessed++;

                     // Save to PocketBase admin_batch_imports (and mirror to Firestore)
                     const upperFilename = file.name.toUpperCase();
                     const matchedStaff = STAFF_NAMES.find(staff => upperFilename.includes(staff)) || 'LAINNYA';
                     try {
                        await addDoc(collection(db, 'admin_batch_imports'), {
                           excelFilename: file.name,
                           staffName: matchedStaff,
                           jumlah: finalItemsToInsert.length,
                           timestamp: new Date().toISOString(),
                           batchId: batchNo,
                           createdAt: new Date().toISOString(),
                           barcodes: finalItemsToInsert.map(i => i.barcode)
                        });
                     } catch (fsErr: any) {
                        console.error("Failed to save to Firestore admin_batch_imports:", fsErr);
                     }
                  }
               }
               filesProcessed++;
            } catch (fileErr: any) {
               errors.push(`File ${file.name}: ${fileErr.message}`);
            }
         }

         if (totalImported > 0) {
            setSuccessToast(`Berhasil mengimpor ${totalImported} barcode dari ${sheetsProcessed} sheet (${filesProcessed} file Excel).`);
            fetchBatchData();
            setAdminImportsTrigger(prev => prev + 1);
            setIsExcelImportModalOpen(false);
            setExcelFilesToImport([]);
         } else if (errors.length > 0) {
            alert(`Tidak ada barcode yang diimpor.\nKesalahan:\n${errors.join('\n')}`);
         } else {
            alert("Tidak ada barcode yang valid ditemukan di kolom D (D2 ke bawah) pada file terpilih.");
         }
      } catch (err: any) {
         alert("Gagal memproses file Excel: " + err.message);
      } finally {
         setIsLoadingBatchData(false);
      }
   };

