   // --- OJOL DATA LOGIC ---

   const buildOjolQuery = (shiftToNamesMap?: Record<string, string[]>, countOnly = false, options?: { startDate?: string, endDate?: string }) => {
      const effectiveStartDate = options?.startDate || (canManageDate ? filterDate : getTodayString());
      const activeClient = supabase;

      let query = activeClient.from('scanned_items')
         .select(countOnly ? 'id' : '*', { count: 'exact' });

      // Role Filter (OJOL & Ojol)
      query = query.in('role', ['OJOL', 'Ojol']);

      // Date Filter with Timestamp range (standard reliable filter)
      if (effectiveStartDate) {
         const startOfDay = new Date(effectiveStartDate + 'T00:00:00').getTime();
         const endOfDay = new Date(effectiveStartDate + 'T23:59:59.999').getTime();
         if (options?.startDate) {
            const startRange = new Date(options.startDate + 'T00:00:00').getTime();
            const endRange = new Date((options.endDate || options.startDate) + 'T23:59:59.999').getTime();
            query = query.gte('timestamp', startRange).lte('timestamp', endRange);
         } else {
            query = query.gte('timestamp', startOfDay).lte('timestamp', endOfDay);
         }
      }

      // Shift Filter -> Transform to Employee Name Filter (only if specific shift selected and has employees)
      if (filterOjolShift !== 'ALL' && shiftToNamesMap && !options?.startDate) {
         const namesInShift = shiftToNamesMap[filterOjolShift] || [];
         if (namesInShift.length > 0) {
            query = query.in('employee_name', namesInShift);
         }
      }

      // Staff Filter
      if (filterOjolStaff !== 'ALL' && !options?.startDate) {
         query = query.eq('employee_name', filterOjolStaff);
      }

      // Search Filter (Barcode or Name)
      if (ojolSearch && !options?.startDate) {
         query = query.or(`barcode.ilike.%${ojolSearch}%,employee_name.ilike.%${ojolSearch}%`);
      }

      if (!countOnly) {
         query = query.order('timestamp', { ascending: false });
      }

      return query;
   };

   const fetchOjolData = useCallback(async () => {
      if (activeView !== 'OJOL_DATA') return;
      setIsLoadingOjol(true);
      try {
         const effectiveDate = canManageDate ? filterDate : getTodayString();
         const activeClient = supabase;

         // 1. Get Shift/Map Info
         const { data: empData } = await activeClient.from('employees').select('name, shift');
         const shiftToNamesMap: Record<string, string[]> = {};
         const shiftMap = new Map<string, string>();

         if (empData) {
            empData.forEach((e: any) => {
               if (e.shift) {
                  if (!shiftToNamesMap[e.shift]) shiftToNamesMap[e.shift] = [];
                  shiftToNamesMap[e.shift].push(e.name);
               }
               if (e.name) shiftMap.set(e.name.trim().toLowerCase(), e.shift);
            });
         }

         // APPLY ACTIVE OJOL STAFF LIST FOR SELECTED DATE (HANYA STAF YANG SCAN PADA HARI TERSEBUT)
         const ojolStaffSet = new Set<string>();

         // 1. Cek cache Firestore jika ada
         if (firestoreDayDataCache.has(effectiveDate)) {
            const cachedDocs = firestoreDayDataCache.get(effectiveDate) || [];
            cachedDocs.forEach((d: any) => {
               const r = (d.role || '').toUpperCase();
               if (r === 'OJOL' || r === 'OJOL_DATA') {
                  const sName = (d.employee_name || d.admin_name || '').trim();
                  if (sName && sName !== '-' && sName !== 'Unknown') {
                     ojolStaffSet.add(sName);
                  }
               }
            });
         }

         // 2. Query Supabase untuk staf yang scan OJOL pada tanggal tersebut (semua pagination)
         try {
            const startOfDayMs = new Date(`${effectiveDate}T00:00:00`).getTime();
            const endOfDayMs = new Date(`${effectiveDate}T23:59:59.999`).getTime();

            const { count: ojolCount } = await activeClient
               .from('scanned_items')
               .select('id', { count: 'exact', head: true })
               .gte('timestamp', startOfDayMs)
               .lte('timestamp', endOfDayMs)
               .in('role', ['OJOL', 'Ojol']);

            if (ojolCount && ojolCount > 0) {
               const chunkSize = 1000;
               const numChunks = Math.min(20, Math.ceil(ojolCount / chunkSize));
               const chunkPromises = [];
               for (let i = 0; i < numChunks; i++) {
                  const from = i * chunkSize;
                  const to = from + chunkSize - 1;
                  chunkPromises.push(
                     activeClient
                        .from('scanned_items')
                        .select('employee_name, team_members')
                        .gte('timestamp', startOfDayMs)
                        .lte('timestamp', endOfDayMs)
                        .in('role', ['OJOL', 'Ojol'])
                        .range(from, to)
                  );
               }
               const results = await Promise.all(chunkPromises);
               results.forEach(res => {
                  if (res.data) {
                     res.data.forEach((row: any) => {
                        const sName = (row.employee_name || '').trim();
                        if (sName && sName !== '-' && sName !== 'Unknown' && sName !== 'null') {
                           ojolStaffSet.add(sName);
                        }
                     });
                  }
               });
            }
         } catch (e) {
            console.error("Error fetching active ojol staff:", e);
         }

         // Filter staf OJOL aktif berdasarkan shift terpilih
         let visibleStaff: string[] = [];
         ojolStaffSet.forEach(name => {
            const empShift = shiftMap.get(name.toLowerCase());
            if (filterOjolShift === 'ALL') {
               visibleStaff.push(name);
            } else if (empShift && (empShift === filterOjolShift || empShift.toLowerCase().includes(filterOjolShift.toLowerCase()))) {
               visibleStaff.push(name);
            }
         });

         const sortedOjolStaff = Array.from(new Set(visibleStaff)).sort((a, b) => a.localeCompare(b));
         setOjolStaffList(sortedOjolStaff);
         if (filterOjolShift !== 'ALL' && sortedOjolStaff.length > 0 && !sortedOjolStaff.includes(filterOjolShift)) {
            setFilterOjolStaff('ALL');
         }

         // FIRESTORE BRANCH FOR OJOL
         if (forcedDataSource === 'FIRESTORE') {
            const startMs = new Date(`${effectiveDate}T00:00:00`).getTime();
            const endMs = new Date(`${effectiveDate}T23:59:59.999`).getTime();

            let dayDocs: any[] = [];
            if (firestoreDayDataCache.has(effectiveDate)) {
               dayDocs = firestoreDayDataCache.get(effectiveDate)!;
            } else {
               setFirestoreLoadingText('Mengambil data Ojol dari Firestore...');
               const activeFsQuery = fsQuery(
                  collection(db, 'scanned_items'),
                  where('timestamp', '>=', startMs),
                  where('timestamp', '<=', endMs)
               );
               const fsSnap = await getDocs(activeFsQuery);
               dayDocs = fsSnap.docs.map(docSnap => ({
                  id: docSnap.id,
                  ...(docSnap.data() as Record<string, any>)
               }));
               firestoreDayDataCache.set(effectiveDate, dayDocs);
               setFirestoreLoadingText('');
            }

            let fsOjolItems: any[] = [];
            dayDocs.forEach(d => {
               const r = (d.role || '').toUpperCase();
               if (r === 'OJOL' || r === 'OJOL_DATA') {
                  let rawBarcode = (d.barcode || '').toString().trim();
                  if (rawBarcode.startsWith('0026') || rawBarcode.startsWith('002')) rawBarcode = rawBarcode.replace(/^00/, '');
                  if (/^LXAD[^-]/i.test(rawBarcode)) rawBarcode = 'LXAD-' + rawBarcode.substring(4);
                  if (/^JNAP[^-]/i.test(rawBarcode)) rawBarcode = 'JNAP-' + rawBarcode.substring(4);
                  if (/^JNEB[^-]/i.test(rawBarcode)) rawBarcode = 'JNEB-' + rawBarcode.substring(4);

                  const empName = d.employee_name || d.admin_name || d.leader_name || '-';
                  fsOjolItems.push({
                     ...d,
                     barcode: rawBarcode,
                     employee_name: empName,
                     shift: shiftMap.get(empName) || 'Unknown',
                     is_from_firestore: true
                  });
               }
            });

            if (filterOjolStaff && filterOjolStaff !== 'ALL') {
               fsOjolItems = fsOjolItems.filter(item => item.employee_name === filterOjolStaff);
            }
            if (filterOjolShift && filterOjolShift !== 'ALL') {
               const validNames = new Set(shiftToNamesMap[filterOjolShift] || []);
               fsOjolItems = fsOjolItems.filter(item => validNames.has(item.employee_name));
            }
            if (ojolSearch) {
               const term = ojolSearch.toLowerCase();
               fsOjolItems = fsOjolItems.filter(item =>
                  (item.barcode && item.barcode.toLowerCase().includes(term)) ||
                  (item.employee_name && item.employee_name.toLowerCase().includes(term))
               );
            }

            fsOjolItems.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));

            const totalFsCount = fsOjolItems.length;
            const from = (page - 1) * rowsPerPage;
            const to = from + rowsPerPage - 1;
            const pageItems = fsOjolItems.slice(from, to + 1);

            setOjolData(pageItems);
            setTotalRows(totalFsCount);
            setActiveDataSource('FIRESTORE');

            const uniqueBarcodes = new Set(fsOjolItems.map((i: any) => i.barcode)).size;
            const uniqueStaff = new Set(fsOjolItems.map((i: any) => i.employee_name)).size;
            const latest = fsOjolItems.length > 0 ? new Date(fsOjolItems[0].timestamp).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '-';
            setOjolStats({
               total: totalFsCount,
               distinctBarcodes: uniqueBarcodes,
               activeStaff: uniqueStaff,
               latest
            });
            setIsLoadingOjol(false);
            return;
         }

         // SUPABASE BRANCH FOR OJOL
         const query = buildOjolQuery(shiftToNamesMap);
         const from = (page - 1) * rowsPerPage;
         const to = from + rowsPerPage - 1;

         const { data, count, error } = await query.range(from, to);
         if (error) throw error;
         const finalData = data || [];
         setTotalRows(count || 0);
         setActiveDataSource('SUPABASE');

         const enriched = finalData.map((item: any) => {
            let rawBarcode = (item.barcode || '').toString().trim();
            if (rawBarcode.startsWith('0026') || rawBarcode.startsWith('002')) {
               rawBarcode = rawBarcode.replace(/^00/, '');
            }
            if (/^LXAD[^-]/i.test(rawBarcode)) {
               rawBarcode = 'LXAD-' + rawBarcode.substring(4);
            }
            if (/^JNAP[^-]/i.test(rawBarcode)) {
               rawBarcode = 'JNAP-' + rawBarcode.substring(4);
            }
            if (/^JNEB[^-]/i.test(rawBarcode)) {
               rawBarcode = 'JNEB-' + rawBarcode.substring(4);
            }
            return {
               ...item,
               barcode: rawBarcode,
               shift: shiftMap.get(item.employee_name) || '-'
            };
         });
         setOjolData(enriched);

         // Stats Query (Separate to ignore pagination)
         const statsQuery = buildOjolQuery(shiftToNamesMap);
         const { data: allStatsData } = await statsQuery.select('barcode, employee_name, timestamp');

         if (allStatsData) {
            const uniqueBarcodes = new Set(allStatsData.map((i: any) => i.barcode)).size;
            const uniqueStaff = new Set(allStatsData.map((i: any) => i.employee_name)).size;
            const latest = allStatsData.length > 0 ? new Date(allStatsData[0].timestamp).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '-';
            setOjolStats({
               total: count || 0,
               distinctBarcodes: uniqueBarcodes,
               activeStaff: uniqueStaff,
               latest
            });
         }
      } catch (err: any) {
         console.error("Fetch Ojol Error", err);
      } finally {
         setIsLoadingOjol(false);
      }
   }, [activeView, filterOjolShift, filterOjolStaff, filterDate, page, rowsPerPage, ojolSearch, forcedDataSource]);

   // Trigger Fetch
   useEffect(() => {
      if (activeView === 'OJOL_DATA') {
         fetchOjolData();
      }
   }, [fetchOjolData]);

   const handleExportOjolData = async () => {
      setIsExportingOjol(true);
      setExportOjolProgress(0);
      try {
         const { data: empData } = await supabase.from('employees').select('name, shift');
         const shiftMap = new Map<string, string>();
         const shiftToNamesMap: Record<string, string[]> = {};
         if (empData) {
            empData.forEach((e: any) => {
               if (e.name && e.shift) {
                  shiftMap.set(e.name, e.shift);
                  if (!shiftToNamesMap[e.shift]) shiftToNamesMap[e.shift] = [];
                  shiftToNamesMap[e.shift].push(e.name);
               }
            });
         }

         const countQuery = buildOjolQuery(shiftToNamesMap, true);
         const { count, error: countError } = await countQuery.range(0, 1);
         if (countError) throw countError;

         const totalRecords = count || 0;
         if (totalRecords === 0) { alert("No data to export."); setIsExportingOjol(false); return; }

         const FETCH_BATCH_SIZE = 1000;
         const FILE_SPLIT_LIMIT = 5000;

         let accumulatedRows = "";
         let currentFileCount = 0;
         let fileIndex = 1;

         for (let offset = 0; offset < totalRecords; offset += FETCH_BATCH_SIZE) {
            setExportOjolProgress(Math.round((offset / totalRecords) * 100));
            const to = Math.min(offset + FETCH_BATCH_SIZE - 1, totalRecords - 1);

            const { data, error } = await buildOjolQuery(shiftToNamesMap).range(offset, to);
            if (error) throw error;
            if (!data || data.length === 0) continue;

            const enrichedBatch = data.map((item: any) => ({ ...item, shift: shiftMap.get(item.employee_name) || '-' }));
            const batchRows = enrichedBatch.map((item: any, idx: number) => {
               const dateStr = new Date(item.timestamp).toLocaleString('id-ID');
               return `${offset + idx + 1},"${dateStr}","=""${item.order_id || ''}""","=""${item.barcode}""","${item.employee_name}","${item.shift}","${item.role}","${item.status}","${item.destination || ''}","${item.description || ''}"`;
            }).join('\n');

            accumulatedRows += (accumulatedRows ? '\n' : '') + batchRows;
            currentFileCount += data.length;

            const isLastBatch = (offset + FETCH_BATCH_SIZE >= totalRecords);

            if (currentFileCount >= FILE_SPLIT_LIMIT || isLastBatch) {
               const blob = new Blob(["No,Timestamp,ID Pesanan,Barcode,Staff,Shift,Role,Status,Destination,Description\n" + accumulatedRows], { type: 'text/csv;charset=utf-8;' });
               const url = URL.createObjectURL(blob);
               const link = document.createElement("a");
               link.href = url;
               const suffix = totalRecords > FILE_SPLIT_LIMIT ? `_Part${fileIndex}` : '';
               link.setAttribute("download", `OjolData_${filterDate}${suffix}.csv`);
               document.body.appendChild(link);
               link.click();
               document.body.removeChild(link);

               accumulatedRows = "";
               currentFileCount = 0;
               fileIndex++;
               await new Promise(resolve => setTimeout(resolve, 500));
            }
         }

         setExportOjolProgress(100);
         setTimeout(() => setIsExportingOjol(false), 800);
      } catch (err: any) { alert(`Export failed: ${getSafeErrorMessage(err)}`); setIsExportingOjol(false); }
   };

   const openQuickAdd = (type: 'SHIFT' | 'ROLE') => { setQuickAddType(type); setQuickAddValue(''); setIsQuickAddModalOpen(true); };

   const handleSaveQuickAdd = async () => {
      if (!quickAddValue.trim()) return;
      const table = quickAddType === 'SHIFT' ? 'app_shifts' : 'app_roles';
      const name = quickAddValue.trim();
      try {
         // Check for existence first (Case Insensitive)
         const { data: existing } = await supabase.from(table).select('name').ilike('name', name).maybeSingle();
         if (existing) {
            alert(`Gagal: Data '${existing.name}' sudah ada di database.`);
            return;
         }

         const { error } = await supabase.from(table).insert([{ name }]);
         if (error) {
            if (error.code === '42P01') {
               alert(`Table '${table}' does not exist. Please run the SQL setup script.`);
            } else if (error.code === '23505') {
               alert("This entry already exists.");
            } else {
               throw error;
            }
         } else {
            if (quickAddType === 'SHIFT') setAvailableShifts(prev => [...prev, name]);
            else setAvailableRoles(prev => [...prev, name]);
            setIsQuickAddModalOpen(false);
         }
      } catch (err: any) {
         alert(`Failed to save: ${getSafeErrorMessage(err)}`);
      }
   };

