   const handleSaveEmployee = async () => {
      if (!employeeNameInput.trim() && !isBulkEditMode) {
         setEmployeeError("Nama karyawan wajib diisi");
         return;
      }

      setIsSavingEmployee(true);
      setEmployeeError(null);

      try {
         const dailyTargetVal = employeeTargetInput ? parseInt(employeeTargetInput) : 0;

         if (isBulkEditMode && selectedEmployeeIds.length > 0) {
            // GRANULAR BULK EDIT LOGIC
            const updateData: any = {};

            if (bulkUpdateSelection.shift) updateData.shift = selectedShift || null;
            if (bulkUpdateSelection.target) updateData.daily_target = dailyTargetVal;
            if (bulkUpdateSelection.roles) updateData.allowed_roles = selectedRoles;

            if (Object.keys(updateData).length === 0) {
               setEmployeeError("Pilih minimal satu data yang ingin diubah (centang box).");
               setIsSavingEmployee(false);
               return;
            }

            const { error } = await supabase.from('employees').update(updateData).in('id', selectedEmployeeIds);
            if (error) throw error;

         } else {
            // SINGLE ADD/EDIT LOGIC - Force UPPERCASE name
            const payload = {
               name: employeeNameInput.trim().toUpperCase(),
               shift: selectedShift || null,
               allowed_roles: selectedRoles,
               daily_target: dailyTargetVal,
               active: true
            };

            if (editingEmployee) {
               const { error } = await supabase.from('employees').update(payload).eq('id', editingEmployee.id);
               if (error) throw error;
            } else {
               const { error } = await supabase.from('employees').insert([{ ...payload, pin: null }]);
               if (error) throw error;
            }
         }

         setIsEmployeeModalOpen(false);
         fetchEmployees();
         setSelectedEmployeeIds([]);
      } catch (err: any) {
         setEmployeeError(err.message || "Failed to save employee");
      } finally {
         setIsSavingEmployee(false);
      }
   };

   // --- SCAN KERANJANG COMPONENT LOGIC ---
