   const processBarcodeMatch = async (barcode: string) => {
      // Check match
      if (dbInternalBarcodes.includes(barcode)) {
         // MATCH!
         // 1. Delete from DB (cancelled_orders)
         setScanKeranjangInput(''); // Clear input immediately for speed

         try {
            const { error } = await supabase.from('cancelled_orders').delete().eq('barcode', barcode);
            if (error) throw error;

            // 2. Update Local State (Remove from list)
            setDbInternalBarcodes(prev => prev.filter(b => b !== barcode));
            setScanKeranjangStatus({ type: 'MATCH', msg: `DATA MATCH! ${barcode} dihapus.` });

         } catch (err: any) {
            setScanKeranjangStatus({ type: 'ERROR', msg: `Error deleting: ${err.message}` });
         }
         return true;
      }
      return false;
   };

   const handleScanKeranjangInput = async (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const val = e.target.value.toUpperCase();
      // Remove whitespace/newlines which some scanners add
      const cleanVal = val.replace(/[\n\r\s]+/g, '');

      setScanKeranjangInput(cleanVal);

      // Attempt real-time match
      if (cleanVal.length >= 5) {
         const matched = await processBarcodeMatch(cleanVal);

         // If not matched, show NO_MATCH status immediately
         if (!matched) {
            setScanKeranjangStatus({ type: 'NO_MATCH', msg: `DATA TIDAK COCOK! Harap Update Data Cancel.` });
         }
      }
   };

   const handleScanKeranjangKeyDown = async (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      // Allow enter to submit (for cases where real-time didn't catch it or for NO MATCH feedback)
      if (e.key === 'Enter') {
         e.preventDefault();
         const barcode = scanKeranjangInput.trim().toUpperCase();
         if (!barcode) return;

         const matched = await processBarcodeMatch(barcode);

         if (!matched) {
            // NO MATCH - Only show error on explicit Enter/Submit
            setScanKeranjangInput(''); // Clear to retry
            setScanKeranjangStatus({ type: 'NO_MATCH', msg: `DATA TIDAK COCOK! Harap update data cancel.` });
         }
      }
   };

   // Effects for auto-focus
   useEffect(() => {
      if (isScanKeranjangOpen && scanKeranjangInputRef.current) {
         setTimeout(() => scanKeranjangInputRef.current?.focus(), 100);
      }
   }, [isScanKeranjangOpen]);


