   // --- COMPARE LOGISTIK LOGIC ---
   const handleCompareLogistik = async () => {
      const isInternalReady = (internalSourceMode === 'UPLOAD' && compareInternalFile) || (internalSourceMode === 'DATABASE' && dbInternalBarcodes.length > 0);
      const isCourierReady = !!compareCourierFile;

      if (!isInternalReady || !isCourierReady) {
         alert("Mohon lengkapi data Internal & Kurir terlebih dahulu.");
         return;
      }

      setIsComparingLogistik(true);
      try {
         // Helper to read file to barcodes
         const readFileToBarcodes = async (file: File): Promise<string[]> => {
            return new Promise((resolve, reject) => {
               const reader = new FileReader();
               reader.onload = (e) => {
                  try {
                     const data = new Uint8Array(e.target?.result as ArrayBuffer);
                     const workbook = XLSX.read(data, { type: 'array' });
                     const worksheet = workbook.Sheets[workbook.SheetNames[0]];
                     // Simple JSON conversion
                     const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 }) as any[][];

                     // Find column index for 'AWB' or 'RESI' or 'BARCODE'
                     const headers = jsonData[0] || [];
                     let barcodeIdx = headers.findIndex((h: any) => {
                        const str = String(h).toUpperCase();
                        return str.includes('AWB') || str.includes('RESI') || str.includes('BARCODE') || str.includes('NO. RESP');
                     });

                     // Valid data rows
                     const barcodes: string[] = [];

                     if (barcodeIdx === -1) {
                        // Fallback: Check if file has only 1 column or assume 1st column
                        barcodeIdx = 0;
                     }

                     for (let i = 1; i < jsonData.length; i++) {
                        const row = jsonData[i];
                        if (row && row[barcodeIdx]) {
                           const val = String(row[barcodeIdx]).trim().toUpperCase();
                           const cleanVal = sanitizeAndPadBarcode(val);
                           if (cleanVal && cleanVal.length > 5) barcodes.push(cleanVal); // Basic filter
                        }
                     }
                     resolve(barcodes);
                  } catch (err) {
                     reject(err);
                  }
               };
               reader.readAsArrayBuffer(file);
            });
         };

         const [internalBarcodes, courierBarcodes] = await Promise.all([
            internalSourceMode === 'UPLOAD'
               ? readFileToBarcodes(compareInternalFile!)
               : Promise.resolve(dbInternalBarcodes),
            readFileToBarcodes(compareCourierFile!)
         ]);

         const courierSet = new Set(courierBarcodes);
         const missingInCourier = internalBarcodes.filter(b => !courierSet.has(b));

         // Remove duplicates from missing list
         const uniqueMissing = Array.from(new Set(missingInCourier));
         const uniqueInternal = new Set(internalBarcodes);

         setCompareResult({
            missingInCourier: uniqueMissing,
            foundCount: internalBarcodes.length - missingInCourier.length,
            totalInternal: internalBarcodes.length,
            // Actually let's use unique counts for stats to be more accurate
            totalCourier: courierSet.size,
            internalBarcodes: internalBarcodes,
            courierBarcodes: courierBarcodes // New field for saving
         });

         // AUTO SAVE TO DB
         // We pass data directly because state update is async
         setIsSavingCompareData(true);
         try {
            await Promise.all([
               saveMissingScansToDb(uniqueMissing as string[], false),
               saveCourierLogsToDb(courierBarcodes, compareCourierFile.name, false)
            ]);
            setCompareSuccessToast("Perbandingan selesai! Data otomatis disimpan ke database.");
         } catch (saveErr) {
            console.error("Auto-save failed", saveErr);
            setCompareSuccessToast("Perbandingan selesai, namun gagal menyimpan otomatis.");
         } finally {
            setIsSavingCompareData(false);
         }

      } catch (err: any) {
         alert("Gagal memproses file: " + err.message);
      } finally {
         setIsComparingLogistik(false);
      }
   };

   // --- COMPARE LOGISTIK: DB FETCH ---
   const fetchTodayCancelledGtl = async () => {
      setIsFetchingDbInternal(true);
      try {
         // Get Today's Range in UTC ISO Standard
         const now = new Date();
         const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0);
         const endOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);

         // Helper for GTL check
         const { data, error } = await supabase
            .from('cancelled_orders')
            .select('barcode')
            .gte('cancelled_at', startOfDay.toISOString())
            .lte('cancelled_at', endOfDay.toISOString())
            .ilike('barcode', 'GTL%'); // Case insensitive GTL%

         if (error) throw error;

         const barcodes = data?.map(d => d.barcode) || [];
         setDbInternalBarcodes(barcodes);

         if (barcodes.length > 0) {
            setCompareSuccessToast(`${barcodes.length} data Cancel (GTL) hari ini berhasil diambil!`);
            // Auto-dismiss toast after 3 seconds
            setTimeout(() => setCompareSuccessToast(null), 3000);
         } else {
            alert("Tidak ada data Cancel dengan awalan GTL untuk hari ini.");
         }

      } catch (err: any) {
         console.error("Error fetching cancel data:", err);
         alert("Gagal mengambil data cancel: " + err.message);
      } finally {
         setIsFetchingDbInternal(false);
      }
   };

