   const saveMissingScansToDb = async (customData?: string[], switchTab: boolean = true) => {
      const dataToSave = customData || compareResult?.missingInCourier;
      if (!dataToSave || dataToSave.length === 0) return;

      setIsSavingCompareData(true);
      try {
         const batchId = crypto.randomUUID();
         const payload = dataToSave.map(awb => ({
            batch_id: batchId,
            awb: awb,
            description: 'Missing in Courier Data',
            processed_by: currentAdmin?.username || 'admin'
         }));

         const { error } = await supabase
            .from('compare_missing_scans')
            .insert(payload);

         if (error) throw error;

         if (switchTab) {
            setCompareSuccessToast("Data AWB Hilang berhasil disimpan!");
            setActiveCompareTab('MISSING_HISTORY');
            fetchMissingScans();
         } else {
            // For auto-save, just refresh background data but don't toast/switch yet or maybe distinct toast
            fetchMissingScans();
         }

      } catch (err: any) {
         console.error("Error saving missing scans:", err);
         if (switchTab) alert("Gagal menyimpan data: " + err.message);
      } finally {
         setIsSavingCompareData(false);
      }
   };

   const saveCourierLogsToDb = async (customData?: string[], customSourceName?: string, switchTab: boolean = true) => {
      const dataToSave = customData || compareResult?.courierBarcodes;
      if (!dataToSave || dataToSave.length === 0) return;

      setIsSavingCompareData(true);
      try {
         const batchId = crypto.randomUUID();
         const chunkSize = 100;
         const sourceName = customSourceName || compareCourierFile?.name || 'Unknown File';
         let processedCount = 0;

         const chunks = [];
         for (let i = 0; i < dataToSave.length; i += chunkSize) {
            const chunk = dataToSave.slice(i, i + chunkSize).map(awb => ({
               batch_id: batchId,
               awb: awb,
               status: 'COURIER_SOURCE',
               courier_source: sourceName,
               processed_by: currentAdmin?.username || 'admin'
            }));
            chunks.push(chunk);
         }

         for (const chunk of chunks) {
            const { error } = await supabase.from('compare_courier_logs').insert(chunk);
            if (error) throw error;
            processedCount += chunk.length;
         }

         if (switchTab) {
            setCompareSuccessToast(`Berhasil menyimpan ${processedCount} data kurir!`);
            setActiveCompareTab('COURIER_HISTORY');
            fetchCourierLogs();
         } else {
            fetchCourierLogs();
         }

      } catch (err: any) {
         console.error("Error saving courier logs:", err);
         if (switchTab) alert("Gagal menyimpan data kurir: " + err.message);
      } finally {
         setIsSavingCompareData(false);
      }
   };

