                                                      packingViewLayout === 'AUTO'
                                                         ? 'bg-white dark:bg-gray-700 text-blue-600 dark:text-blue-400 shadow-sm'
                                                         : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
